// 中国近现代史纲要专项全量选择题 (220题)
var SHIGANG_CHOICE_DATA = (typeof window !== 'undefined' ? (window.SHIGANG_CHOICE_DATA = [{"id":"sg-1","globalId":1,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":1,"question":"19世纪末，在帝国主义列强瓜分中国的狂潮中提出“门户开放”政策的国家是（ ）。","options":["美国","日本","俄国","德国"],"answer":0,"answerLetter":"A","explain":"19世纪末，各国在中国划分势力范围时，美国忙于美西战争，无暇顾及中国。美西战争结束后，美 国为分享侵略权益，于1899年向英、俄、德、日、意、法六国提出“门户开放”政策。答案选A。"},{"id":"sg-2","globalId":2,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":2,"question":"太平天国后期，洪仁玕提出的改革与建设方案是（ ）。","options":["（原道觉世训》","《十救天条）","《天朝田亩制度》","《资政新篇》"],"answer":3,"answerLetter":"D","explain":"《原道觉世训》《十救天条》是太平天国早期洪秀全等人的著述；《天朝田亩制度》是太平天国前 期颁布的纲领性文件；而《资政新篇》是太平天国后期洪仁玕提出的改革与建设方案，具有鲜明的资本主义 色彩。"},{"id":"sg-3","globalId":3,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":3,"question":"中共十三大明确将党在社会主义初级阶段的基本路线概括为（ ）。","options":["“一个中心，两个基本点”","“四个坚持”","一手抓物质文明，一手抓精神文明","建设中国特色社会主义经济、政治和文化"],"answer":0,"answerLetter":"A","explain":"中共十三大明确提出党在社会主义初级阶段的基本路线，即领导和团结全国各族人民，以经济建设 为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的 社会主义现代化国家而奋斗，简称为“一个中心，两个基本点” 。"},{"id":"sg-4","globalId":4,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":4,"question":"1839年组织编写成《四洲志》，向中国人介绍西方情况的是（ ）。","options":["林则徐","魏源","马建忠","郑观应"],"answer":0,"answerLetter":"A","explain":"林则徐是近代中国睁眼看世界的第一人，1839 年他组织编译《四洲志》，介绍西方情况。魏源在《 四洲志》基础上编成《海国图志》；马建忠、郑观应是 19 世纪 70 - 90 年代的早期维新思想家。答案 ：A。"},{"id":"sg-5","globalId":5,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":5,"question":"1938年6月间，毛泽东发表的系统论述抗日战争特点.前途和发展规律的著作是（ ）。","options":["论反对日本帝国主义的策略","抗日救国十大纲领.","论持久战","对日寇的最后一站"],"answer":2,"answerLetter":"C","explain":"1938 年 6 月毛泽东发表《论持久战》，系统阐明了抗日战争的特点、前途和发展规律，为全国抗 战指明方向。A 选项《论反对日本帝国主义的策略》主要论述建立抗日民族统一战线；B 选项《抗日救国十 大纲领》主要是全面抗战路线相关；D 选项《对日寇的最后一战》发布于抗战即将胜利时。答案：C。"},{"id":"sg-6","globalId":6,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":6,"question":"2002年2月，江泽民在广东考察工作时提出了（ ）。","options":["“三讲”教育的要求","“八个坚持，八个反对”的要求","“三个代表”重要思想","以“八荣八耻”为主要内容的社会主义荣辱观"],"answer":2,"answerLetter":"C","explain":"2000 年 2 月，江泽民在广东考察工作时，首次提出“三个代表”重要思想 。“三讲”教育是 1995 年提出；“八个坚持，八个反对”是 2001 年提出；以“八荣八耻”为主要内容的社会主义荣辱观是 2006 年提出。答案选C。"},{"id":"sg-7","globalId":7,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":7,"question":"中共十四大明确提出，我国经济体制改革的目标是建立（ ）。","options":["社会主义市场经济体制","市场为主、计划为辅的经济体制","社会主义计划经济体制","社会主义有计划的商品经济体制"],"answer":0,"answerLetter":"A","explain":"1992 年中共十四大明确提出我国经济体制改革的目标是建立社会主义市场经济体制 。"},{"id":"sg-8","globalId":8,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":8,"question":"1851年，中国爆发的一场伟大的农民战争是（ ）。","options":["三元里人民抗英斗争","太平天国运动","台湾高山族人民抗日斗争","义和团运动"],"answer":1,"answerLetter":"B","explain":"1851 年洪秀全领导发动金田起义，太平天国运动爆发，它是一场伟大的农民战争。A 选项三元里人 民抗英斗争发生于 1841 年；C 选项台湾高山族人民抗日斗争主要是在《马关条约》割让台湾后；D 选项义 和团运动兴起于 19 世纪末。"},{"id":"sg-9","globalId":9,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":9,"question":"1939年1月，国民党制定“防共.限共.溶共.反共”方针的会议是（ ）。","options":["五届三中全会","五届四中全会","五届五中全会","五届六中全会"],"answer":2,"answerLetter":"C","explain":"1939年1月，国民党五届五中全会决定成立“防共委员会”，确定了“防共、限共、溶共、反共”的 方针。这一方针标志着国民党由片面抗战逐步转变为消极抗战、积极反共。答案选C。"},{"id":"sg-10","globalId":10,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":10,"question":"2005年，第十届全国人民代表大会第三次会议通过的法律是（ ）。","options":["《香港特别行政区基本法》","《澳门特别行政区基本法》","《国家安全法》","《反分裂国家法》"],"answer":3,"answerLetter":"D","explain":"2005 年第十届全国人民代表大会第三次会议通过《反分裂国家法》，旨在反对和遏制“台独”分裂 势力分裂国家，促进祖国和平统一 。A 选项《香港特别行政区基本法》于 1990 年通过；B 选项《澳门特别 行政区基本法》于 1993 年通过；C 选项现行《国家安全法》是 2015 年通过 。答案：D 。"},{"id":"sg-11","globalId":11,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":11,"question":"中共中央明确提出“和平、民主、团结”的口号是（ ）。","options":["1943年8月25日","1944年8月25日","1945年8月25日","1946年8月25日"],"answer":2,"answerLetter":"C","explain":"1945 年 8 月 25 日，中共中央在对时局的宣言中明确提出“和平、民主、团结”的口号。答案 ：C。"},{"id":"sg-12","globalId":12,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":12,"question":"“文化大革命”结束的主要标志是（ ）。","options":["林彪反革命集团的覆灭","邓小平的复出","江青反革命集团的垮台","“天安门事件”的平反"],"answer":2,"answerLetter":"C","explain":"答案：C“文化大革命”结束的主要标志是江青反革命集团的垮台，这标志着“文化大革命”的正式 结束。因此，正确答案为C。"},{"id":"sg-13","globalId":13,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":13,"question":"1937年8月，中国共产党制定《抗日救国十大纲领》的会议是（ ）。","options":["六届五中全会","瓦窑堡会议","洛川会议","六届六中全会"],"answer":2,"answerLetter":"C","explain":"1937年8月，中共中央在陕北洛川召开政治局扩大会议，制定了《抗日救国十大纲领》，强调要打倒 日本帝国主义，关键在于使已经发动的抗战成为全面的全民族的抗战。A选项六届五中全会1934 年召开；B选 项瓦窑堡会议1935年召开，提出抗日民族统一战线政策；D选项六届六中全会1938年召开。"},{"id":"sg-14","globalId":14,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":14,"question":"19世纪60年代到90年代，洋务派兴办洋务事业的指导思想是（ ）。","options":["师夷长技以制夷","中学为体，西学为用","物竞天择，适者生存","变法维新，救亡图存"],"answer":1,"answerLetter":"B","explain":"“师夷长技以制夷”是魏源《海国图志》提出的，早于洋务运动，A 不符；“中学为体，西学为用 ”是洋务派兴办洋务事业的指导思想，强调以中国封建纲常伦理为根本，采用西方先进科技，B 正确；“物 竞天择，适者生存”是严复翻译《天演论》宣传的思想，非洋务派指导思想，C 不符；“变法维新，救亡图 存”是维新派主张，D 不符。"},{"id":"sg-15","globalId":15,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":15,"question":"日本在甲午战争后迫使清政府签订了（ ）。","options":["《天津条约》","《北京条约》","《马关条约》","《辛丑条约》"],"answer":2,"answerLetter":"C","explain":"甲午战争清政府战败后，1895 年被迫与日本签订《马关条约》。A 选项《天津条约》是第二次鸦片 战争签订；B 选项《北京条约》也是第二次鸦片战争签订；D 选项《辛丑条约》是八国联军侵华后签订。答 案：C。"},{"id":"sg-16","globalId":16,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":16,"question":"中共十八大提出，我国到2020年的奋斗目标是（ ）。","options":["实现“四个现代化”","基本实现现代化","全面建设小康社会","全面建成小康社会"],"answer":3,"answerLetter":"D","explain":"中共十八大提出到2020年全面建成小康社会的奋斗目标。“四个现代化”是过去提出的概念；基本 实现现代化是2035年目标；之前是全面建设小康社会阶段，十八大强调要建成。"},{"id":"sg-17","globalId":17,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":17,"question":"《共产党宣言》第一个中文全译本的译者是（ ）。","options":["李大钊","陈独秀","陈望道","毛泽东"],"answer":2,"answerLetter":"C","explain":"1920年8月，陈望道翻译的《共产党宣言》第一个中文全译本在上海出版。李大钊、陈独秀、毛泽东 都不是《共产党宣言》第一个中文全译本译者。答案选C。"},{"id":"sg-18","globalId":18,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":18,"question":"1938年，毛泽东发表的系统阐述抗日战争特点、前途和发展规律的著作是（ ）。","options":["《论反对日本帝国主义的策略》","《论持久战》","《论新阶段》","《论联合政府》"],"answer":1,"answerLetter":"B","explain":"1938 年毛泽东发表《论持久战》，系统阐述了抗日战争的特点、前途和发展规律，有力批驳了“亡 国论”和“速胜论”。A 选项《论反对日本帝国主义的策略》主要是论述抗日民族统一战线；C 选项《论新 阶段》是 1938 年提出“马克思主义中国化”；D 选项《论联合政府》是 1945 年中共七大上的报告。答案 ：B 。"},{"id":"sg-19","globalId":19,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":19,"question":"19世纪末，梁启超撰写的宣传变法维新主张的著作是（ ）。","options":["《新学伪经考》","《人类公理》","《仁学》","《变法通义》"],"answer":3,"answerLetter":"D","explain":"A选项《新学伪经考》是康有为著作；B选项《人类公理》也是康有为作品；C选项《仁学》是谭嗣同 著作；D选项《变法通义》是梁启超宣传变法维新主张的著作 。"},{"id":"sg-20","globalId":20,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":20,"question":"台湾人民为反抗国民党当局暴政而举行“二二八”起义的时间是（ ）。","options":["1945年","1946年","1947年","1948年"],"answer":2,"answerLetter":"C","explain":"“二二八”起义发生于1947年2月28日，是台湾人民反对国民党统治的重要起义。答案选C。"},{"id":"sg-21","globalId":21,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":21,"question":"《中国人民政协商会议共同纲领》最基本、最核心的内容是规定了新中国的（ ）。","options":["基本民族政策","国体和政体","经济工作方针","外交工作原则"],"answer":1,"answerLetter":"B","explain":"《中国人民政治协商会议共同纲领》规定了新中国的国体和政体，这是其最基本、最核心的内容 ，国体和政体决定着国家的性质等根本问题，其他政策方针等都以此为基础展开。"},{"id":"sg-22","globalId":22,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":22,"question":"1938年，中国共产党制定《抗日救国十大纲领》的重要会议是（ ）。","options":["瓦窑堡会议","洛川会议","中共六届六中会议","中共六届七中会议"],"answer":1,"answerLetter":"B","explain":"1937年8月，中共中央在陕北洛川召开政治局扩大会议，制定了《抗日救国十大纲领》 ，强调要打 倒日本帝国主义，关键在于使已经发动的抗战成为全面的全民族的抗战。"},{"id":"sg-23","globalId":23,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":23,"question":"太平天国失败的根本原因是（ ）。","options":["没有科学理论的指导","缺乏先进阶级的领导","无法长期保持领导集团的团结","不能正确对待传统文化"],"answer":1,"answerLetter":"B","explain":"太平天国运动是农民阶级领导的运动，农民阶级不是先进生产力的代表，具有自身局限性，这是导 致其失败的根本原因，即缺乏先进阶级的领导。A、C、D选项也是失败原因，但不是根本原因。"},{"id":"sg-24","globalId":24,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":24,"question":"1853年，太平天国定都天京后颁布的纲领性文件是（ ）。","options":["《原道觉世训》","《十款天条》","《天朝田亩制度》","《资政新篇》"],"answer":2,"answerLetter":"C","explain":"1853 年太平天国定都天京后颁布《天朝田亩制度》，它是太平天国的纲领性文件。A 选项《原道觉 世训》是洪秀全早期著作；B 选项《十款天条》是拜上帝会的基本准则；D 选项《资政新篇》1859 年提出。 答案：C 。"},{"id":"sg-25","globalId":25,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":25,"question":"太平天国由盛到衰的转折点是（ ）。","options":["长沙战役","安庆失守","天京事变","北伐受挫"],"answer":2,"answerLetter":"C","explain":"天京事变是太平天国领导集团内部自相残杀的严重事件，它严重削弱了太平天国的领导和军事力量 ，成为太平天国由盛转衰的转折点。答案选C。"},{"id":"sg-26","globalId":26,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":26,"question":"中共中央通过<关于建国以来党的若干历史问题的决议》的会议是（ ）。","options":["十一届三中全会","十一届六中全会","十二届三中全会","十二届六中全会"],"answer":1,"answerLetter":"B","explain":"1981 年 6 月，中共十一届六中全会通过了《关于建国以来党的若干历史问题的决议》，对新中国 成立以来党的重大历史问题特别是“文化大革命”、毛泽东的历史地位及功过是非和毛泽东思想基本内容与 指导意义作了总结和评价。答案：B 。"},{"id":"sg-27","globalId":27,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":27,"question":"1941年3月，在抗日民主运动中成立的民主党派是（ ）。","options":["中国国民党临时行动委员会","中国青年党","中国国家社会党","中国民主政团同盟"],"answer":3,"answerLetter":"D","explain":"1941 年 3 月 19 日，中国民主政团同盟在重庆秘密成立。而中国国民党临时行动委员会是 1930 年成立；中国青年党、中国国家社会党成立时间也并非 1941 年 3 月。答案：D。"},{"id":"sg-28","globalId":28,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":28,"question":"2005年3月，十届全国人大三次会议通过的法律是（ ）。","options":["《反分裂国家法》","《国家安全法》","《香港特别行政区基本法》","《澳门特别行政区基本法》"],"answer":0,"answerLetter":"A","explain":"2005 年 3 月十届全国人大三次会议通过《反分裂国家法》，旨在反对和遏制“台独”分裂势力分 裂国家，促进祖国和平统一。而《国家安全法》有不同时期的版本但并非此次会议通过；《香港特别行政区 基本法》1990 年通过；《澳门特别行政区基本法》1993 年通过。"},{"id":"sg-29","globalId":29,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":29,"question":"谭嗣同在戊戌维新时期撰写的宣传变法维新主张的著作是（ ）。","options":["《新学伪经考》","《变法通义》","《日本变政考》","《仁学》"],"answer":3,"answerLetter":"D","explain":"《仁学》是谭嗣同的著作 。A选项《新学伪经考》是康有为的；B选项《变法通义》是梁启超的 ；C选项《日本变政考》是康有为的。"},{"id":"sg-30","globalId":30,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":30,"question":"中国的社会生产力在改革开放后迅速发展，到2006年经济总量已居世界（ ）。","options":["第二位","第三位","第四位","第五位"],"answer":2,"answerLetter":"C","explain":"2006 年中国经济总量居世界第四位。2010 年中国经济总量超越日本成为世界第二。所以 2006 年 应选第四位。"},{"id":"sg-31","globalId":31,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":31,"question":"20世纪初，在民主革命思想传播中发表《警世钟》的是（ ）。","options":["章炳麟","邹容","陈天华","孙中山"],"answer":2,"answerLetter":"C","explain":"陈天华在民主革命思想传播中发表了《警世钟》等著作，以通俗的语言宣传革命思想。章炳麟的代 表作是《驳康有为论革命书》，邹容的是《革命军》，孙中山主要是领导革命实践等。"},{"id":"sg-32","globalId":32,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":32,"question":"1945年8月至10月，国共双方举行了商讨和平建国方针的（ ）。","options":["重庆谈判","西安谈判","南京谈判","北平谈判"],"answer":0,"answerLetter":"A","explain":"1945 年 8 月至 10 月，为避免内战、争取和平，国共双方在重庆进行了关于和平建国的谈判，即 重庆谈判 。西安谈判是为解决西安事变；南京谈判是 1946 年；北平谈判是 1949 年 。所以符合时间和主 题的是重庆谈判。答案：A 。"},{"id":"sg-33","globalId":33,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":33,"question":"20世纪初，资产阶级革命派与改良派论战的焦点是（ ）。","options":["要不要变法","要不要建立民主共和国","要不要社会革命","要不要以革命手段推翻清政府"],"answer":3,"answerLetter":"D","explain":"20世纪初，资产阶级革命派与改良派论战主要围绕三个方面，其中要不要以革命手段推翻清王朝是 双方论战的焦点。改良派主张温和变革，革命派主张以革命推翻清政府。"},{"id":"sg-34","globalId":34,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":34,"question":"文化大革命”的导火线是（ ）。","options":["《评新编历史剧<海瑞罢官>》的发表","上海“一月革命”夺权斗争","围困中南海事件","《炮打司令部——我的一张大字报》的发表"],"answer":0,"answerLetter":"A","explain":"答案：A“文化大革命”的导火线是姚文元1965年11月10日在《文汇报》上发表的《评新编历史剧 (海瑞罢官)》。这篇文章被人们称为“文化大革命”的“导火线”、“引火物”。"},{"id":"sg-35","globalId":35,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":35,"question":"中国共产党开展的延安整风运动最主要的任务是（ ）。","options":["反对主观主义","反对宗派主义","反对官僚主义","反对党八股"],"answer":0,"answerLetter":"A","explain":"延安整风运动的主要内容是反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整 顿文风。其中，反对主观主义是最主要任务，因为主观主义是中国共产党内反复出现“左”、右倾错误的思 想认识根源。"},{"id":"sg-36","globalId":36,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":36,"question":"1911年，在保路运动中规模最大、斗争最激烈的省份是（ ）。","options":["湖北","湖南","广东","四川"],"answer":3,"answerLetter":"D","explain":"1911 年的保路运动中，四川人民发动了武装起义，成立了保路同志军，与清军进行了激烈战斗，其 规模和斗争激烈程度远超其他省份。"},{"id":"sg-37","globalId":37,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":37,"question":"1911年夏，湖北、湖南、广东和四川爆发的民众斗争运动是（ ）。","options":["拒俄运动","拒法运动","保路运动","立宪运动"],"answer":2,"answerLetter":"C","explain":"1911 年 5 月，清政府将已归民间商办的川汉、粤汉铁路收归“国有”，随即出卖给英、法、德、 美 4 国银行团，激起湘、鄂、粤、川等省人民的强烈反对，掀起了保路运动。答案：C。"},{"id":"sg-38","globalId":38,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":38,"question":"1946年，中共决定将减租减息政策改为实现“耕者有其田”政策的文件是（ ）。","options":["《井冈山土地法》","《兴国土地法》","《关于清算、减租及土地问题的指示》","《中国土地法大纲》"],"answer":2,"answerLetter":"C","explain":"答案：C1946年5月4日，中共中央发出《关于清算、减租及土地问题的指示》，决定将党在抗日战争 时期实行的减租减息政策改变为实现“耕者有其田”的政策。"},{"id":"sg-39","globalId":39,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":39,"question":"标志着中国民族资产阶级开始登上政治舞台的运动是（ ）。","options":["洋务运动","戊戌维新运动","国会请愿运动","保路运动"],"answer":1,"answerLetter":"B","explain":"戊戌维新运动是一场资产阶级性质的政治改良运动，民族资产阶级作为新的政治力量开始登上历史 舞台。洋务运动是地主阶级洋务派发起，旨在维护封建统治；国会请愿运动是立宪派发起；保路运动是群众 性的反帝爱国运动。"},{"id":"sg-40","globalId":40,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":40,"question":"我国对资本主义工商业进行社会主义改造所实行的高级形式的国家资本主义是（ ）。","options":["加工订货","统购统销","经销代销","公私合营"],"answer":3,"answerLetter":"D","explain":"国家资本主义有低级和高级两种形式。低级形式的国家资本主义如加工订货、统购统销、经销代销 等；高级形式的国家资本主义是公私合营，公私合营又分个别企业的公私合营和全行业的公私合营。所以答 案选高级形式的公私合营。"},{"id":"sg-41","globalId":41,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":41,"question":"中国共产党确定第一次国共合作和建立革命统一战线方针的会议是（ ）。","options":["中共三大","中共四大","中共五大","中共六大"],"answer":0,"answerLetter":"A","explain":"中共三大的中心议题是讨论全体共产党员加入国民党，建立国共合作统一战线的问题，正式确定了 建立国共合作统一战线的策略方针。中共四大主要是提出了无产阶级在民主革命中的领导权问题等；中共五 大主要是批评陈独秀的右倾错误等；中共六大主要是在大革命失败后，总结大革命失败教训，正确分析革命 性质等。所以答案是中共三大。"},{"id":"sg-42","globalId":42,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":42,"question":"1913年，孙中山领导革命党人发动的反对袁世凯的斗争是（ ）。","options":["“二次革命”","护国战争","护法战争","北伐战争"],"answer":0,"answerLetter":"A","explain":"1913 年，袁世凯派人刺杀宋教仁，孙中山等发动“二次革命”讨袁。护国战争是 1915 年反对袁世 凯称帝；护法战争是 1917 - 1918 年为维护《临时约法》等；北伐战争是 1926 - 1927 年国共合作推翻北 洋军阀统治。所以 1913 年孙中山领导反对袁世凯的斗争是“二次革命”。"},{"id":"sg-43","globalId":43,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":43,"question":"1946年6月，国民党当局制造了镇压上海人民团体联合会请愿团的（ ）。","options":["五卅惨案","校场口惨案","下关惨案","五二零惨案"],"answer":2,"answerLetter":"C","explain":"1946 年 6 月，上海人民团体联合会组成请愿团，赴南京向国民党当局呼吁和平。请愿团到达南京 下关车站时，遭到国民党特务围攻毒打，这就是下关惨案。 A 选项五卅惨案发生于 1925 年 5 月 30 日 ，与题干时间 1946 年不符。 B 选项校场口惨案是 1946 年 2 月 10 日，在重庆校场口发生的破坏政协决 议、反对内战的事件，与上海人民团体联合会请愿团无关。 D 选项五二零惨案是 1947 年 5 月 20 日，国 民党反动派对爱国学生进行镇压的事件，时间也不符。"},{"id":"sg-44","globalId":44,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":44,"question":"中国共产党首次完整概括党在社会主义初级阶段的基本路线是在（ ）。","options":["中共十一大","中共十二大","中共十三大","中共十四大"],"answer":2,"answerLetter":"C","explain":"中共十三大首次完整概括了党在社会主义初级阶段的基本路线，即“一个中心、两个基本点”。答 案：C"},{"id":"sg-45","globalId":45,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":45,"question":"1920年，陈独秀等建立的中国共产党早期组织是（ ）。","options":["北京共产主义小组","上海共产主义小组","武汉共产主义小组","广州共产主义小组"],"answer":1,"answerLetter":"B","explain":"1920 年 8 月，陈独秀、李达等在上海建立了中国第一个共产党早期组织——上海共产主义小组。 这是各地共产主义小组中成立最早的，对其他地方党组织的建立起到引领示范作用。"},{"id":"sg-46","globalId":46,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":46,"question":"1946年6月，国民党军队挑起全国内战的起点是（ ）。","options":["重点进攻陕甘宁地区","重点进攻山东解放区","大举围攻东北解放区","大举围攻中原解放区"],"answer":3,"answerLetter":"D","explain":"1946 年 6 月 26 日，国民党军队以大举围攻中原解放区为起点，挑起了全国性内战。重点进攻陕 甘宁和山东解放区是在 1947 年，且进攻东北解放区也不符合挑起全国内战起点这一表述。"},{"id":"sg-47","globalId":47,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":47,"question":"邓小平首次明确提出必须坚持“四项基本原则”是在（ ）。","options":["1976年10月","1978年12月","1979年3月","1981年6月"],"answer":2,"answerLetter":"C","explain":"1979年3月，邓小平在理论工作务虚会上首次明确提出必须坚持“四项基本原则” 。"},{"id":"sg-48","globalId":48,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":48,"question":"中国共产党于1927年召开的确定土地革命和武装斗争方针的会议是（ ）。","options":["古田会议","遵义会议","八七会议","洛川会议"],"answer":2,"answerLetter":"C","explain":"八七会议是大革命失败以后，在关系党和革命事业前途和命运的严重危机时刻，中共中央召开的紧 急会议，确定了土地革命和武装斗争方针。古田会议强调党对军队的绝对领导；遵义会议主要解决军事和组 织问题，确立以毛泽东为代表的马克思主义的正确路线在中共中央的领导地位；洛川会议制定全面抗战路线 。答案选C。"},{"id":"sg-49","globalId":49,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":49,"question":"1947年，国民党宪警制造的镇压爱国学生运动的惨案是（ ）。","options":["五卅惨案","校场口惨案","下关惨案","五二O惨案"],"answer":3,"answerLetter":"D","explain":"1947年5月20日，南京、上海、苏州、杭州等地学生举行大规模的反饥饿、反内战、反迫害（“反饥 饿、反内战、反迫害”简称“三反”）示威游行，遭到国民党宪警镇压，造成“五二O”惨案。A选项五卅惨 案发生于1925年；B选项校场口惨案发生于1946年；C选项下关惨案发生于1946年。"},{"id":"sg-50","globalId":50,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":50,"question":"第一次国共合作建立后，全国范围大革命风暴兴起的标志是（ ）。","options":["护法战争","五四运动","北伐战争","五卅运动"],"answer":3,"answerLetter":"D","explain":"五卅运动中，工人罢工、学生罢课、商人罢市，反帝爱国运动迅速扩展到全国，是大革命风暴兴起 的标志。护法战争与第一次国共合作无关；五四运动时第一次国共合作尚未建立；北伐战争是大革命高潮的 到来，而非兴起标志。"},{"id":"sg-51","globalId":51,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":51,"question":"戊戌维新时期，谭嗣同撰写的宣传变法维新主张的著作是（ ）。","options":["《新学伪经考》","《变法通义》","《日本变政考》","《仁学》"],"answer":3,"answerLetter":"D","explain":"《新学伪经考》是康有为著作；《变法通义》是梁启超著作；《日本变政考》是康有为进呈光绪帝 的书籍；而《仁学》是谭嗣同撰写的宣传变法维新主张的著作。答案：D。"},{"id":"sg-52","globalId":52,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":52,"question":"1947年，台湾人民举行的反对国民党反动统治的大规模斗争是（ ）。","options":["黑旗军起义","一二·一运动","二二八起义","一二·三〇运动"],"answer":2,"answerLetter":"C","explain":"1947年2月28日，台湾人民为反抗国民党当局的暴政、抗议反动军警屠杀市民，举行大规模示威游行 ，即“二二八起义” 。黑旗军起义是清末刘永福领导的武装斗争；一二·一运动是1945年昆明学生发动的反 内战、争民主运动；一二·三〇运动是1946年12月30日，为抗议驻华美军暴行，北平学生发起的运动。答案 ：C"},{"id":"sg-53","globalId":53,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":53,"question":"戊戌维新时期，维新派在上海创办的影响较大的报刊是（ ）。","options":["《时务报》","《国闻报》","《湘报》","《万国公报》"],"answer":0,"answerLetter":"A","explain":"戊戌维新时期，维新派在各地创办了众多报刊来宣传变法思想。其中《时务报》是在上海创办且影 响较大。《国闻报》在天津，《湘报》在湖南，《万国公报》虽有重要意义但创办地不是上海。答案：A。"},{"id":"sg-54","globalId":54,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":54,"question":"中国开始进入半殖民地半封建社会是在（ ）。","options":["第一次鸦片战争后","第二次鸦片战争后","中日甲午战争后","八国联军侵华战争后"],"answer":0,"answerLetter":"A","explain":"第一次鸦片战争后，英国强迫清政府签订《南京条约》等一系列不平等条约，破坏了中国的主权和 领土完整等，中国开始沦为半殖民地半封建社会。第二次鸦片战争使半殖民地半封建化程度加深；甲午战争 后大大加深；八国联军侵华后完全沦为。答案：A。"},{"id":"sg-55","globalId":55,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":55,"question":"第一次鸦片战争结束后，美国迫使清政府订立的不平等条约是（ ）。","options":["《南京条约》","《望厦条约》","《黄埔条约》","《理挥条约》"],"answer":1,"answerLetter":"B","explain":"《南京条约》是英国与清政府签订的；《黄埔条约》是法国与清政府签订的；不存在《理挥条约》 。而《望厦条约》是第一次鸦片战争后美国强迫清政府签订的不平等条约 。"},{"id":"sg-56","globalId":56,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":56,"question":"1925年至1926年间，中国工人坚持16个月之久的罢工斗争是（ ）。","options":["香港海员罢工","安源路矿工人罢工","京汉铁路工人罢工","省港罢工"],"answer":3,"answerLetter":"D","explain":"省港罢工从1925年6月开始，到1926年10月结束，坚持了16个月之久。香港海员罢工1922 年；安源 路矿工人罢工1922年；京汉铁路工人罢工1923年。"},{"id":"sg-57","globalId":57,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":57,"question":"1948年11月至1949年1月，担任淮海战役总前委书记的是（ ）。","options":["邓小平","刘伯承","陈毅","粟裕"],"answer":0,"answerLetter":"A","explain":"淮海战役总前委由刘伯承、陈毅、邓小平、粟裕、谭震林组成，邓小平任总前委书记 。"},{"id":"sg-58","globalId":58,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":58,"question":"国民党四大家族官僚资本的性质是（ ）。","options":["私人垄断资本主义","封建的买办的国家垄断资本主义","私人资本主义","国家资本主义"],"answer":1,"answerLetter":"B","explain":"国民党四大家族官僚资本是在国民政府统治时期，凭借国家政权，依附帝国主义，与封建势力勾结 而形成，具有封建性、买办性和国家垄断性。答案：B 。"},{"id":"sg-59","globalId":59,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":59,"question":"新中国第一次正式提出实现“四个现代化”奋斗目标的会议是（ ）。","options":["第一届全国人民代表大会","第二届全国人民代表大会","第三届全国人民代表大会","第四届全国人民代表大会"],"answer":2,"answerLetter":"C","explain":"1964 年 12 月第三届全国人民代表大会第一次会议上，周恩来在政府工作报告中首次正式提出要在 不太长的历史时期内，把我国建设成为一个具有现代农业、现代工业、现代国防和现代科学技术的社会主义 强国，即实现“四个现代化”的奋斗目标。答案：C 。"},{"id":"sg-60","globalId":60,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":60,"question":"1927年，中国共产党确定土地革命和武装反抗国民党反动派方针的会议是（ ）。","options":["八七会议","古田会议","赣南会议","十二月会议"],"answer":0,"answerLetter":"A","explain":"1927 年 8 月 7 日，中共中央在湖北汉口召开紧急会议，即“八七会议”，确定了土地革命和武装 反抗国民党反动派的总方针。古田会议主要是解决新型人民军队建设问题；赣南会议是 1931 年召开，对根 据地和红军发展有重要影响，但主题并非确定土地革命和武装反抗方针；十二月会议是 1947 年召开，主要 讨论解放战争转入战略进攻后的一系列问题。答案：A 。"},{"id":"sg-61","globalId":61,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":61,"question":"中华人民共和国恢复在联合国合法席位的时间是（ ）。","options":["1949年","1966年","1971年","1978年"],"answer":2,"answerLetter":"C","explain":"1971年10月25日，联合国大会第26届会议以压倒性多数通过第2758号决议，恢复中华人民共和国在 联合国的一切合法权利。所以答案选C。"},{"id":"sg-62","globalId":62,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":62,"question":"1928年10月，国民党中央常务委员会通过了（ ）。","options":["《中华民国临时约法》","《中华民国约法》","《军政纲领》","《训政纲领》"],"answer":3,"answerLetter":"D","explain":"1928 年 10 月，国民党中央常务委员会通过《训政纲领》，规定“由中国国民党全国代表大会代表 国民大会，领导国民行使政权”，实质是蒋介石集团实行独裁统治的工具。《中华民国临时约法》是 1912 年南京临时政府颁布；《中华民国约法》是 1914 年袁世凯炮制；不存在《军政纲领》这一当时特定文件。 答案：D 。"},{"id":"sg-63","globalId":63,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":63,"question":"1956年，陈云在中共八大上提出了（ ）。","options":["“三个主体、三个补充”的思想","“双重监督”的思想","“健全法制”的思想","“新经济政策”的思想"],"answer":0,"answerLetter":"A","explain":"1956 年陈云在中共八大上提出“三个主体、三个补充”的思想，旨在突破传统观念，探索适合中国 特点的经济体制。"},{"id":"sg-64","globalId":64,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":64,"question":"将中国领土台湾割让给日本的不平等条约是（ ）。","options":["《南京条约》","《北京条约》","《马关条约》","《瑷珲条约》"],"answer":2,"answerLetter":"C","explain":"1895 年签订的《马关条约》规定，把辽东半岛、台湾全岛及所有附属各岛屿和澎湖列岛割让给日本 。《南京条约》割香港岛给英国；《北京条约》割九龙司地方一区给英国；《瑷珲条约》使沙俄割占了中国 东北外兴安岭以南、黑龙江以北 60 多万平方公里领土。答案选C。"},{"id":"sg-65","globalId":65,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":65,"question":"1928年12月，毛泽东主持制定中国共产党历史上第一个土地法是在","options":["古田","永新","井冈山","瑞金"],"answer":2,"answerLetter":"C","explain":"1928 年 12 月，毛泽东在井冈山主持制定了中国共产党历史上第一个土地法，即《井冈山土地法》 。所以答案是C。"},{"id":"sg-66","globalId":66,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":66,"question":"1956年，在中共八大上提出“三个主体，三个补充”思想的是（ ）","options":["周恩来","刘少奇","邓小平","陈云"],"answer":3,"answerLetter":"D","explain":"1956年，陈云在中共八大上提出“三个主体，三个补充”思想，即国家经营和集体经营是主体，一 定数量的个体经营为补充；计划生产是主体，一定范围的自由生产为补充；国家市场是主体，一定范围的自 由市场为补充。所以答案选D。"},{"id":"sg-67","globalId":67,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":67,"question":"进入新民主主义社会后，我国在经济上处于领导地位的是（ ）。","options":["私人资本主义经济","国家资本主义经济","合作社经济","国营经济"],"answer":3,"answerLetter":"D","explain":"新民主主义社会存在五种经济成分，国营经济是通过没收官僚资本而形成的，它掌握了主要经济命 脉，在国民经济中居于领导地位。"},{"id":"sg-68","globalId":68,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":68,"question":"洋务派最早从事的洋务事业是（ ）。","options":["兴办军用工业","兴办民用工业","派遣留学生","创立新式学堂"],"answer":0,"answerLetter":"A","explain":"洋务派为了自强，最早从兴办军用工业开始，通过引进西方技术设备来制造枪炮等武器，以增强军 事力量。而兴办民用工业是为了解决军用工业的资金等问题；派遣留学生和创立新式学堂是为洋务事业培养 人才，这些举措都晚于兴办军用工业。答案：A。"},{"id":"sg-69","globalId":69,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":69,"question":"1931～1934年，中国共产党内出现的主要错误倾向是（ ）。","options":["“左”倾盲动主义","“左”倾教条主义","右倾保守主义","右倾机会主义"],"answer":1,"answerLetter":"B","explain":"1931 - 1934 年，王明“左”倾教条主义在党内占据统治地位，使中国革命遭受严重挫折。答案选B 。"},{"id":"sg-70","globalId":70,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":70,"question":"1962年1月，中共中央召开总结经验教训、明确工作方向的会议是（ ）。","options":["“七千人大会”","中共八届九中全会","第一次郑州会议","中共八届十中全会"],"answer":0,"answerLetter":"A","explain":"1962年1月召开的“七千人大会”，是中共中央召开的总结经验教训、明确工作方向的会议 。中共 八届九中全会1961年召开，正式批准对国民经济实行“调整、巩固、充实、提高”八字方针 ；第一次郑州会 议1958年召开，开始纠正“左”倾错误；中共八届十中全会1962年9月召开，使“左”倾错误进一步发展 。 答案选A 。"},{"id":"sg-71","globalId":71,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":71,"question":"近代中国睁眼看世界的第一人是（ ）。","options":["魏源","林则徐","龚自珍","洪仁玕"],"answer":1,"answerLetter":"B","explain":"林则徐组织翻译西方书刊，编译《四洲志》等，是近代中国睁眼看世界的第一人。"},{"id":"sg-72","globalId":72,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":72,"question":"以第一次国共合作为基础的国民革命统一战线正式形成的标志是（ ）。","options":["中共二大的召开","中共三大的召开","中国国民党一大的召开","中国国民党二大的召开"],"answer":2,"answerLetter":"C","explain":"1924 年中国国民党一大的召开，重新解释了三民主义，制定了联俄、联共、扶助农工的三大政策 ，标志着以第一次国共合作为基础的国民革命统一战线正式形成。中共二大主要是制定民主革命纲领；中共 三大是决定共产党员以个人身份加入国民党，但都不是统一战线正式形成标志；国民党二大时统一战线早已 形成。"},{"id":"sg-73","globalId":73,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":73,"question":"1931年1月至1935年1月，中国共产党内出现的主要错误倾向是（ ）。","options":["“左”倾盲动主义","“左”倾教条主义","右倾保守主义","右倾投降主义"],"answer":1,"answerLetter":"B","explain":"1931 年 1 月至 1935 年 1 月，以王明为代表的“左”倾教条主义在党中央占据统治地位，使中国 革命遭受严重挫折。“左”倾盲动主义主要在大革命失败后一段时间；右倾保守主义、右倾投降主义不符合 这一时期党内主要错误倾向特征。"},{"id":"sg-74","globalId":74,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":74,"question":"1967年，老一辈革命家与中央文革小组错误做法进行的抗争被诬称为","options":["“一月风暴”","“二月逆流”","“右倾翻案”","“反攻倒算”"],"answer":1,"answerLetter":"B","explain":"1967 年 2 月前后，谭震林、陈毅、叶剑英等老一辈革命家在不同会议上对“文化大革命”的错误 做法提出了强烈批评，但被江青等人诬称为“二月逆流” 。A 选项“一月风暴”是上海造反派掀起全面夺权 风暴；C 选项“右倾翻案”主要针对邓小平 1975 年整顿；D 选项“反攻倒算”不符合这一史实描述。答案 ：B"},{"id":"sg-75","globalId":75,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":75,"question":"1931年当选为中华苏维埃共和国临时中央政府主席的是（ ）。","options":["毛泽东","周恩来","项英","王稼祥"],"answer":0,"answerLetter":"A","explain":"1931年11月，中华苏维埃第一次全国代表大会在江西瑞金召开，大会选举产生了中华苏维埃共和国 临时中央政府，毛泽东当选为主席。所以答案是A。"},{"id":"sg-76","globalId":76,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":76,"question":"1967年，谭震林等老一辈无产阶级革命家与中央文革小组的错误做法进行的抗争被诬称为（ ）。","options":["“一月风暴”","“反攻倒算”","“右倾翻案”","“二月逆流”"],"answer":3,"answerLetter":"D","explain":"1967 年 2 月，谭震林、陈毅、叶剑英等老一辈革命家在不同会议上对“文化大革命”的错误做法 提出了强烈批评，但当时被林彪、江青反革命集团诬称为“二月逆流” 。"},{"id":"sg-77","globalId":77,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":77,"question":"袁世凯窃夺辛亥革命成果后，于1914年5月炮制了（ ）。","options":["《戒严法》","《中华民国约法》","《钦定宪法大纲》","《暂行新刑律》"],"answer":1,"answerLetter":"B","explain":"1914 年 5 月，袁世凯炮制《中华民国约法》，用总统制取代内阁制，为其复辟帝制做准备。答案 选B 。《戒严法》并非 1914 年 5 月炮制；《钦定宪法大纲》是清政府 1908 年颁布；《暂行新刑律》是袁 世凯在 1912 年在《大清新刑律》基础上修订。"},{"id":"sg-78","globalId":78,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":78,"question":"1933年，冯玉祥在张家口领导成立的抗日武装力量是（ ）。","options":["东北抗日义勇军","东北抗日联军","察哈尔抗日义勇军","察哈尔抗日同盟军"],"answer":3,"answerLetter":"D","explain":"1933 年冯玉祥在张家口成立的是察哈尔抗日同盟军。东北抗日义勇军是自发的民众抗日武装；东北 抗日联军是在东北抗日武装力量基础上发展而来，主要领导者有杨靖宇等；不存在察哈尔抗日义勇军这一确 切称谓。答案选D。"},{"id":"sg-79","globalId":79,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":79,"question":"1971年10月，新中国在外交上取得的重大成果是（ ）。","options":["恢复了在联合国的合法席位","恢复了在世界卫生组织的合法席位","实现了中日关系正常化","实现了中法关系正常化"],"answer":0,"answerLetter":"A","explain":"1971年10月，第26届联合国大会恢复中华人民共和国在联合国的一切合法权利。B选项恢复在世界卫 生组织合法席位时间不符；C选项中日关系正常化是1972年；D选项中法建交是1964年。答案选A。"},{"id":"sg-80","globalId":80,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":80,"question":"毛泽东为新华社写的1949年新年献词是（ ）。","options":["《对目前时局的宣言》","《目前形势和我们的任务》","《将革命进行到底》","《论人民民主专政》"],"answer":2,"answerLetter":"C","explain":"1949 年新年之际，毛泽东为新华社撰写《将革命进行到底》的新年献词，号召将革命进行到底 。A 选项《对目前时局的宣言》发表于抗战胜利后；B 选项《目前形势和我们的任务》是 1947 年毛泽东在陕北 米脂县杨家沟召集的会议上所作报告；D 选项《论人民民主专政》是 1949 年 6 月 30 日毛泽东为纪念中国 共产党成立 28 周年而写。答案：C 。"},{"id":"sg-81","globalId":81,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":81,"question":"在抗美援朝战争中担任中国人民志愿军司令员兼政治委员的是（ ）。","options":["朱德","彭德怀","陈毅","刘伯承"],"answer":1,"answerLetter":"B","explain":"抗美援朝战争中，彭德怀临危受命，出任中国人民志愿军司令员兼政治委员，指挥志愿军作战。而 朱德、陈毅、刘伯承并未担任此职。"},{"id":"sg-82","globalId":82,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":82,"question":"1935年，中共北平临时工作委员会领导发动的抗日救亡运动是（ ）。","options":["一二·九运动","一二·一运动","一二·三零运动","五·二零运动"],"answer":0,"answerLetter":"A","explain":"1935 年 12 月 9 日，中共北平临时工作委员会领导发动了一二·九运动，这是一场抗日救亡运动 。而 B 选项一二·一运动是 1945 年在昆明爆发的反对内战、争取民主的学生运动；C 选项一二·三零运动 表述错误；D 选项五·二零运动是 1947 年爆发的反饥饿、反内战、反迫害运动。所以答案是 A。"},{"id":"sg-83","globalId":83,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":83,"question":"1982年，中共十二大明确提出了（ ）。","options":["建设有中国特色的社会主义","党在社会主义初级阶段的基本路线","建设社会主义政治文明","党在社会主义初级阶段的基本纲领"],"answer":0,"answerLetter":"A","explain":"1982 年中共十二大首次明确提出“建设有中国特色的社会主义”这一崭新命题。B 选项党在社会主 义初级阶段基本路线是 1987 年十三大提出；C 选项建设社会主义政治文明是 2001 年提出；D 选项党在社 会主义初级阶段基本纲领是 1997 年十五大提出。"},{"id":"sg-84","globalId":84,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":84,"question":"毛泽东在《论持久战》中指出，中国抗日战争取得胜利最关键的阶段是（ ）。","options":["战略防御阶段","战略相持阶段","战略反攻阶段","战略决战阶段"],"answer":1,"answerLetter":"B","explain":"《论持久战》中明确提出，战略相持阶段是中国抗日战争取得胜利最关键的阶段。这个阶段，敌之 力量逐步削弱，我之力量逐步增强。相持阶段是持久战的过渡阶段，中国将在此阶段获得转弱为强的力量 ，为战略反攻准备条件。答案：B。"},{"id":"sg-85","globalId":85,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":85,"question":"在抗日战争中，国民党由比较积极地抗战转向消极抗战的标志是（ ）。","options":["国民党五届三中全会的召开","国民党五届四中全会的召开","国民党五届五中全会的召开","国民党五届六中全会的召开"],"answer":2,"answerLetter":"C","explain":"1939 年 1 月，国民党五届五中全会决定成立“防共委员会”，确定了“防共、限共、溶共、反共 ”的方针，这标志着国民党由比较积极地抗战转向消极抗战。答案选C 。"},{"id":"sg-86","globalId":86,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":86,"question":"1935年12月，中国共产党召开的确定抗日民族统一战线新政策的会议是（ ）。","options":["西湖会议","八七会议","瓦窑堡会议","洛川会议"],"answer":2,"answerLetter":"C","explain":"1935 年 12 月的瓦窑堡会议，提出了抗日民族统一战线的政策 ，既着重批判了“左”倾教条主义 在政治策略上的错误，也警戒全党汲取大革命中无产阶级放弃领导权而导致革命失败的教训。西湖会议主要 是讨论国共合作；八七会议是大革命失败后纠正右倾错误等；洛川会议是 1937 年制定全面抗战路线。答案 ：C。"},{"id":"sg-87","globalId":87,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":87,"question":"1990年，邓小平提出的关于中国农业改革与发展的思想是（ ）。","options":["“三个主体，三个补充”","“三步走”","“两个飞跃”","“两个大局”"],"answer":2,"answerLetter":"C","explain":"1990 年邓小平提出中国农业改革与发展的“两个飞跃”思想，一是废除人民公社，实行家庭联产承 包为主的责任制；二是发展适度规模经营，发展集体经济。所以答案选C 。A选项“三个主体，三个补充”是 陈云提出的；B选项“三步走”是中国现代化建设的战略部署；D选项“两个大局”是邓小平关于区域经济协 调发展的思想。"},{"id":"sg-88","globalId":88,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":88,"question":"毛泽东在1957年2月的讲话中指出，我国政治生活的主题是正确处理（ ）。","options":["敌我矛盾","人民内部矛盾","生产关系与生产力的矛盾","上层建筑与经济基础的矛盾"],"answer":1,"answerLetter":"B","explain":"1957 年 2 月，毛泽东在《关于正确处理人民内部矛盾的问题》的讲话中指出，我国政治生活的主 题是正确处理人民内部矛盾。敌我矛盾是对抗性矛盾，当时大规模的阶级斗争基本结束，重点是处理人民内 部这种非对抗性矛盾。C、D 选项属于社会基本矛盾，并非政治生活主题。"},{"id":"sg-89","globalId":89,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":89,"question":"在抗日战争中为国捐躯的八路军副参谋长是（ ）。","options":["彭雪枫","赵尚志","杨靖宇","左权"],"answer":3,"answerLetter":"D","explain":"左权是八路军副参谋长，在抗日战争中牺牲。彭雪枫是新四军将领；赵尚志、杨靖宇是东北抗日联 军的重要领导人。"},{"id":"sg-90","globalId":90,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":90,"question":"1935年1月，中国共产党在红军长征途中召开了具有历史转折意义的（ ）。","options":["古田会议","遵义会议","两河口会议","瓦窑堡会议"],"answer":1,"answerLetter":"B","explain":"1935年1月召开的遵义会议，结束了王明“左”倾冒险主义在中共中央的统治，确立了以毛泽东为代 表的新的中央的正确领导，在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党历史上一个 生死攸关的转折点 。A选项古田会议1929 年召开；C选项两河口会议1935年6月召开；D选项瓦窑堡会议1935 年12月召开。"},{"id":"sg-91","globalId":91,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":91,"question":"1990年，中共中央和国务院为进一步对外开放而作出的战略举措是（ ）。","options":["建立厦门经济特区","建立珠海经济特区","开发、开放海南经济特区","开发、开放上海浦东新区"],"answer":3,"answerLetter":"D","explain":"1990年，中共中央和国务院作出开发、开放上海浦东新区的战略举措。厦门、珠海经济特区在 1980年设立，海南经济特区在1988年设立。所以答案是D。"},{"id":"sg-92","globalId":92,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":92,"question":"毛泽东在1957年2月扩大的最高国务会议上指出，我国政治生活的主题是（ ）。","options":["正确处理敌我矛盾","正确处理人民内部矛盾","正确处理民主与专政的关系","正确处理共产党和民主党派的关系"],"answer":1,"answerLetter":"B","explain":"1957 年 2 月，毛泽东在扩大的最高国务会议上发表《关于正确处理人民内部矛盾的问题》讲话 ，指出我国政治生活的主题是正确处理人民内部矛盾。"},{"id":"sg-93","globalId":93,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":93,"question":"在武昌起义前夕的保路运动中，斗争最激烈的省份是（ ）。","options":["湖南","湖北","四川","广东"],"answer":2,"answerLetter":"C","explain":"保路运动中，四川人民发动了大规模武装起义，成立保路同志军，与清军展开激烈战斗，运动发展 成武装起义，斗争最为激烈。答案选C。"},{"id":"sg-94","globalId":94,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":94,"question":"1992年召开的中共十四大明确提出，我国经济体制改革的目标是建立（ ）。","options":["社会主义市场经济体制","社会主义有计划商品经济体制","计划为主、市场为辅的经济体制","市场为主、计划为辅的经济体制"],"answer":0,"answerLetter":"A","explain":"1992年中共十四大明确提出我国经济体制改革目标是建立社会主义市场经济体制 。"},{"id":"sg-95","globalId":95,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":95,"question":"毛泽东指出，社会主义国家政治生活的主题是（ ）。","options":["正确处理人民内部矛盾","正确处理敌我矛盾","正确处理共产党和民主党派的关系","正确处理民主和专政的关系"],"answer":0,"answerLetter":"A","explain":"1957 年 2 月，毛泽东发表《关于正确处理人民内部矛盾的问题》，提出社会主义国家政治生活的 主题是正确处理人民内部矛盾 。答案：A 。"},{"id":"sg-96","globalId":96,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":96,"question":"1998年，中共中央决定在县级以上党政领导班子和领导干部中深入开展（ ）。","options":["讲政治、讲经济、讲文化的教育","讲思想、讲作风、讲文明的教育","讲理想、讲觉悟、讲正气的教育","讲学习、讲政治、讲正气的教育"],"answer":3,"answerLetter":"D","explain":"1998 年底，中共中央决定在县级以上党政领导班子、领导干部中深入开展以讲学习、讲政治、讲正 气为主要内容的党性党风教育。所以答案是D。"},{"id":"sg-97","globalId":97,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":97,"question":"毛泽东指出，在社会主义改造完成后我国政治生活的主题是正确处理（ ）。","options":["生产关系与生产力之间的矛盾","上层建筑与经济基础之间的矛盾","敌我矛盾","人民内部矛盾"],"answer":3,"answerLetter":"D","explain":"社会主义改造完成后，国内的敌我矛盾已经基本解决，人民内部矛盾突出起来，成为政治生活的主 题。A、B选项是社会基本矛盾，不是政治生活主题。所以正确答案是关于人民内部矛盾。"},{"id":"sg-98","globalId":98,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":98,"question":"1936年10月，中国工农红军三大主力胜利会师地是（ ）。","options":["四川懋功地区","甘肃会宁、静宁将台堡","西康甘孜地区","陕北吴起镇"],"answer":1,"answerLetter":"B","explain":"1936年10月，红二、红四方面军先后同红一方面军在甘肃会宁、静宁将台堡会师，标志着中国工农 红军三大主力胜利会师。四川懋功地区是1935年6月红一、四方面军会师地；西康甘孜地区是1936年7月红二 、四方面军会师地；陕北吴起镇是1935年10月中央红军与陕北红军会师地。答案选B。"},{"id":"sg-99","globalId":99,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":99,"question":"19世纪60年代，清朝统治集团中倡导洋务的首领人物是（ ）。","options":["奕䜣","桂良","曾国藩","李鸿章"],"answer":0,"answerLetter":"A","explain":"19世纪60年代，清朝统治集团中倡导洋务的首领人物是奕䜣 ，他是中央洋务派的代表。曾国藩、李 鸿章是地方洋务派代表，桂良不是倡导洋务的首领人物。答案：A。"},{"id":"sg-100","globalId":100,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":100,"question":"1937年，出任新四军军长的是（ ）。","options":["朱德","刘伯承","叶挺","陈毅"],"answer":2,"answerLetter":"C","explain":"1937年，叶挺出任新四军军长 。朱德是八路军总指挥；刘伯承是八路军129师师长；陈毅在新四军 组建时是重要将领，但不是军长。"},{"id":"sg-101","globalId":101,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":101,"question":"全国性抗战开始后，中国军队取得第一次重大胜利的战役是（ ）。","options":["台儿庄战役","昆仑关战役","百团大战","平型关战役"],"answer":3,"answerLetter":"D","explain":"平型关战役是全国性抗战开始后中国军队取得的第一次重大胜利，有力地打击了日军的疯狂气焰 ，打破了“日军不可战胜”的神话。台儿庄战役是抗战以来中国正面战场取得的最大的一场胜仗；昆仑关战 役是桂南会战中取得的重大胜利；百团大战是八路军主动出击日军的一次大规模战役。答案：D。"},{"id":"sg-102","globalId":102,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":102,"question":"中共八大上，在经济建设方面提出“三个主体，三个补充”思想的领导人是（ ）。","options":["毛泽东","周恩来","陈云","邓小平"],"answer":2,"answerLetter":"C","explain":"在中共八大上，陈云提出了“三个主体，三个补充”的思想，即国家经营和集体经营是主体，一定 数量的个体经营为补充；计划生产是主体，一定范围的自由生产为补充；国家市场是主体，一定范围的自由 市场为补充。答案：C。"},{"id":"sg-103","globalId":103,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":103,"question":"1898年，为对抗维新变法而发表《劝学篇》的洋务派官僚是（ ）。","options":["李鸿章","左宗棠","张之洞","刘坤一"],"answer":2,"answerLetter":"C","explain":"1898 年，张之洞发表《劝学篇》，对洋务派的指导思想“中学为体，西学为用”作了全面阐述，试 图以此来对抗维新变法。答案选C。"},{"id":"sg-104","globalId":104,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":104,"question":"1940年8～12月，八路军发动的大规模进攻华北日军的战役是（ ）。","options":["平型关战役","忻口战役","黄桥战役","百团大战"],"answer":3,"answerLetter":"D","explain":"1940 年 8 月至 12 月八路军发动百团大战，向华北日军发起大规模进攻。平型关战役是 1937 年 ；忻口战役也是 1937 年；黄桥战役是 1940 年新四军在江苏黄桥对国民党顽固派军队进行的自卫反击战役 ，地点不在华北。"},{"id":"sg-105","globalId":105,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":105,"question":"2005年3月，第十届全国人民代表大会第三次会议通过的法律是（ ）。","options":["《香港特别行政区基本法》","《国家安全法》","《澳门特别行政区基本法》","《反分裂国家法》"],"answer":3,"answerLetter":"D","explain":"2005年3月，第十届全国人民代表大会第三次会议通过《反分裂国家法》 ，旨在反对和遏制“台独 ”分裂势力分裂国家，促进祖国和平统一。A选项《香港特别行政区基本法》于1990年通过；B选项《国家安 全法》2015年通过；C选项《澳门特别行政区基本法》1993 年通过。"},{"id":"sg-106","globalId":106,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":106,"question":"太平天国运动后期，提出《资政新篇》这一带有资本主义色彩改革方案的是（ ）。","options":["洪秀全","洪仁玕","石达开","李秀成"],"answer":1,"answerLetter":"B","explain":"《资政新篇》是洪仁玕向洪秀全提出的统筹全局的改革方案，具有鲜明的资本主义色彩。"},{"id":"sg-107","globalId":107,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":107,"question":"中共中央正式提出党在过渡时期总路线的时间是（ ）。","options":["1949年","1950年","1953年","1956年"],"answer":2,"answerLetter":"C","explain":"1953 年 6 月，中共中央政治局正式讨论和制定了中国共产党在过渡时期的总路线。答案选C。"},{"id":"sg-108","globalId":108,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":108,"question":"中国大陆基本解放和实现统一的标志是（ ）。","options":["1949年中华人民共和国的成立","1950年中共七届三中全会的召开","1951年西藏的和平解放","1952年土地改革的完成"],"answer":2,"answerLetter":"C","explain":"西藏和平解放，使中国大陆实现了基本解放和统一。中华人民共和国成立时，还有部分地区未解放 ；七届三中全会是为全面实施《共同纲领》规定了明确的战略策略方针；土地改革主要是关于农村生产关系 变革。答案选C。"},{"id":"sg-109","globalId":109,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":109,"question":"1898年，张之洞发表的对抗维新变法的著作是（ ）。","options":["《新学伪经考》","《孔子改制考》","《仁学》","《劝学篇》"],"answer":3,"answerLetter":"D","explain":"《劝学篇》为张之洞所著，其核心是“中体西用”，以此对抗维新变法。《新学伪经考》《孔子改 制考》是康有为的著作，《仁学》是谭嗣同的著作。"},{"id":"sg-110","globalId":110,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":110,"question":"20世纪70年代，毛泽东、周恩来抓住时机发起了改善中美关系的（ ）。","options":["“篮球外交”","“乒乓外交”","“网球外交”","“围棋外交”"],"answer":1,"answerLetter":"B","explain":"20世纪70年代，通过“乒乓外交”这一以小球推动大球的方式，打开了中美关系改善的大门 。答案 ：B"},{"id":"sg-111","globalId":111,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":111,"question":"外国列强对近代中国进行资本输出最早出现在（ ）。","options":["第一次鸦片战争后","第二次鸦片战争后","中日甲午战争","八国联军侵华战争后"],"answer":1,"answerLetter":"B","explain":"外国列强对中国进行资本输出，在第二次鸦片战争后就已开始，《天津条约》等不平等条约签订后 ，列强逐渐开始在中国设立工厂等进行资本输出活动。而甲午战争后资本输出大规模扩张。第一次鸦片战争 后主要还是商品输出为主。八国联军侵华后资本输出进一步加深。所以最早出现在第二次鸦片战争后。答案 ：B"},{"id":"sg-112","globalId":112,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":112,"question":"1904年至l905年，为争夺侵略权益公然在中国东北进行战争的是（ ）。","options":["美国与俄国","美国与英国","英国与日本","日本与俄国"],"answer":3,"answerLetter":"D","explain":"1904 - 1905年，日俄两国为争夺在华利益，在中国东北进行战争，清政府却宣布“局外中立”。答 案选D。"},{"id":"sg-113","globalId":113,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":113,"question":"1945年4月，包括解放军代表董必武在内的中国代表团出席了（ ）。","options":["开罗会议","德黑兰会议","雅尔塔会议","联合国制宪会议"],"answer":3,"answerLetter":"D","explain":"1945 年 4 月，董必武作为中国共产党代表随中国代表团出席联合国制宪会议。开罗会议、德黑兰 会议、雅尔塔会议召开时间与题干所给时间不对应，且参会人员中没有董必武。"},{"id":"sg-114","globalId":114,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":114,"question":"20世纪初，为传播民主革命思想而撰写《革命军》一书的人是（ ）。","options":["章炳麟","邹容","陈天华","孙中山"],"answer":1,"answerLetter":"B","explain":"邹容撰写了《革命军》，以通俗易懂的语言号召人民起来推翻清王朝统治，建立“中华共和国” 。 章炳麟的著作是《驳康有为论革命书》，陈天华的著作是《警世钟》《猛回头》，孙中山主要是领导革命实 践并提出革命理论。答案：B 。"},{"id":"sg-115","globalId":115,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":115,"question":"为反对袁世凯刺杀宋教仁和“善后大借款”，孙中山在1913年领导发动了（ ）。","options":["二次革命","护国战争","护法运动","北伐战争"],"answer":0,"answerLetter":"A","explain":"【标准答案：A】"},{"id":"sg-116","globalId":116,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":116,"question":"中国第一个资产阶级革命政党是（ ）。","options":["兴中会","中国同盟会","中华革命党","中国国民党"],"answer":1,"answerLetter":"B","explain":"兴中会是近代中国第一个资产阶级革命团体；中国同盟会是中国第一个全国性的统一的资产阶级革 命政党；中华革命党是孙中山于1914年在日本东京成立的组织；中国国民党由中华革命党改组而来。所以答 案是B。"},{"id":"sg-117","globalId":117,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":117,"question":"1905～1907年，资产阶级革命派与改良派论战的焦点是（ ）。","options":["要不要打倒列国","要不要实行共和","要不要以革命手段推翻清政府","要不要废科学，兴学堂"],"answer":2,"answerLetter":"C","explain":"1905 - 1907年资产阶级革命派与改良派论战主要围绕三个方面，其中焦点是要不要以革命手段推翻 清政府。革命派主张用革命手段推翻清王朝，改良派主张通过改良的方式实现君主立宪，反对革命。"},{"id":"sg-118","globalId":118,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":118,"question":"1945年4月，出席联合国制宪会议中国代表团中的解放区代表是（ ）。","options":["周恩来","刘少奇","董必武","王若飞"],"answer":2,"answerLetter":"C","explain":"1945 年 4 月，董必武作为解放区代表出席联合国制宪会议。"},{"id":"sg-119","globalId":119,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":119,"question":"为反对袁世凯的独裁和卖国行径，孙中山在1913年领导革命党人发动了（ ）。","options":["二次革命","护国战争","护法战争","北伐战争"],"answer":0,"answerLetter":"A","explain":"1913 年，袁世凯派人刺杀宋教仁，为反对袁世凯独裁和卖国，孙中山领导革命党人发动二次革命。 护国战争发生于 1915 年底，是反对袁世凯称帝；护法战争是 1917 - 1918 年，为维护《临时约法》；北伐 战争 1926 年开始，旨在推翻北洋军阀统治。答案：A 。"},{"id":"sg-120","globalId":120,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":120,"question":"中国对香港恢复行使主权的时间是（ ）。","options":["1997年7月1日","1997年l2月20日","1999年7月1日","1999年12月20日"],"answer":0,"answerLetter":"A","explain":"1997年7月1日，中国对香港恢复行使主权，香港回归祖国。1999年12月20日是澳门回归祖国的时间 ，1999年7月1日、1997年12月20日与港澳回归时间均不符。答案：A。"},{"id":"sg-121","globalId":121,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":121,"question":"1905年8月，中国同盟会成立时所确定的机关刊物是（ ）。","options":["《民报》","《新民丛报》","《时务报》","《万国公报》"],"answer":0,"answerLetter":"A","explain":"1905 年 8 月 20 日，孙中山、黄兴等人在东京成立中国同盟会，其机关报为《民报》 。《新民丛 报》是梁启超主持的，《时务报》是维新派创办，《万国公报》为广学会发行，均与同盟会机关刊物无关。"},{"id":"sg-122","globalId":122,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":122,"question":"1945年8月，毛泽东发表的号召对日本侵略者实行全国规模反攻的文章是（ ）。","options":["《为抗日救国告全国同胞书》","《关于目前形势与党的任务的决定》","《论持久战》","《对日寇的最后一战》"],"answer":3,"answerLetter":"D","explain":"1945年8月，毛泽东发表《对日寇的最后一战》，号召对日本侵略者实行全国规模反攻 。A选项《为 抗日救国告全国同胞书》是1935年中共驻共产国际代表团发表，推动了抗日救亡运动发展；B选项《关于目前 形势与党的任务的决定》是1937年洛川会议文件，主要是制定全面抗战路线；C选项《论持久战》是1938年毛 泽东阐述抗日战争方针的著作。"},{"id":"sg-123","globalId":123,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":123,"question":"20世纪初，在资产阶级民主革命思想传播中发表《驳康有为论革命书》的是（ ）。","options":["孙中山","邹容","章炳麟","陈天华"],"answer":2,"answerLetter":"C","explain":"章炳麟发表《驳康有为论革命书》，批驳康有为的保皇观点，强调中国人民完全有能力建立民主共 和制度。答案选C 。"},{"id":"sg-124","globalId":124,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":124,"question":"魏源在1843难编纂的《海国图志》中提出的重要思想是（ ）。","options":["中学为体、西学为用","物竞天择、适者生存","救亡图存","师夷长技以制夷"],"answer":3,"answerLetter":"D","explain":"《海国图志》中魏源明确提出了“师夷长技以制夷”的思想 ，主张学习西方先进技术来抵御西方侵 略。A选项“中学为体、西学为用”是洋务派主张；B选项“物竞天择、适者生存”是严复翻译《天演论》宣 传的思想；C选项“救亡图存”是甲午战后民族危机加深时兴起的思潮。"},{"id":"sg-125","globalId":125,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":125,"question":"中国封建社会产生过诸多“盛世”，出现在清代的是（ ）。","options":["文景之治","贞观之治","开元之治","康乾盛世"],"answer":3,"answerLetter":"D","explain":"文景之治是西汉汉文帝、汉景帝时期；贞观之治是唐朝唐太宗时期；开元之治是唐朝唐玄宗前期 ；康乾盛世是清朝康熙、雍正、乾隆时期的盛世局面。所以出现在清代的是康乾盛世。"},{"id":"sg-126","globalId":126,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":126,"question":"1911年，标志辛亥革命达到高潮的起义是（ ）。","options":["惠州起义","河口起义","广州起义","武昌起义"],"answer":3,"answerLetter":"D","explain":"武昌起义成功后，全国十几个省纷纷响应，清朝的统治摇摇欲坠，标志着辛亥革命达到高潮。而惠 州起义、河口起义、广州起义虽也是反清起义，但影响力和对辛亥革命进程推动程度不及武昌起义。"},{"id":"sg-127","globalId":127,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":127,"question":"20世纪初，邹容发表的号召人民推翻清朝统治、建立“中华共和国”的著作是（ ）。","options":["《驳康有为论革命书》","《革命军》","《警世钟》","《猛回头》"],"answer":1,"answerLetter":"B","explain":"邹容的《革命军》热情讴歌革命，号召推翻清朝统治，建立“中华共和国” 。A选项《驳康有为论 革命书》是章炳麟所著；C选项《警世钟》和D选项《猛回头》是陈天华所著。"},{"id":"sg-128","globalId":128,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":128,"question":"我国的科举制度正式废除于（ ）。","options":["1905年","1906年","1907年","1908年"],"answer":1,"answerLetter":"B","explain":"答案：B科举制度是中国古代选拔官员的一种制度，历经了1300多年。清朝末期，随着社会的变革和 新式教育的兴起，科举制度逐渐显得不适应时代的需求。1905年，清政府宣布废除科举制度的诏书，但实际 操作上，科举制度的废除是在1906年进行的。因此，我国的科举制度正式废除于1906年，选项B正确。"},{"id":"sg-129","globalId":129,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":129,"question":"中国共产党领导建立的第一个农民协会是在（ ）。","options":["浙江省萧山县","广东省海丰县","福建省上杭县","湖南省湘潭县"],"answer":0,"answerLetter":"A","explain":"1921 年 9 月，沈定一等在浙江省萧山县衙前村领导成立了第一个农民协会。答案：A 。"},{"id":"sg-130","globalId":130,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":130,"question":"从1937年卢沟桥事变到1938年10月广州、武汉失守，中国抗日战争处于（ ）。","options":["战略防御阶段","战略相持阶段","战略反攻阶段","战略决战阶段"],"answer":0,"answerLetter":"A","explain":"1937 年卢沟桥事变到 1938 年 10 月广州、武汉失守，日军处于战略进攻态势，中国军队处于战略 防御，进行了一系列抵抗作战。所以这一时期是战略防御阶段。"},{"id":"sg-131","globalId":131,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":131,"question":"我国对资本主义商业的社会主义改造所采取的基本政策是（ ）。","options":["加工订货","和平赎买","统购包销","公私合营"],"answer":1,"answerLetter":"B","explain":"我国对资本主义工商业社会主义改造采取的基本政策是和平赎买，通过国家资本主义形式，将其改 造成社会主义公有制企业。加工订货、统购包销是国家资本主义初级形式，公私合营是高级形式。答案选B。"},{"id":"sg-132","globalId":132,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":132,"question":"我国农业社会主义改造中，具有完全社会主义性质的经济组织形式是（ ）。","options":["变工队","互助组","初级农业生产合作社","高级农业生产合作社"],"answer":3,"answerLetter":"D","explain":"变工队是旧中国农村的一种劳动互助形式，不属于社会主义改造的经济组织形式；互助组是具有社 会主义萌芽性质；初级农业生产合作社具有半社会主义性质；高级农业生产合作社实现了土地等主要生产资 料的公有，具有完全社会主义性质。"},{"id":"sg-133","globalId":133,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":133,"question":"中国共产党为总结经验教训、明确工作方向召开的“七千人大会”是在（ ）。","options":["1958年","1959年","1962年","1963年"],"answer":2,"answerLetter":"C","explain":"“七千人大会”于1962年1月11日至2月7日召开 ，目的是总结经验教训、明确工作方向。"},{"id":"sg-134","globalId":134,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":134,"question":"1920年10月，李大钊发起成立的中国共产党早期组织是（ ）。","options":["上海共产主义小组","武汉共产主义小组","北京共产主义小组","广州共产主义小组"],"answer":2,"answerLetter":"C","explain":"1920年10月，李大钊发起成立北京共产主义小组 。上海共产主义小组是陈独秀发起成立的，武汉、 广州共产主义小组也都不是李大钊发起成立的。"},{"id":"sg-135","globalId":135,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":135,"question":"1946年6月全面内战爆发时，国民党军队首先进攻的地区是（ ）。","options":["中原解放区","东北解放区","山东解放区","陕甘宁解放区"],"answer":0,"answerLetter":"A","explain":"1946年6月，国民党军队以围攻中原解放区为起点，挑起了全国性的内战。所以国民党军队首先进攻 的地区是中原解放区。"},{"id":"sg-136","globalId":136,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":136,"question":"邓演达在1930年8月领导成立的中间党派是（ ）。","options":["中华职业教育社","中国国家社会党","中国青年党","中国国民党临时行动委员会"],"answer":3,"answerLetter":"D","explain":"1930 年 8 月，邓演达领导成立中国国民党临时行动委员会，它是中间党派中影响较大的一个。而 A 选项中华职业教育社由黄炎培等创立；B 选项中国国家社会党由张君劢等组建；C 选项中国青年党由曾琦 等建立，都与邓演达无关。"},{"id":"sg-137","globalId":137,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":137,"question":"我国西藏实现和平解放的时间是（ ）。","options":["1949年10月","1950年10月","1951年10月","1952年10月"],"answer":2,"answerLetter":"C","explain":"1951 年 5 月，中央人民政府同西藏地方政府达成关于和平解放西藏办法的协议，10 月，人民解放 军进驻拉萨，西藏和平解放。答案：C。"},{"id":"sg-138","globalId":138,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":138,"question":"1920年8月，陈独秀领导建立的中国共产党早期组织是（ ）。","options":["上海共产主义小组","北京共产主义小组","武汉共产主义小组","广州共产主义小组"],"answer":0,"answerLetter":"A","explain":"1920年8月，陈独秀在上海建立了中国第一个共产党早期组织——上海共产主义小组 。其他各地共 产主义小组在上海小组影响推动下建立。"},{"id":"sg-139","globalId":139,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":139,"question":"1947年，被国民党当局宣布为而“非法团体”而被迫解散的中国国民党派是（ ）。","options":["中国民主同盟","九三学社","中国农工民主党","台湾民主自治同盟"],"answer":0,"answerLetter":"A","explain":"1947 年 10 月，国民党当局宣布民盟为“非法团体”，明令对该组织及其成员的一切活动“严加取 缔”，民盟总部被迫发表公告，通告盟员自即日起一律停止政治活动，民盟总部即日解散。"},{"id":"sg-140","globalId":140,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":140,"question":"第五次反“围剿”斗争失败后，1934年10月开始战略转移的是（ ）。","options":["红十五军团","红一方面军","红二方面军","红四方面军"],"answer":1,"answerLetter":"B","explain":"第五次反“围剿”失败后，1934 年 10 月红一方面军率先开始战略转移，也就是长征。红二、红四 方面军随后开始长征，红十五军团成立于 1935 年，与此次战略转移起始时间不符。"},{"id":"sg-141","globalId":141,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":141,"question":"武昌起义前夕，在保路运动中规模最大、斗争最激烈的省份是（ ）。","options":["湖南","湖北","广东","四川"],"answer":3,"answerLetter":"D","explain":"保路运动中，四川成立保路同志会，发动民众开展反清武装起义，规模最大、斗争最激烈。答案 ：D。"},{"id":"sg-142","globalId":142,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":142,"question":"1921年9月，在浙江省萧山县衙前村组织成立第一个农民协会的是（ ）。","options":["沈定一","彭湃","阮啸仙","林伯渠"],"answer":0,"answerLetter":"A","explain":"1921 年 9 月，沈定一在浙江省萧山县衙前村组织成立了第一个农民协会。彭湃主要在广东海陆丰 开展农民运动；阮啸仙是广东农民运动的重要领导人之一；林伯渠主要活跃于民主革命等诸多重要政治活动 ，与题干农民协会创建不符。答案：A 。"},{"id":"sg-143","globalId":143,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":143,"question":"1947年，国民党宪警镇压爱国学生运动的事件是（ ）。","options":["五卅惨案","较场口惨案","下关惨案","五二零惨案"],"answer":3,"answerLetter":"D","explain":"1947 年 5 月 20 日，南京、上海、苏州、杭州地区 16 所专科以上院校学生 6000 余人汇集南京 ，举行反饥饿、反内战、挽救教育危机联合大游行，遭到国民党宪警的镇压，史称“五二零惨案” 。A 选项 五卅惨案发生于 1925 年；B 选项较场口惨案发生于 1946 年；C 选项下关惨案发生于 1946 年。"},{"id":"sg-144","globalId":144,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":144,"question":"第一次国共合作的政治基础是（ ）。","options":["三民主义","新三民主义","新民主主义","社会主义"],"answer":1,"answerLetter":"B","explain":"新三民主义与中国共产党在民主革命阶段的纲领基本一致，成为第一次国共合作的政治基础。三民 主义没有明确的反帝反封建内容；新民主主义是中国共产党的革命理论；社会主义与当时合作基础不符。答 案：B"},{"id":"sg-145","globalId":145,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":145,"question":"武昌起义胜利后被推举为湖北军政府都督的是（ ）。","options":["黄兴","黎元洪","孙中山","章太炎"],"answer":1,"answerLetter":"B","explain":"武昌起义后，革命党人认为需要有一个有地位的人来稳定局面，黎元洪当时是湖北新军协统，在旧 势力中有一定影响力，所以被推举为湖北军政府都督 。黄兴、孙中山当时不在武昌，章太炎在当时主要以思 想文化活动等闻名，并非被推举为湖北军政府都督之人。"},{"id":"sg-146","globalId":146,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":146,"question":"中国近代史上第一次彻底反帝反封建的革命运动是（ ）。","options":["辛亥革命","五四运动","五卅运动","国民革命"],"answer":1,"answerLetter":"B","explain":"辛亥革命没有彻底反帝反封建；五卅运动发生在五四运动之后；国民革命也是在五四运动之后。而 五四运动是中国近代史上第一次彻底反帝反封建的革命运动。"},{"id":"sg-147","globalId":147,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":147,"question":"1922年1月，中国共产党领导的第一次工人运动高潮的起点是（ ）。","options":["香港海员罢工","安源路矿工人罢工","京汉铁路工人罢工","省港工人罢工"],"answer":0,"answerLetter":"A","explain":"1922 年 1 月香港海员罢工，是中国工人阶级第一次直接同帝国主义势力进行的有组织较量 ，成为 第一次工人运动高潮的起点。"},{"id":"sg-148","globalId":148,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":148,"question":"中国近代史上人民群众第一次大规模的反侵略武装斗争是（ ）。","options":["三元里人民的抗英斗争","太平天国抗击洋枪队的斗争","台湾人民的抗日斗争","义和团抗击八国联军的斗争"],"answer":0,"answerLetter":"A","explain":"三元里人民抗英斗争发生于1841年，是中国近代史上人民群众第一次大规模的反侵略武装斗争。其 他选项时间均晚于它。"},{"id":"sg-149","globalId":149,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":149,"question":"1922年7月，中共二大第一次明确提出了（ ）。","options":["反帝反封建的民主革命纲领","实现共产主义的最高纲领","新民主主义革命总路线","土地革命总路线"],"answer":0,"answerLetter":"A","explain":"中共二大在分析国际国内形势和中国社会性质的基础上，第一次明确提出了反帝反封建的民主革命 纲领。B项实现共产主义最高纲领在一大就已提出；C项新民主主义革命总路线是1948年毛泽东完整表述的 ；D项土地革命总路线在20世纪30年代逐渐形成。"},{"id":"sg-150","globalId":150,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":150,"question":"1924年，国民革命统一战线正式形成的标志是（ ）。","options":["中国国民党一大的召开","中国国民党二大的召开","中国共产党三大的召开","中国共产党四大的召开"],"answer":0,"answerLetter":"A","explain":"1924 年，中国国民党一大在广州召开，重新解释了三民主义，制定了联俄、联共、扶助农工的三大 政策；承认共产党员和青年团员以个人身份加入国民党。标志着以第一次国共合作为基础的革命统一战线正 式建立。"},{"id":"sg-151","globalId":151,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":151,"question":"1947年，中国共产党在全国土地会议上制定的重要文件是（ ）。","options":["《井冈山土地法》","《兴国土地法》","《关于清算、减租及土地问题的请示》","《中国土地法大纲》"],"answer":3,"answerLetter":"D","explain":"1947 年全国土地会议制定的是《中国土地法大纲》。A 项《井冈山土地法》是 1928 年制定；B 项 《兴国土地法》是 1929 年制定；C 项《关于清算、减租及土地问题的请示》即《五四指示》，是 1946 年 发布。答案：D 。"},{"id":"sg-152","globalId":152,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":152,"question":"辛亥革命时期，资产阶级革命派的阶级基础是（ ）。","options":["买办资产阶级","官僚资产阶级","民族资产阶级","城市小资产阶级"],"answer":2,"answerLetter":"C","explain":"资产阶级革命派代表民族资产阶级的利益，民族资产阶级随着民族资本主义发展而壮大，为革命派 提供阶级基础。买办资产阶级和官僚资产阶级与帝国主义、封建势力联系紧密，不是革命派阶级基础。城市 小资产阶级不是资产阶级范畴。答案选C。"},{"id":"sg-153","globalId":153,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":153,"question":"中国历史上第一次比较完全意义上的资产阶级民主革命是（ ）。","options":["戊戌维新运动","辛亥革命","护国运动","国民革命"],"answer":1,"answerLetter":"B","explain":"辛亥革命推翻了清王朝统治，结束了统治中国两千多年的君主专制制度，建立了中国历史上第一个 资产阶级共和政府，是中国历史上第一次比较完全意义上的资产阶级民主革命。戊戌维新运动是一场资产阶 级性质的改良运动；护国运动是为反对袁世凯复辟帝制；国民革命是国共合作推翻北洋军阀统治的革命，时 间晚于辛亥革命 。答案选B。"},{"id":"sg-154","globalId":154,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":154,"question":"1925年，广州国民政府将所辖各部队统一改编为（ ）。","options":["国民军","国民革命军","东征军","北伐军"],"answer":1,"answerLetter":"B","explain":"1925 年，广州国民政府将所辖各部队统一改编为国民革命军，这是为适应革命形势发展，建立起的 新型军队。"},{"id":"sg-155","globalId":155,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":155,"question":"1947年10月，被国民党当局宣布为“非法团体”并勒令取缔的民主党派是（ ）。","options":["中国农工民主党","中国民主同盟","中国民主促进会","中国国民党革命委员会"],"answer":1,"answerLetter":"B","explain":"1947 年 10 月，国民党当局宣布中国民主同盟为“非法团体”，明令对该组织及其成员的一切活动 “严加取缔”。民盟被迫解散，这使中间路线的政治幻想破灭。"},{"id":"sg-156","globalId":156,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":156,"question":"对兴办洋务的指导思想最早作出完整表述的人是（ ）。","options":["冯桂芬","马建忠","王韬","郑观应"],"answer":0,"answerLetter":"A","explain":"冯桂芬在《校邠庐抗议》中提出“以中国之伦常名教为原本，辅以诸国富强之术”，第一次完整表 述了洋务运动“中体西用”的指导思想。"},{"id":"sg-157","globalId":157,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":157,"question":"新文化运动的主要内容是（ ）。","options":["提倡民主和科学","宣传俄国十月革命","主张社会革命","反对外来侵略"],"answer":0,"answerLetter":"A","explain":"新文化运动提倡民主、反对独裁专制，提倡科学、反对迷信盲从，这是其主要内容。B宣传俄国十月 革命是新文化运动后期内容，不是主要内容；C主张社会革命不是新文化运动核心内容；D反对外来侵略并非 新文化运动重点。"},{"id":"sg-158","globalId":158,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":158,"question":"中国人民解放军在1949年4月21日发起的重大战役是（ ）。","options":["辽沈战役","淮海战役","平津战役","渡江战役"],"answer":3,"answerLetter":"D","explain":"1949年4月21日，毛泽东、朱德发布《向全国进军的命令》，人民解放军发起渡江战役。而辽沈战役 1948年9 - 11月、淮海战役1948年11月 - 1949年1月、平津战役1948年11月 - 1949年1月。答案：D。"},{"id":"sg-159","globalId":159,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":159,"question":"1925年国民政府将所辖各部队统一改编为（ ）。","options":["国民军","东征军","国民革命军","北伐军"],"answer":2,"answerLetter":"C","explain":"1925年，国民政府将所辖各部队统一改编为国民革命军，这是为了适应当时革命形势发展，建立统 一军事力量的重要举措。"},{"id":"sg-160","globalId":160,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":160,"question":"1947年11月，在香港成立的中国民主党派是（ ）。","options":["中国民主同盟","中国国民党革命委员会","中国民主促进会","中国农工民主党"],"answer":1,"answerLetter":"B","explain":"1947 年 11 月，中国国民党民主派和其他爱国民主人士第一次联合会议在香港召开。1948 年 1 月 1 日，中国国民党革命委员会正式成立，其成立地点在香港 。"},{"id":"sg-161","globalId":161,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":161,"question":"国民党军队在1946年挑起全面内战的起点是大举围攻（ ）。","options":["东北解放区","中原解放区","陕北解放区","山东解放区"],"answer":1,"answerLetter":"B","explain":"1946 年 6 月，国民党军队以进攻中原解放区为起点，挑起了全国性的内战。"},{"id":"sg-162","globalId":162,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":162,"question":"新中国第一部婚姻法颁布的时间是（ ）。","options":["1950年5月","1950年6月","1951年7月","1951年8月"],"answer":0,"answerLetter":"A","explain":"新中国第一部婚姻法于1950年5月1日颁布施行，它对有关婚姻关系的建立、夫妻间的权利和义务、 父母子女间的关系，离婚、离婚后子女的抚养和教育等内容，作了具体规定。"},{"id":"sg-163","globalId":163,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":163,"question":"中国西藏和平解放的时间是（ ）。","options":["1948年10月","1949年10月","1950年10月","1951年10月"],"answer":3,"answerLetter":"D","explain":"1951 年 5 月 23 日，中央人民政府与西藏地方政府签订《关于和平解放西藏办法的协议》，1951 年 10 月，人民解放军进驻拉萨，西藏和平解放。答案选D。"},{"id":"sg-164","globalId":164,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":164,"question":"中国资产阶级领导的旧民主主义革命终结的标志是（ ）。","options":["二次革命的失败","护国运动的失败","第一次护法运动的失败","第二次护法运动的失败"],"answer":3,"answerLetter":"D","explain":"旧民主主义革命是由资产阶级领导的。第二次护法运动的失败，表明中国旧民主主义革命陷入绝境 ，标志着中国资产阶级领导的旧民主主义革命的终结。答案选D 。"},{"id":"sg-165","globalId":165,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":165,"question":"1927年，汪精卫在武汉制造的屠杀共产党人和革命群众的事变是（ ）。","options":["四一二事变","马日事变","七一五事变","皖南事变"],"answer":2,"answerLetter":"C","explain":"1927 年 7 月 15 日，汪精卫在武汉召开“分共”会议，公开叛变革命，对共产党员和革命群众进 行大屠杀，这就是七一五事变。四一二事变是蒋介石在上海发动的；马日事变是许克祥在长沙发动的；皖南 事变发生于 1941 年。"},{"id":"sg-166","globalId":166,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":166,"question":"1948年1月，在香港正式成立的民主党派是（ ）。","options":["中国民主同盟","中国国民党革命委员会","中国民主建国会","中国农工民主党"],"answer":1,"answerLetter":"B","explain":"1948年1月，中国国民党革命委员会在香港正式成立 。中国民主同盟1941年成立；中国民主建国会 1945年成立；中国农工民主党1930年成立。答案选B。"},{"id":"sg-167","globalId":167,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":167,"question":"国民党在全国统治建立后，官僚资本的垄断活动首先和主要是（ ）。","options":["从农业方面开始的","从重工业方面开始的","从商业方面开始的","从金融业方面开始的"],"answer":3,"answerLetter":"D","explain":"国民党统治时期，官僚资本的垄断活动，首先和主要的是在金融业方面开始的。官僚资本通过控制 金融机构，滥发纸币，造成通货膨胀等，掠夺财富。"},{"id":"sg-168","globalId":168,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":168,"question":"新中国发展国民经济第一个五年计划的中心环节是（ ）。","options":["优先发展轻工业","优先发展重工业","重点发展农村经济","重点发展城市经济"],"answer":1,"answerLetter":"B","explain":"新中国第一个五年计划以“一化三改”为核心，“一化”即社会主义工业化，而实现工业化的中心 环节是优先发展重工业，因为重工业是国家工业化和国防现代化的基础。"},{"id":"sg-169","globalId":169,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":169,"question":"中国资产阶级领导的民主革命进入到一个新阶段的标志是（ ）。","options":["兴中会的成立","华兴会的成立","光复会的成立","中国同盟会的成立"],"answer":3,"answerLetter":"D","explain":"中国同盟会是近代中国第一个全国性的资产阶级革命政党，它的成立使资产阶级民主革命有了统一 的领导和明确的奋斗目标，标志着中国资产阶级领导的民主革命进入新阶段。兴中会、华兴会、光复会都是 早期的资产阶级革命团体，不具备使革命进入新阶段这一意义。"},{"id":"sg-170","globalId":170,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":170,"question":"洪秀全在广西发动金田起义的时间是（ ）。","options":["1851年","1853年","1856年","1864年"],"answer":0,"answerLetter":"A","explain":"1851年1月，洪秀全在广西金田村发动起义，建号太平天国 。所以选A。"},{"id":"sg-171","globalId":171,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":171,"question":"新中国建立初期通过没收官僚资本建立了（ ）。","options":["合作社经济","国家资本主义经济","国营经济","民族资本主义经济"],"answer":2,"answerLetter":"C","explain":"新中国建立初期没收官僚资本，将其转化为社会主义性质的国营经济，使国家掌握了经济命脉。合 作社经济是通过对个体农业、手工业改造发展而来；国家资本主义经济是对资本主义工商业改造过程中的一 种经济形式；民族资本主义经济是中国旧有的经济成分，不是通过没收官僚资本建立。"},{"id":"sg-172","globalId":172,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":172,"question":"中华人民共和国的成立标志着中国进入（ ）。","options":["资本主义社会","社会主义初级阶段","新民主主义社会","社会主义中级阶段"],"answer":2,"answerLetter":"C","explain":"新中国成立初期，中国社会的性质是新民主主义社会 。直到1956年底社会主义改造基本完成，才进 入社会主义初级阶段。资本主义社会不符合中国发展轨迹，也不存在社会主义中级阶段这种表述。"},{"id":"sg-173","globalId":173,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":173,"question":"1950年6月，中国共产党为争取国家财政经济状况的基本好转而召开的重要会议是（ ）。","options":["中共七届二中全会","中共七届三中全会","中共七届四中全会","中共七届五中全会"],"answer":1,"answerLetter":"B","explain":"1950 年 6 月召开的中共七届三中全会，确定了当时全党和全国人民的中心任务是要在三年左右的 时间内，争取国家财政经济状况的基本好转。A 选项中共七届二中全会是 1949 年召开，主要是工作重心转 移等问题；C 选项中共七届四中全会 1954 年召开；D 选项中共七届五中全会 1955 年召开。答案：B。"},{"id":"sg-174","globalId":174,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":174,"question":"将社会主义初级阶段基本路线概括为“一个中心，两个基本点”的会议是（ ）。","options":["中共十二大","中共十三大","中共十五大","中共十六大"],"answer":1,"answerLetter":"B","explain":"中共十三大系统阐述了社会主义初级阶段理论，明确概括了党在社会主义初级阶段的基本路线，即 “一个中心，两个基本点”。“一个中心”是以经济建设为中心，“两个基本点”是坚持四项基本原则，坚 持改革开放。"},{"id":"sg-175","globalId":175,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":175,"question":"鸦片战争后，提出“师夷长技以制夷”思想的是（ ）。","options":["林则徐","王韬","龚自珍","魏源"],"answer":3,"answerLetter":"D","explain":"魏源在《海国图志》中明确提出“师夷长技以制夷”思想，主张学习西方先进技术来抵御西方侵略 。"},{"id":"sg-176","globalId":176,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":176,"question":"严复1898年翻译出版的《天演论》所宣传的思想是（ ）。","options":["师夷长技以制夷","中学为体、西学为用","振兴中华","物竞天择、适者生存"],"answer":3,"answerLetter":"D","explain":"《天演论》主要宣传了达尔文的进化论思想，核心观点是“物竞天择、适者生存”。A选项“师夷长 技以制夷”是魏源在《海国图志》中提出；B选项“中学为体、西学为用”是洋务派主张；C选项“振兴中华 ”是孙中山提出。"},{"id":"sg-177","globalId":177,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":177,"question":"资本—帝国主义列强对近代中国的侵略，首先和主要进行的是（ ）。","options":["军事侵略","政治控制","经济掠夺","文化渗透"],"answer":0,"answerLetter":"A","explain":"资本—帝国主义列强侵略中国，军事侵略是最首要的手段，通过军事侵略打开中国大门，进而实现 政治控制、经济掠夺和文化渗透等。答案：A。"},{"id":"sg-178","globalId":178,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":178,"question":"严复将英国人赫胥黎的《进化与伦理》的前两章翻译为（ ）。","options":["《天演论》","《穆勒名学》","《原富》","《法意》"],"answer":0,"answerLetter":"A","explain":"严复翻译的《天演论》是将赫胥黎《进化与伦理》前两章进行编译，宣传“物竞天择，适者生存 ”思想。"},{"id":"sg-179","globalId":179,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":179,"question":"遵义会议后，中共中央政治局成立了新的三人团负责红军的军事行动，其成员是（ ）。","options":["毛泽东、朱德、周恩来","毛泽东、朱德、王稼祥","毛泽东、周恩来、王稼祥","毛泽东、张闻天、周恩来"],"answer":2,"answerLetter":"C","explain":"遵义会议后成立的新三人团成员是毛泽东、周恩来、王稼祥 。这三人在当时红军军事指挥方面发挥 了关键作用。"},{"id":"sg-180","globalId":180,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":180,"question":"1928年底，在东北宣布“遵守三民主义，服从国民政府，改易旗帜”的是（ ）。","options":["张作霖","张学良","阎锡山","杨虎城"],"answer":1,"answerLetter":"B","explain":"1928年底张学良在东北宣布“遵守三民主义，服从国民政府，改易旗帜”，史称东北易帜，至此国 民政府在形式上基本统一全国 。答案选B。"},{"id":"sg-181","globalId":181,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":181,"question":"1956年召开的中共八大指出，党和全国人民当前的主要任务是（ ）。","options":["争取国家财政经济状况的根本好转","完成社会主义改造","正确处理人民内部矛盾","把我国从落后的农业国变为先进的工业国"],"answer":3,"answerLetter":"D","explain":"中共八大正确分析了社会主义改造完成后中国社会的主要矛盾和主要任务，指出国内的主要矛盾已 经是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，是人民对于经济文化迅速发展的 需要同当前经济文化不能满足人民需要的状况之间的矛盾。党和全国人民的主要任务是集中力量发展社会生 产力，把我国尽快地从落后的农业国变为先进的工业国。"},{"id":"sg-182","globalId":182,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":182,"question":"近代中国历史上第一个资产阶级革命组织是（ ）。","options":["兴中会","中国同盟会","华兴会","光复会"],"answer":0,"answerLetter":"A","explain":"兴中会是孙中山于1894 年在檀香山建立，是近代中国第一个资产阶级革命组织。中国同盟会是近代 中国第一个全国性的资产阶级革命政党；华兴会、光复会是资产阶级革命团体但成立时间晚于兴中会。答案 ：A"},{"id":"sg-183","globalId":183,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":183,"question":"洋务派在1862年创办的翻译学堂是（ ）。","options":["京师同文馆","广方言馆","译书局","译书馆"],"answer":0,"answerLetter":"A","explain":"1862年，洋务派创办京师同文馆，它是近代中国第一所新式学堂，是翻译学堂。广方言馆创办时间 晚于京师同文馆；译书局、译书馆不属于洋务派1862年创办的翻译学堂。"},{"id":"sg-184","globalId":184,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":184,"question":"1930年5月，毛泽东撰写的关于坚持辩证唯物主义思想路线的著作是（ ）。","options":["《中国的红色政权为什么能够存在》","《井冈山的斗争》","《星星之火，可以燎原》","《反对本本主义》"],"answer":3,"answerLetter":"D","explain":"1930年5月毛泽东写的《反对本本主义》，阐明了坚持辩证唯物主义的思想路线即坚持理论与实际相 结合的原则的极端重要性，表现了毛泽东开辟新道路、创造新理论的革命首创精神。答案：D 。"},{"id":"sg-185","globalId":185,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":185,"question":"1959年，在中共中央召开的庐山会议上受到错误批判的是（ ）。","options":["刘少奇","彭德怀","周恩来","邓小平"],"answer":1,"answerLetter":"B","explain":"1959 年庐山会议原本是为了总结经验教训、调整指标、继续纠正“左”倾错误而召开，彭德怀同志 写信给毛泽东主席，对“大跃进”和人民公社化运动中的错误提出批评，却遭到错误批判。答案选B。"},{"id":"sg-186","globalId":186,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":186,"question":"近代中国派遣第一批留学生是在（ ）。","options":["洋务运动时期质","戊戌维新时期","清末“新政”时期","辛亥革命时期"],"answer":0,"answerLetter":"A","explain":"洋务运动为了培养洋务人才，1872 年到 1875 年，清政府先后选派 120 名幼童赴美留学，这是近 代中国派遣的第一批留学生 。戊戌维新时期、清末“新政”时期、辛亥革命时期均晚于洋务运动派遣留学生 时间 。"},{"id":"sg-187","globalId":187,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":187,"question":"近代中国向西方派遣第一批留学生是在（ ）。","options":["洋务运动时期","戊戌维新时期","清末“新政”时期","辛亥革命时期"],"answer":0,"answerLetter":"A","explain":"洋务运动为培养洋务人才，在19世纪70 - 90年代，先后派遣4批幼童赴美留学 ，这是近代中国向西 方派遣的第一批留学生。答案：A。"},{"id":"sg-188","globalId":188,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":188,"question":"洋务运动时期，清政府建立的新式海军的主力是（ ）。","options":["福建水师","北洋水师","南洋水师","广东水师"],"answer":1,"answerLetter":"B","explain":"洋务运动创办新式海军，其中北洋水师是清政府海军的主力，规模最大、实力最强。"},{"id":"sg-189","globalId":189,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":189,"question":"1931年11月，中国共产党在江西瑞金召开的重要会议是（ ）。","options":["中共六届四中全会","红四军第九次党的代表大会","中华苏维埃第一次全国代表大会","赣南会议"],"answer":2,"answerLetter":"C","explain":"1931年11月在江西瑞金召开的是中华苏维埃第一次全国代表大会，这次会议宣告中华苏维埃共和国 临时中央政府成立 。A选项中共六届四中全会在上海召开；B选项红四军第九次党的代表大会即古田会议，在 福建上杭古田召开；D选项赣南会议在江西瑞金召开，但时间与题干不符。"},{"id":"sg-190","globalId":190,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":190,"question":"1966年至1976年间在我国发生的全局性、长时间的“左”倾严重错误是（ ）。","options":["“大跃进”","人民公社运动","反右派斗争扩大化","“文化大革命”"],"answer":3,"answerLetter":"D","explain":"“文化大革命 ”发生于1966 - 1976 年，是一场给党、国家和各族人民带来严重灾难的内乱，造成 了全局性、长时间的 “左” 倾严重错误。“大跃进”和人民公社运动主要发生在1958 - 1960 年；反右派 斗争扩大化发生在1957 年。"},{"id":"sg-191","globalId":191,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":191,"question":"抗日战争胜利后，国共双方通过重庆谈判签订《政府与中共代表会谈纪要》的时间是（ ）。","options":["1945年8月","1945年9月","1945年10月","1945年11月"],"answer":2,"answerLetter":"C","explain":"1945 年 10 月 10 日，国共双方签订《政府与中共代表会谈纪要》即双十协定 。所以答案是C。"},{"id":"sg-192","globalId":192,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":192,"question":"以蒋介石为首的国民党南京政权建立后，官僚资本的垄断活动首先和主要是（ ）。","options":["从重工业方面开始的","从金融业方面开始的","从商业方面开始的","从农业方面开始的"],"answer":1,"answerLetter":"B","explain":"官僚资本要实现对全国经济的控制，金融是关键领域。国民党统治集团通过建立“四行二局”等金 融机构，开始其垄断活动，以此为基础进而控制其他行业。答案：B 。"},{"id":"sg-193","globalId":193,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":193,"question":"抗日战争时期，中国共产党开展的延安整风运动最主要的任务是（ ）。","options":["反对主观主义以整顿学风","反对宗派主义以整顿党风","反对官僚主义以整顿作风","反对党八股以整顿文风"],"answer":0,"answerLetter":"A","explain":"延安整风运动的主要内容是反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整 顿文风，其中最主要任务是反对主观主义整顿学风，主观主义是中国共产党内反复出现“左”、右倾错误的 思想认识根源。"},{"id":"sg-194","globalId":194,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":194,"question":"鲁迅在《新青年》上发表的第一篇白话小说是（ ）。","options":["《孔乙己》","《药》","《狂人日记》","《阿Q正传》"],"answer":2,"answerLetter":"C","explain":"鲁迅于1918年5月在《新青年》发表《狂人日记》，这是中国第一部现代白话文小说。而《孔乙己》 《药》《阿Q正传》发表时间晚于《狂人日记》。"},{"id":"sg-195","globalId":195,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":195,"question":"在1860年洗劫和烧毁圆明园的外国侵略者是（ ）。","options":["日本侵略军","俄国侵略军","英法联军","八国联军"],"answer":2,"answerLetter":"C","explain":"1860 年第二次鸦片战争期间，英法联军攻占北京后洗劫并烧毁圆明园。日本侵略军主要罪行多在甲 午战争及抗日战争期间；俄国侵略军在近代主要是割占中国大片领土；八国联军侵华是 1900 年。答案：C。"},{"id":"sg-196","globalId":196,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":196,"question":"1933年11月，在福州发动抗日反蒋事变的国民党爱国将领是（ ）。","options":["马占山和李杜","冯玉祥和吉鸿昌","蔡廷锴和蒋光鼐","张学良和杨虎城"],"answer":2,"answerLetter":"C","explain":"1933 年 11 月发动福建事变（即抗日反蒋事变）的是蔡廷锴和蒋光鼐等率领的第十九路军 。A 选 项马占山、李杜主要是在东北抗日；B 选项冯玉祥、吉鸿昌组织察哈尔民众抗日同盟军；D 选项张学良、杨 虎城发动西安事变。所以答案是C。"},{"id":"sg-197","globalId":197,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":197,"question":"1978年，我国开展的一场马克思主义思想解放运动是（ ）。","options":["揭批“四人帮”","关于真理标准问题的大讨论","平反冤假错案","关于社会主义市场经济问题的大讨论"],"answer":1,"answerLetter":"B","explain":"1978 年开展的关于真理标准问题的大讨论，是一场马克思主义思想解放运动，它打破了长期以来个 人崇拜和教条主义的束缚，为拨乱反正、开启改革开放新时期作了重要的思想准备。A 选项揭批“四人帮 ”主要是政治上批判其罪行；C 选项平反冤假错案是落实政策工作；D 选项关于社会主义市场经济问题的大 讨论在 20 世纪 90 年代。"},{"id":"sg-198","globalId":198,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":198,"question":"毛泽东《论十大关系》报告围绕的基本方针是（ ）。","options":["独立自主","自力更生为主，争取外援为辅","调动一切积极因素，为社会主义事业服务","走中国特色社会主义道路"],"answer":2,"answerLetter":"C","explain":"《论十大关系》的报告确定了一个基本方针，就是“努力把党内党外、国内国外的一切积极的因素 ，直接的、间接的积极因素全部调动起来”，为社会主义建设服务 。"},{"id":"sg-199","globalId":199,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":199,"question":"在近代中国，洋务派开展洋务运动的指导思想是（ ）。","options":["“师夷长技以制夷”","“中学为体，西学为用”","“物竞天择，适者生存”","“启迪民智，除旧布新”"],"answer":1,"answerLetter":"B","explain":"洋务派的指导思想是“中学为体，西学为用”，意思是在维护清王朝封建统治的基础上，采用西方 先进技术。A选项“师夷长技以制夷”是魏源提出，是早期向西方学习思想的萌芽，但不是洋务派指导思想 ；C选项“物竞天择，适者生存”是严复翻译《天演论》传播的思想，为维新变法提供理论依据；D选项“启 迪民智，除旧布新”与维新派等相关，强调思想启蒙等。"},{"id":"sg-200","globalId":200,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":200,"question":"1934年中国工农红军第五次反“围剿”斗争失败后，率先开始战略转移的是（ ）。","options":["红十五军团","红一方面军","红二方面军","红四方面军"],"answer":1,"answerLetter":"B","explain":"1934 年第五次反“围剿”失败后率先开始战略转移的是红一方面军，也就是中央红军，答案选B 。"},{"id":"sg-201","globalId":201,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":201,"question":"1979年，邓小平在中央理论工作务虚会上首次明确提出，必须坚持（ ）。","options":["拨乱反正","解放思想","四项基本原则","以经济建设为中心"],"answer":2,"answerLetter":"C","explain":"1979年，邓小平在中央理论工作务虚会上首次明确提出必须坚持四项基本原则。四项基本原则是立 国之本，对稳定社会秩序、推动改革开放等具有重要意义。所以答案选C。"},{"id":"sg-202","globalId":202,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":202,"question":"1979年元旦，全国人大常委会发表的重要文献是（ ）。","options":["《一个国家，两种制度》","《告台湾同胞书》","《实现两岸和平统一的九项方针》","《反国家分裂法》"],"answer":1,"answerLetter":"B","explain":"1979年元旦，全国人大常委会发表《告台湾同胞书》，郑重宣示争取祖国和平统一的大政方针。A选 项《一个国家，两种制度》是1984 年邓小平提出；C选项《实现两岸和平统一的九项方针》是1995 年江泽民 提出；D选项《反国家分裂法》是2005 年通过。答案选B。"},{"id":"sg-203","globalId":203,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":203,"question":"毛泽东系统阐明农业合作化理论的重要文献是（ ）。","options":["《介绍一个合作社》","《关于农业合作化问题》","《组织起来》","《中国农村的社会主义高潮》"],"answer":1,"answerLetter":"B","explain":"1955 年 7 月 31 日，毛泽东在省、市、自治区党委书记会议上作《关于农业合作化问题》的报告 ，系统阐述了农业合作化理论 。答案：B 。"},{"id":"sg-204","globalId":204,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":204,"question":"在抗日战争的芦淞会站中，率领“八百壮士”孤军据守四行仓库的爱国将领是（ ）。","options":["佟麟阁","赵登禹","戴安澜","谢晋元"],"answer":3,"answerLetter":"D","explain":"在淞沪会战中，率领“八百壮士”坚守四行仓库的是谢晋元。佟麟阁、赵登禹是在北平保卫战中牺 牲；戴安澜是在入缅作战中殉国。"},{"id":"sg-205","globalId":205,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":205,"question":"1935年，中国共产党提出建立抗日民族统一战线的会议是（ ）。","options":["瓦窑堡会议","洛川会议","中共六届六中全会","中共六届七中全会"],"answer":0,"answerLetter":"A","explain":"1935 年 12 月，中共中央在瓦窑堡召开政治局会议，提出了在抗日的条件下与民族资产阶级重建统 一战线的新政策，即建立抗日民族统一战线。洛川会议主要是制定全面抗战路线等；中共六届六中全会提出 “马克思主义中国化”命题等；中共六届七中全会通过《关于若干历史问题的决议》等。答案：A。"},{"id":"sg-206","globalId":206,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":206,"question":"毛泽东于1928年12月主持制定的中国共产党历史上第一个土地法是（ ）。","options":["《井冈山土地法》","《兴国土地法》","《关于清算、减租及土地问题的指示》","《中国土地法大纲》"],"answer":0,"answerLetter":"A","explain":"1928 年 12 月毛泽东在井冈山主持制定了中国共产党历史上第一个土地法即《井冈山土地法》 。B 项《兴国土地法》是 1929 年制定；C 项《关于清算、减租及土地问题的指示》1946 年发布；D 项《中国土 地法大纲》1947 年颁布。"},{"id":"sg-207","globalId":207,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":207,"question":"在抗日战争的战略防御阶段，国民党军队在正面战场上取得胜利的战役是（ ）。","options":["台儿庄战役","桂南战役","枣宜战役","中条山战役"],"answer":0,"answerLetter":"A","explain":"在抗日战争战略防御阶段，台儿庄战役是国民党军队在正面战场取得的重大胜利。它打击了日军的 嚣张气焰，振奋了全国军民的抗战信心。桂南、枣宜、中条山战役都不是发生在战略防御阶段取得胜利的战 役。"},{"id":"sg-208","globalId":208,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":208,"question":"1935年10月，中央红军同红十五军团胜利会师于（ ）。","options":["四川懋功地区","西康甘孜地区","甘肃会宁、静宁地区","陕北吴起镇"],"answer":3,"answerLetter":"D","explain":"1935 年 10 月，中央红军到达陕北吴起镇，与红十五军团胜利会师。A 选项四川懋功地区是 1935 年 6 月中央红军与红四方面军会师地；B 选项西康甘孜地区是 1936 年 7 月红二、红四方面军会师地；C 选项甘肃会宁、静宁地区是 1936 年 10 月三大主力红军会师地。答案：D。"},{"id":"sg-209","globalId":209,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":209,"question":"1988年，中共中央和国务院决定建立的经济特区是（ ）。","options":["海南经济特区","珠海经济特区","厦门经济特区","深圳经济特区"],"answer":0,"answerLetter":"A","explain":"1988年，中共中央和国务院决定建立海南经济特区 。珠海、厦门、深圳经济特区设立时间早于 1988年。答案选A。"},{"id":"sg-210","globalId":210,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":210,"question":"1935年1月，中国共产党在遵义会议上解决的主要问题是（ ）。","options":["军事和组织问题","思想和作风问题","政治和军事问题","筹款和征兵问题"],"answer":0,"answerLetter":"A","explain":"遵义会议集中全力解决当时具有决定意义的军事问题和组织问题，结束王明“左”倾教条主义在中 央的统治，确立了以毛泽东为代表的马克思主义的正确路线在中共中央的领导地位。"},{"id":"sg-211","globalId":211,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":211,"question":"1990年3月，中共十三届六中全会通过了（ ）。","options":["《关于科学技术体制改革的决定》","《关于教育体制改革的决定》","《关于加强党同人民群众联系的决定》","《关于加强党的执政能力建设的决定》"],"answer":2,"answerLetter":"C","explain":"1990年3月，中共十三届六中全会通过《关于加强党同人民群众联系的决定》 。A选项《关于科学技 术体制改革的决定》是1985年3月作出；B选项《关于教育体制改革的决定》是1985年5月作出；D选项《关于 加强党的执政能力建设的决定》是2004年9月中共十六届四中全会通过。"},{"id":"sg-212","globalId":212,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":212,"question":"毛泽东在1957年指出，我国国家政治生活的主题是正确处理（ ）。","options":["敌我矛盾","人民内部矛盾","生产关系与生产力的矛盾","上层建筑与经济基础的矛盾"],"answer":1,"answerLetter":"B","explain":"1957 年毛泽东发表《关于正确处理人民内部矛盾的问题》，指出在社会主义制度下，人民的根本利 益是一致的，但还存在着敌我矛盾和人民内部矛盾，国家政治生活的主题是正确处理人民内部矛盾。答案选 B。"},{"id":"sg-213","globalId":213,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":213,"question":"在中共八大上，陈云提出的重要思想是（ ）。","options":["双重监督","“三个主体，三个补充”","健全法制","“两条腿”走路"],"answer":1,"answerLetter":"B","explain":"在中共八大上，陈云提出了“三个主体，三个补充”的思想，即国家经营和集体经营是主体，一定 数量的个体经营为补充；计划生产是主体，一定范围的自由生产为补充；国家市场是主体，一定范围的自由 市场为补充 。"},{"id":"sg-214","globalId":214,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":214,"question":"1935年中国共产党北平临时工作委员会领导发动的抗日救亡运动是是（ ）。","options":["五卅运动","一二·九运动","一二·一运动","一二·三零运动"],"answer":1,"answerLetter":"B","explain":"1935 年，在民族危机日益加深的形势下，中国共产党北平临时工作委员会领导发动了一二·九运动 ，这是一场大规模的抗日救亡运动。五卅运动发生于 1925 年；一二·一运动是 1945 年发生在昆明的反内 战、争民主运动；不存在一二·三零运动。答案：B。"},{"id":"sg-215","globalId":215,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":215,"question":"在中国近代史上，资产阶级思想和封建主义思想的第一次正面交锋是（ ）。","options":["洋务派与顽固派的论战","洋务派与维新派的论战","维新派与守旧派的论战","革命派与改良派的论战"],"answer":2,"answerLetter":"C","explain":"维新派与守旧派的论战，实质是资产阶级思想与封建主义思想在中国的第一次正面交锋 。论战涉及 要不要变法，要不要兴民权、设议院、实行君主立宪，要不要废八股、改科举和兴西学等问题，传播了新思 想。A选项洋务派与顽固派论战围绕是否学习西方科技等，本质都维护封建统治；B选项洋务派与维新派不是 思想正面交锋；D选项革命派与改良派论战在维新派与守旧派论战后，是资产阶级内部不同政治主张的较量。"},{"id":"sg-216","globalId":216,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":216,"question":"1936年10月，中国工农红军第一、二、四方面军胜利会师于（ ）。","options":["陕北保安地区","陕北洛川地区","陕北瓦窑堡地区","甘肃会宁、静宁地区"],"answer":3,"answerLetter":"D","explain":"1936年10月，红二、红四方面军先后同红一方面军在甘肃会宁、静宁及将台堡地区会师，标志着长 征胜利结束。所以答案是D。"},{"id":"sg-217","globalId":217,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":217,"question":"早在1836年就扬言要用武力打开中国门的是（ ）。","options":["国驻华商务监督义律","美国驻华公使田贝","德国传教士郭士立","法国传教士孟振生"],"answer":0,"answerLetter":"A","explain":"1836 年，英国驻华商务监督义律扬言要用武力打开中国国门，这与英国当时企图通过鸦片贸易扭转 贸易逆差，进而打开中国市场，进行殖民扩张的背景相关。答案：A 。"},{"id":"sg-218","globalId":218,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":218,"question":"清王朝由强盛转向衰落是在（ ）。","options":["乾隆朝后期","嘉庆朝中期","咸丰朝后期","同治朝中期"],"answer":0,"answerLetter":"A","explain":"乾隆朝后期，清朝统治由盛转衰，政治上吏治腐败，经济上土地兼并严重，军事上军备废弛等各种 社会矛盾加剧。答案选A。"},{"id":"sg-219","globalId":219,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":219,"question":"正式提出以人为本、全面协调可持续的科学发展观的会议是（ ）。","options":["中共十五届五中全会","中共十五届六中全会","中共十六届三中全会","中共十六届四中全会"],"answer":2,"answerLetter":"C","explain":"2003 年 10 月，中共十六届三中全会正式提出以人为本、全面协调可持续的科学发展观。答案选 C。"},{"id":"sg-220","globalId":220,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":220,"question":"19世纪60年代，洋务派最早从事的洋务事业是（ ）。","options":["兴办民用工业","创立新式学堂","派遣留学生","兴办军用工业"],"answer":3,"answerLetter":"D","explain":"19世纪60年代，洋务派以“自强”为旗号，最早从事的洋务事业是兴办军用工业，目的是增强军事 力量，抵御外侮。所以答案是D。"}]) : [{"id":"sg-1","globalId":1,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":1,"question":"19世纪末，在帝国主义列强瓜分中国的狂潮中提出“门户开放”政策的国家是（ ）。","options":["美国","日本","俄国","德国"],"answer":0,"answerLetter":"A","explain":"19世纪末，各国在中国划分势力范围时，美国忙于美西战争，无暇顾及中国。美西战争结束后，美 国为分享侵略权益，于1899年向英、俄、德、日、意、法六国提出“门户开放”政策。答案选A。"},{"id":"sg-2","globalId":2,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":2,"question":"太平天国后期，洪仁玕提出的改革与建设方案是（ ）。","options":["（原道觉世训》","《十救天条）","《天朝田亩制度》","《资政新篇》"],"answer":3,"answerLetter":"D","explain":"《原道觉世训》《十救天条》是太平天国早期洪秀全等人的著述；《天朝田亩制度》是太平天国前 期颁布的纲领性文件；而《资政新篇》是太平天国后期洪仁玕提出的改革与建设方案，具有鲜明的资本主义 色彩。"},{"id":"sg-3","globalId":3,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":3,"question":"中共十三大明确将党在社会主义初级阶段的基本路线概括为（ ）。","options":["“一个中心，两个基本点”","“四个坚持”","一手抓物质文明，一手抓精神文明","建设中国特色社会主义经济、政治和文化"],"answer":0,"answerLetter":"A","explain":"中共十三大明确提出党在社会主义初级阶段的基本路线，即领导和团结全国各族人民，以经济建设 为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的 社会主义现代化国家而奋斗，简称为“一个中心，两个基本点” 。"},{"id":"sg-4","globalId":4,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":4,"question":"1839年组织编写成《四洲志》，向中国人介绍西方情况的是（ ）。","options":["林则徐","魏源","马建忠","郑观应"],"answer":0,"answerLetter":"A","explain":"林则徐是近代中国睁眼看世界的第一人，1839 年他组织编译《四洲志》，介绍西方情况。魏源在《 四洲志》基础上编成《海国图志》；马建忠、郑观应是 19 世纪 70 - 90 年代的早期维新思想家。答案 ：A。"},{"id":"sg-5","globalId":5,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":5,"question":"1938年6月间，毛泽东发表的系统论述抗日战争特点.前途和发展规律的著作是（ ）。","options":["论反对日本帝国主义的策略","抗日救国十大纲领.","论持久战","对日寇的最后一站"],"answer":2,"answerLetter":"C","explain":"1938 年 6 月毛泽东发表《论持久战》，系统阐明了抗日战争的特点、前途和发展规律，为全国抗 战指明方向。A 选项《论反对日本帝国主义的策略》主要论述建立抗日民族统一战线；B 选项《抗日救国十 大纲领》主要是全面抗战路线相关；D 选项《对日寇的最后一战》发布于抗战即将胜利时。答案：C。"},{"id":"sg-6","globalId":6,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":6,"question":"2002年2月，江泽民在广东考察工作时提出了（ ）。","options":["“三讲”教育的要求","“八个坚持，八个反对”的要求","“三个代表”重要思想","以“八荣八耻”为主要内容的社会主义荣辱观"],"answer":2,"answerLetter":"C","explain":"2000 年 2 月，江泽民在广东考察工作时，首次提出“三个代表”重要思想 。“三讲”教育是 1995 年提出；“八个坚持，八个反对”是 2001 年提出；以“八荣八耻”为主要内容的社会主义荣辱观是 2006 年提出。答案选C。"},{"id":"sg-7","globalId":7,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":7,"question":"中共十四大明确提出，我国经济体制改革的目标是建立（ ）。","options":["社会主义市场经济体制","市场为主、计划为辅的经济体制","社会主义计划经济体制","社会主义有计划的商品经济体制"],"answer":0,"answerLetter":"A","explain":"1992 年中共十四大明确提出我国经济体制改革的目标是建立社会主义市场经济体制 。"},{"id":"sg-8","globalId":8,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":8,"question":"1851年，中国爆发的一场伟大的农民战争是（ ）。","options":["三元里人民抗英斗争","太平天国运动","台湾高山族人民抗日斗争","义和团运动"],"answer":1,"answerLetter":"B","explain":"1851 年洪秀全领导发动金田起义，太平天国运动爆发，它是一场伟大的农民战争。A 选项三元里人 民抗英斗争发生于 1841 年；C 选项台湾高山族人民抗日斗争主要是在《马关条约》割让台湾后；D 选项义 和团运动兴起于 19 世纪末。"},{"id":"sg-9","globalId":9,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":9,"question":"1939年1月，国民党制定“防共.限共.溶共.反共”方针的会议是（ ）。","options":["五届三中全会","五届四中全会","五届五中全会","五届六中全会"],"answer":2,"answerLetter":"C","explain":"1939年1月，国民党五届五中全会决定成立“防共委员会”，确定了“防共、限共、溶共、反共”的 方针。这一方针标志着国民党由片面抗战逐步转变为消极抗战、积极反共。答案选C。"},{"id":"sg-10","globalId":10,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":10,"question":"2005年，第十届全国人民代表大会第三次会议通过的法律是（ ）。","options":["《香港特别行政区基本法》","《澳门特别行政区基本法》","《国家安全法》","《反分裂国家法》"],"answer":3,"answerLetter":"D","explain":"2005 年第十届全国人民代表大会第三次会议通过《反分裂国家法》，旨在反对和遏制“台独”分裂 势力分裂国家，促进祖国和平统一 。A 选项《香港特别行政区基本法》于 1990 年通过；B 选项《澳门特别 行政区基本法》于 1993 年通过；C 选项现行《国家安全法》是 2015 年通过 。答案：D 。"},{"id":"sg-11","globalId":11,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":11,"question":"中共中央明确提出“和平、民主、团结”的口号是（ ）。","options":["1943年8月25日","1944年8月25日","1945年8月25日","1946年8月25日"],"answer":2,"answerLetter":"C","explain":"1945 年 8 月 25 日，中共中央在对时局的宣言中明确提出“和平、民主、团结”的口号。答案 ：C。"},{"id":"sg-12","globalId":12,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":12,"question":"“文化大革命”结束的主要标志是（ ）。","options":["林彪反革命集团的覆灭","邓小平的复出","江青反革命集团的垮台","“天安门事件”的平反"],"answer":2,"answerLetter":"C","explain":"答案：C“文化大革命”结束的主要标志是江青反革命集团的垮台，这标志着“文化大革命”的正式 结束。因此，正确答案为C。"},{"id":"sg-13","globalId":13,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":13,"question":"1937年8月，中国共产党制定《抗日救国十大纲领》的会议是（ ）。","options":["六届五中全会","瓦窑堡会议","洛川会议","六届六中全会"],"answer":2,"answerLetter":"C","explain":"1937年8月，中共中央在陕北洛川召开政治局扩大会议，制定了《抗日救国十大纲领》，强调要打倒 日本帝国主义，关键在于使已经发动的抗战成为全面的全民族的抗战。A选项六届五中全会1934 年召开；B选 项瓦窑堡会议1935年召开，提出抗日民族统一战线政策；D选项六届六中全会1938年召开。"},{"id":"sg-14","globalId":14,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":14,"question":"19世纪60年代到90年代，洋务派兴办洋务事业的指导思想是（ ）。","options":["师夷长技以制夷","中学为体，西学为用","物竞天择，适者生存","变法维新，救亡图存"],"answer":1,"answerLetter":"B","explain":"“师夷长技以制夷”是魏源《海国图志》提出的，早于洋务运动，A 不符；“中学为体，西学为用 ”是洋务派兴办洋务事业的指导思想，强调以中国封建纲常伦理为根本，采用西方先进科技，B 正确；“物 竞天择，适者生存”是严复翻译《天演论》宣传的思想，非洋务派指导思想，C 不符；“变法维新，救亡图 存”是维新派主张，D 不符。"},{"id":"sg-15","globalId":15,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":15,"question":"日本在甲午战争后迫使清政府签订了（ ）。","options":["《天津条约》","《北京条约》","《马关条约》","《辛丑条约》"],"answer":2,"answerLetter":"C","explain":"甲午战争清政府战败后，1895 年被迫与日本签订《马关条约》。A 选项《天津条约》是第二次鸦片 战争签订；B 选项《北京条约》也是第二次鸦片战争签订；D 选项《辛丑条约》是八国联军侵华后签订。答 案：C。"},{"id":"sg-16","globalId":16,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":16,"question":"中共十八大提出，我国到2020年的奋斗目标是（ ）。","options":["实现“四个现代化”","基本实现现代化","全面建设小康社会","全面建成小康社会"],"answer":3,"answerLetter":"D","explain":"中共十八大提出到2020年全面建成小康社会的奋斗目标。“四个现代化”是过去提出的概念；基本 实现现代化是2035年目标；之前是全面建设小康社会阶段，十八大强调要建成。"},{"id":"sg-17","globalId":17,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":17,"question":"《共产党宣言》第一个中文全译本的译者是（ ）。","options":["李大钊","陈独秀","陈望道","毛泽东"],"answer":2,"answerLetter":"C","explain":"1920年8月，陈望道翻译的《共产党宣言》第一个中文全译本在上海出版。李大钊、陈独秀、毛泽东 都不是《共产党宣言》第一个中文全译本译者。答案选C。"},{"id":"sg-18","globalId":18,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":18,"question":"1938年，毛泽东发表的系统阐述抗日战争特点、前途和发展规律的著作是（ ）。","options":["《论反对日本帝国主义的策略》","《论持久战》","《论新阶段》","《论联合政府》"],"answer":1,"answerLetter":"B","explain":"1938 年毛泽东发表《论持久战》，系统阐述了抗日战争的特点、前途和发展规律，有力批驳了“亡 国论”和“速胜论”。A 选项《论反对日本帝国主义的策略》主要是论述抗日民族统一战线；C 选项《论新 阶段》是 1938 年提出“马克思主义中国化”；D 选项《论联合政府》是 1945 年中共七大上的报告。答案 ：B 。"},{"id":"sg-19","globalId":19,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":19,"question":"19世纪末，梁启超撰写的宣传变法维新主张的著作是（ ）。","options":["《新学伪经考》","《人类公理》","《仁学》","《变法通义》"],"answer":3,"answerLetter":"D","explain":"A选项《新学伪经考》是康有为著作；B选项《人类公理》也是康有为作品；C选项《仁学》是谭嗣同 著作；D选项《变法通义》是梁启超宣传变法维新主张的著作 。"},{"id":"sg-20","globalId":20,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":20,"question":"台湾人民为反抗国民党当局暴政而举行“二二八”起义的时间是（ ）。","options":["1945年","1946年","1947年","1948年"],"answer":2,"answerLetter":"C","explain":"“二二八”起义发生于1947年2月28日，是台湾人民反对国民党统治的重要起义。答案选C。"},{"id":"sg-21","globalId":21,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":21,"question":"《中国人民政协商会议共同纲领》最基本、最核心的内容是规定了新中国的（ ）。","options":["基本民族政策","国体和政体","经济工作方针","外交工作原则"],"answer":1,"answerLetter":"B","explain":"《中国人民政治协商会议共同纲领》规定了新中国的国体和政体，这是其最基本、最核心的内容 ，国体和政体决定着国家的性质等根本问题，其他政策方针等都以此为基础展开。"},{"id":"sg-22","globalId":22,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":22,"question":"1938年，中国共产党制定《抗日救国十大纲领》的重要会议是（ ）。","options":["瓦窑堡会议","洛川会议","中共六届六中会议","中共六届七中会议"],"answer":1,"answerLetter":"B","explain":"1937年8月，中共中央在陕北洛川召开政治局扩大会议，制定了《抗日救国十大纲领》 ，强调要打 倒日本帝国主义，关键在于使已经发动的抗战成为全面的全民族的抗战。"},{"id":"sg-23","globalId":23,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":23,"question":"太平天国失败的根本原因是（ ）。","options":["没有科学理论的指导","缺乏先进阶级的领导","无法长期保持领导集团的团结","不能正确对待传统文化"],"answer":1,"answerLetter":"B","explain":"太平天国运动是农民阶级领导的运动，农民阶级不是先进生产力的代表，具有自身局限性，这是导 致其失败的根本原因，即缺乏先进阶级的领导。A、C、D选项也是失败原因，但不是根本原因。"},{"id":"sg-24","globalId":24,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":24,"question":"1853年，太平天国定都天京后颁布的纲领性文件是（ ）。","options":["《原道觉世训》","《十款天条》","《天朝田亩制度》","《资政新篇》"],"answer":2,"answerLetter":"C","explain":"1853 年太平天国定都天京后颁布《天朝田亩制度》，它是太平天国的纲领性文件。A 选项《原道觉 世训》是洪秀全早期著作；B 选项《十款天条》是拜上帝会的基本准则；D 选项《资政新篇》1859 年提出。 答案：C 。"},{"id":"sg-25","globalId":25,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":25,"question":"太平天国由盛到衰的转折点是（ ）。","options":["长沙战役","安庆失守","天京事变","北伐受挫"],"answer":2,"answerLetter":"C","explain":"天京事变是太平天国领导集团内部自相残杀的严重事件，它严重削弱了太平天国的领导和军事力量 ，成为太平天国由盛转衰的转折点。答案选C。"},{"id":"sg-26","globalId":26,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":26,"question":"中共中央通过<关于建国以来党的若干历史问题的决议》的会议是（ ）。","options":["十一届三中全会","十一届六中全会","十二届三中全会","十二届六中全会"],"answer":1,"answerLetter":"B","explain":"1981 年 6 月，中共十一届六中全会通过了《关于建国以来党的若干历史问题的决议》，对新中国 成立以来党的重大历史问题特别是“文化大革命”、毛泽东的历史地位及功过是非和毛泽东思想基本内容与 指导意义作了总结和评价。答案：B 。"},{"id":"sg-27","globalId":27,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":27,"question":"1941年3月，在抗日民主运动中成立的民主党派是（ ）。","options":["中国国民党临时行动委员会","中国青年党","中国国家社会党","中国民主政团同盟"],"answer":3,"answerLetter":"D","explain":"1941 年 3 月 19 日，中国民主政团同盟在重庆秘密成立。而中国国民党临时行动委员会是 1930 年成立；中国青年党、中国国家社会党成立时间也并非 1941 年 3 月。答案：D。"},{"id":"sg-28","globalId":28,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":28,"question":"2005年3月，十届全国人大三次会议通过的法律是（ ）。","options":["《反分裂国家法》","《国家安全法》","《香港特别行政区基本法》","《澳门特别行政区基本法》"],"answer":0,"answerLetter":"A","explain":"2005 年 3 月十届全国人大三次会议通过《反分裂国家法》，旨在反对和遏制“台独”分裂势力分 裂国家，促进祖国和平统一。而《国家安全法》有不同时期的版本但并非此次会议通过；《香港特别行政区 基本法》1990 年通过；《澳门特别行政区基本法》1993 年通过。"},{"id":"sg-29","globalId":29,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":29,"question":"谭嗣同在戊戌维新时期撰写的宣传变法维新主张的著作是（ ）。","options":["《新学伪经考》","《变法通义》","《日本变政考》","《仁学》"],"answer":3,"answerLetter":"D","explain":"《仁学》是谭嗣同的著作 。A选项《新学伪经考》是康有为的；B选项《变法通义》是梁启超的 ；C选项《日本变政考》是康有为的。"},{"id":"sg-30","globalId":30,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":30,"question":"中国的社会生产力在改革开放后迅速发展，到2006年经济总量已居世界（ ）。","options":["第二位","第三位","第四位","第五位"],"answer":2,"answerLetter":"C","explain":"2006 年中国经济总量居世界第四位。2010 年中国经济总量超越日本成为世界第二。所以 2006 年 应选第四位。"},{"id":"sg-31","globalId":31,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":31,"question":"20世纪初，在民主革命思想传播中发表《警世钟》的是（ ）。","options":["章炳麟","邹容","陈天华","孙中山"],"answer":2,"answerLetter":"C","explain":"陈天华在民主革命思想传播中发表了《警世钟》等著作，以通俗的语言宣传革命思想。章炳麟的代 表作是《驳康有为论革命书》，邹容的是《革命军》，孙中山主要是领导革命实践等。"},{"id":"sg-32","globalId":32,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":32,"question":"1945年8月至10月，国共双方举行了商讨和平建国方针的（ ）。","options":["重庆谈判","西安谈判","南京谈判","北平谈判"],"answer":0,"answerLetter":"A","explain":"1945 年 8 月至 10 月，为避免内战、争取和平，国共双方在重庆进行了关于和平建国的谈判，即 重庆谈判 。西安谈判是为解决西安事变；南京谈判是 1946 年；北平谈判是 1949 年 。所以符合时间和主 题的是重庆谈判。答案：A 。"},{"id":"sg-33","globalId":33,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":33,"question":"20世纪初，资产阶级革命派与改良派论战的焦点是（ ）。","options":["要不要变法","要不要建立民主共和国","要不要社会革命","要不要以革命手段推翻清政府"],"answer":3,"answerLetter":"D","explain":"20世纪初，资产阶级革命派与改良派论战主要围绕三个方面，其中要不要以革命手段推翻清王朝是 双方论战的焦点。改良派主张温和变革，革命派主张以革命推翻清政府。"},{"id":"sg-34","globalId":34,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":34,"question":"文化大革命”的导火线是（ ）。","options":["《评新编历史剧<海瑞罢官>》的发表","上海“一月革命”夺权斗争","围困中南海事件","《炮打司令部——我的一张大字报》的发表"],"answer":0,"answerLetter":"A","explain":"答案：A“文化大革命”的导火线是姚文元1965年11月10日在《文汇报》上发表的《评新编历史剧 (海瑞罢官)》。这篇文章被人们称为“文化大革命”的“导火线”、“引火物”。"},{"id":"sg-35","globalId":35,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":35,"question":"中国共产党开展的延安整风运动最主要的任务是（ ）。","options":["反对主观主义","反对宗派主义","反对官僚主义","反对党八股"],"answer":0,"answerLetter":"A","explain":"延安整风运动的主要内容是反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整 顿文风。其中，反对主观主义是最主要任务，因为主观主义是中国共产党内反复出现“左”、右倾错误的思 想认识根源。"},{"id":"sg-36","globalId":36,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":36,"question":"1911年，在保路运动中规模最大、斗争最激烈的省份是（ ）。","options":["湖北","湖南","广东","四川"],"answer":3,"answerLetter":"D","explain":"1911 年的保路运动中，四川人民发动了武装起义，成立了保路同志军，与清军进行了激烈战斗，其 规模和斗争激烈程度远超其他省份。"},{"id":"sg-37","globalId":37,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":37,"question":"1911年夏，湖北、湖南、广东和四川爆发的民众斗争运动是（ ）。","options":["拒俄运动","拒法运动","保路运动","立宪运动"],"answer":2,"answerLetter":"C","explain":"1911 年 5 月，清政府将已归民间商办的川汉、粤汉铁路收归“国有”，随即出卖给英、法、德、 美 4 国银行团，激起湘、鄂、粤、川等省人民的强烈反对，掀起了保路运动。答案：C。"},{"id":"sg-38","globalId":38,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":38,"question":"1946年，中共决定将减租减息政策改为实现“耕者有其田”政策的文件是（ ）。","options":["《井冈山土地法》","《兴国土地法》","《关于清算、减租及土地问题的指示》","《中国土地法大纲》"],"answer":2,"answerLetter":"C","explain":"答案：C1946年5月4日，中共中央发出《关于清算、减租及土地问题的指示》，决定将党在抗日战争 时期实行的减租减息政策改变为实现“耕者有其田”的政策。"},{"id":"sg-39","globalId":39,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":39,"question":"标志着中国民族资产阶级开始登上政治舞台的运动是（ ）。","options":["洋务运动","戊戌维新运动","国会请愿运动","保路运动"],"answer":1,"answerLetter":"B","explain":"戊戌维新运动是一场资产阶级性质的政治改良运动，民族资产阶级作为新的政治力量开始登上历史 舞台。洋务运动是地主阶级洋务派发起，旨在维护封建统治；国会请愿运动是立宪派发起；保路运动是群众 性的反帝爱国运动。"},{"id":"sg-40","globalId":40,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":40,"question":"我国对资本主义工商业进行社会主义改造所实行的高级形式的国家资本主义是（ ）。","options":["加工订货","统购统销","经销代销","公私合营"],"answer":3,"answerLetter":"D","explain":"国家资本主义有低级和高级两种形式。低级形式的国家资本主义如加工订货、统购统销、经销代销 等；高级形式的国家资本主义是公私合营，公私合营又分个别企业的公私合营和全行业的公私合营。所以答 案选高级形式的公私合营。"},{"id":"sg-41","globalId":41,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":41,"question":"中国共产党确定第一次国共合作和建立革命统一战线方针的会议是（ ）。","options":["中共三大","中共四大","中共五大","中共六大"],"answer":0,"answerLetter":"A","explain":"中共三大的中心议题是讨论全体共产党员加入国民党，建立国共合作统一战线的问题，正式确定了 建立国共合作统一战线的策略方针。中共四大主要是提出了无产阶级在民主革命中的领导权问题等；中共五 大主要是批评陈独秀的右倾错误等；中共六大主要是在大革命失败后，总结大革命失败教训，正确分析革命 性质等。所以答案是中共三大。"},{"id":"sg-42","globalId":42,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":42,"question":"1913年，孙中山领导革命党人发动的反对袁世凯的斗争是（ ）。","options":["“二次革命”","护国战争","护法战争","北伐战争"],"answer":0,"answerLetter":"A","explain":"1913 年，袁世凯派人刺杀宋教仁，孙中山等发动“二次革命”讨袁。护国战争是 1915 年反对袁世 凯称帝；护法战争是 1917 - 1918 年为维护《临时约法》等；北伐战争是 1926 - 1927 年国共合作推翻北 洋军阀统治。所以 1913 年孙中山领导反对袁世凯的斗争是“二次革命”。"},{"id":"sg-43","globalId":43,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":43,"question":"1946年6月，国民党当局制造了镇压上海人民团体联合会请愿团的（ ）。","options":["五卅惨案","校场口惨案","下关惨案","五二零惨案"],"answer":2,"answerLetter":"C","explain":"1946 年 6 月，上海人民团体联合会组成请愿团，赴南京向国民党当局呼吁和平。请愿团到达南京 下关车站时，遭到国民党特务围攻毒打，这就是下关惨案。 A 选项五卅惨案发生于 1925 年 5 月 30 日 ，与题干时间 1946 年不符。 B 选项校场口惨案是 1946 年 2 月 10 日，在重庆校场口发生的破坏政协决 议、反对内战的事件，与上海人民团体联合会请愿团无关。 D 选项五二零惨案是 1947 年 5 月 20 日，国 民党反动派对爱国学生进行镇压的事件，时间也不符。"},{"id":"sg-44","globalId":44,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":44,"question":"中国共产党首次完整概括党在社会主义初级阶段的基本路线是在（ ）。","options":["中共十一大","中共十二大","中共十三大","中共十四大"],"answer":2,"answerLetter":"C","explain":"中共十三大首次完整概括了党在社会主义初级阶段的基本路线，即“一个中心、两个基本点”。答 案：C"},{"id":"sg-45","globalId":45,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":45,"question":"1920年，陈独秀等建立的中国共产党早期组织是（ ）。","options":["北京共产主义小组","上海共产主义小组","武汉共产主义小组","广州共产主义小组"],"answer":1,"answerLetter":"B","explain":"1920 年 8 月，陈独秀、李达等在上海建立了中国第一个共产党早期组织——上海共产主义小组。 这是各地共产主义小组中成立最早的，对其他地方党组织的建立起到引领示范作用。"},{"id":"sg-46","globalId":46,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":46,"question":"1946年6月，国民党军队挑起全国内战的起点是（ ）。","options":["重点进攻陕甘宁地区","重点进攻山东解放区","大举围攻东北解放区","大举围攻中原解放区"],"answer":3,"answerLetter":"D","explain":"1946 年 6 月 26 日，国民党军队以大举围攻中原解放区为起点，挑起了全国性内战。重点进攻陕 甘宁和山东解放区是在 1947 年，且进攻东北解放区也不符合挑起全国内战起点这一表述。"},{"id":"sg-47","globalId":47,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":47,"question":"邓小平首次明确提出必须坚持“四项基本原则”是在（ ）。","options":["1976年10月","1978年12月","1979年3月","1981年6月"],"answer":2,"answerLetter":"C","explain":"1979年3月，邓小平在理论工作务虚会上首次明确提出必须坚持“四项基本原则” 。"},{"id":"sg-48","globalId":48,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":48,"question":"中国共产党于1927年召开的确定土地革命和武装斗争方针的会议是（ ）。","options":["古田会议","遵义会议","八七会议","洛川会议"],"answer":2,"answerLetter":"C","explain":"八七会议是大革命失败以后，在关系党和革命事业前途和命运的严重危机时刻，中共中央召开的紧 急会议，确定了土地革命和武装斗争方针。古田会议强调党对军队的绝对领导；遵义会议主要解决军事和组 织问题，确立以毛泽东为代表的马克思主义的正确路线在中共中央的领导地位；洛川会议制定全面抗战路线 。答案选C。"},{"id":"sg-49","globalId":49,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":49,"question":"1947年，国民党宪警制造的镇压爱国学生运动的惨案是（ ）。","options":["五卅惨案","校场口惨案","下关惨案","五二O惨案"],"answer":3,"answerLetter":"D","explain":"1947年5月20日，南京、上海、苏州、杭州等地学生举行大规模的反饥饿、反内战、反迫害（“反饥 饿、反内战、反迫害”简称“三反”）示威游行，遭到国民党宪警镇压，造成“五二O”惨案。A选项五卅惨 案发生于1925年；B选项校场口惨案发生于1946年；C选项下关惨案发生于1946年。"},{"id":"sg-50","globalId":50,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":50,"question":"第一次国共合作建立后，全国范围大革命风暴兴起的标志是（ ）。","options":["护法战争","五四运动","北伐战争","五卅运动"],"answer":3,"answerLetter":"D","explain":"五卅运动中，工人罢工、学生罢课、商人罢市，反帝爱国运动迅速扩展到全国，是大革命风暴兴起 的标志。护法战争与第一次国共合作无关；五四运动时第一次国共合作尚未建立；北伐战争是大革命高潮的 到来，而非兴起标志。"},{"id":"sg-51","globalId":51,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":51,"question":"戊戌维新时期，谭嗣同撰写的宣传变法维新主张的著作是（ ）。","options":["《新学伪经考》","《变法通义》","《日本变政考》","《仁学》"],"answer":3,"answerLetter":"D","explain":"《新学伪经考》是康有为著作；《变法通义》是梁启超著作；《日本变政考》是康有为进呈光绪帝 的书籍；而《仁学》是谭嗣同撰写的宣传变法维新主张的著作。答案：D。"},{"id":"sg-52","globalId":52,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":52,"question":"1947年，台湾人民举行的反对国民党反动统治的大规模斗争是（ ）。","options":["黑旗军起义","一二·一运动","二二八起义","一二·三〇运动"],"answer":2,"answerLetter":"C","explain":"1947年2月28日，台湾人民为反抗国民党当局的暴政、抗议反动军警屠杀市民，举行大规模示威游行 ，即“二二八起义” 。黑旗军起义是清末刘永福领导的武装斗争；一二·一运动是1945年昆明学生发动的反 内战、争民主运动；一二·三〇运动是1946年12月30日，为抗议驻华美军暴行，北平学生发起的运动。答案 ：C"},{"id":"sg-53","globalId":53,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":53,"question":"戊戌维新时期，维新派在上海创办的影响较大的报刊是（ ）。","options":["《时务报》","《国闻报》","《湘报》","《万国公报》"],"answer":0,"answerLetter":"A","explain":"戊戌维新时期，维新派在各地创办了众多报刊来宣传变法思想。其中《时务报》是在上海创办且影 响较大。《国闻报》在天津，《湘报》在湖南，《万国公报》虽有重要意义但创办地不是上海。答案：A。"},{"id":"sg-54","globalId":54,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":54,"question":"中国开始进入半殖民地半封建社会是在（ ）。","options":["第一次鸦片战争后","第二次鸦片战争后","中日甲午战争后","八国联军侵华战争后"],"answer":0,"answerLetter":"A","explain":"第一次鸦片战争后，英国强迫清政府签订《南京条约》等一系列不平等条约，破坏了中国的主权和 领土完整等，中国开始沦为半殖民地半封建社会。第二次鸦片战争使半殖民地半封建化程度加深；甲午战争 后大大加深；八国联军侵华后完全沦为。答案：A。"},{"id":"sg-55","globalId":55,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":55,"question":"第一次鸦片战争结束后，美国迫使清政府订立的不平等条约是（ ）。","options":["《南京条约》","《望厦条约》","《黄埔条约》","《理挥条约》"],"answer":1,"answerLetter":"B","explain":"《南京条约》是英国与清政府签订的；《黄埔条约》是法国与清政府签订的；不存在《理挥条约》 。而《望厦条约》是第一次鸦片战争后美国强迫清政府签订的不平等条约 。"},{"id":"sg-56","globalId":56,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":56,"question":"1925年至1926年间，中国工人坚持16个月之久的罢工斗争是（ ）。","options":["香港海员罢工","安源路矿工人罢工","京汉铁路工人罢工","省港罢工"],"answer":3,"answerLetter":"D","explain":"省港罢工从1925年6月开始，到1926年10月结束，坚持了16个月之久。香港海员罢工1922 年；安源 路矿工人罢工1922年；京汉铁路工人罢工1923年。"},{"id":"sg-57","globalId":57,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":57,"question":"1948年11月至1949年1月，担任淮海战役总前委书记的是（ ）。","options":["邓小平","刘伯承","陈毅","粟裕"],"answer":0,"answerLetter":"A","explain":"淮海战役总前委由刘伯承、陈毅、邓小平、粟裕、谭震林组成，邓小平任总前委书记 。"},{"id":"sg-58","globalId":58,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":58,"question":"国民党四大家族官僚资本的性质是（ ）。","options":["私人垄断资本主义","封建的买办的国家垄断资本主义","私人资本主义","国家资本主义"],"answer":1,"answerLetter":"B","explain":"国民党四大家族官僚资本是在国民政府统治时期，凭借国家政权，依附帝国主义，与封建势力勾结 而形成，具有封建性、买办性和国家垄断性。答案：B 。"},{"id":"sg-59","globalId":59,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":59,"question":"新中国第一次正式提出实现“四个现代化”奋斗目标的会议是（ ）。","options":["第一届全国人民代表大会","第二届全国人民代表大会","第三届全国人民代表大会","第四届全国人民代表大会"],"answer":2,"answerLetter":"C","explain":"1964 年 12 月第三届全国人民代表大会第一次会议上，周恩来在政府工作报告中首次正式提出要在 不太长的历史时期内，把我国建设成为一个具有现代农业、现代工业、现代国防和现代科学技术的社会主义 强国，即实现“四个现代化”的奋斗目标。答案：C 。"},{"id":"sg-60","globalId":60,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":60,"question":"1927年，中国共产党确定土地革命和武装反抗国民党反动派方针的会议是（ ）。","options":["八七会议","古田会议","赣南会议","十二月会议"],"answer":0,"answerLetter":"A","explain":"1927 年 8 月 7 日，中共中央在湖北汉口召开紧急会议，即“八七会议”，确定了土地革命和武装 反抗国民党反动派的总方针。古田会议主要是解决新型人民军队建设问题；赣南会议是 1931 年召开，对根 据地和红军发展有重要影响，但主题并非确定土地革命和武装反抗方针；十二月会议是 1947 年召开，主要 讨论解放战争转入战略进攻后的一系列问题。答案：A 。"},{"id":"sg-61","globalId":61,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":61,"question":"中华人民共和国恢复在联合国合法席位的时间是（ ）。","options":["1949年","1966年","1971年","1978年"],"answer":2,"answerLetter":"C","explain":"1971年10月25日，联合国大会第26届会议以压倒性多数通过第2758号决议，恢复中华人民共和国在 联合国的一切合法权利。所以答案选C。"},{"id":"sg-62","globalId":62,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":62,"question":"1928年10月，国民党中央常务委员会通过了（ ）。","options":["《中华民国临时约法》","《中华民国约法》","《军政纲领》","《训政纲领》"],"answer":3,"answerLetter":"D","explain":"1928 年 10 月，国民党中央常务委员会通过《训政纲领》，规定“由中国国民党全国代表大会代表 国民大会，领导国民行使政权”，实质是蒋介石集团实行独裁统治的工具。《中华民国临时约法》是 1912 年南京临时政府颁布；《中华民国约法》是 1914 年袁世凯炮制；不存在《军政纲领》这一当时特定文件。 答案：D 。"},{"id":"sg-63","globalId":63,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":63,"question":"1956年，陈云在中共八大上提出了（ ）。","options":["“三个主体、三个补充”的思想","“双重监督”的思想","“健全法制”的思想","“新经济政策”的思想"],"answer":0,"answerLetter":"A","explain":"1956 年陈云在中共八大上提出“三个主体、三个补充”的思想，旨在突破传统观念，探索适合中国 特点的经济体制。"},{"id":"sg-64","globalId":64,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":64,"question":"将中国领土台湾割让给日本的不平等条约是（ ）。","options":["《南京条约》","《北京条约》","《马关条约》","《瑷珲条约》"],"answer":2,"answerLetter":"C","explain":"1895 年签订的《马关条约》规定，把辽东半岛、台湾全岛及所有附属各岛屿和澎湖列岛割让给日本 。《南京条约》割香港岛给英国；《北京条约》割九龙司地方一区给英国；《瑷珲条约》使沙俄割占了中国 东北外兴安岭以南、黑龙江以北 60 多万平方公里领土。答案选C。"},{"id":"sg-65","globalId":65,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":65,"question":"1928年12月，毛泽东主持制定中国共产党历史上第一个土地法是在","options":["古田","永新","井冈山","瑞金"],"answer":2,"answerLetter":"C","explain":"1928 年 12 月，毛泽东在井冈山主持制定了中国共产党历史上第一个土地法，即《井冈山土地法》 。所以答案是C。"},{"id":"sg-66","globalId":66,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":66,"question":"1956年，在中共八大上提出“三个主体，三个补充”思想的是（ ）","options":["周恩来","刘少奇","邓小平","陈云"],"answer":3,"answerLetter":"D","explain":"1956年，陈云在中共八大上提出“三个主体，三个补充”思想，即国家经营和集体经营是主体，一 定数量的个体经营为补充；计划生产是主体，一定范围的自由生产为补充；国家市场是主体，一定范围的自 由市场为补充。所以答案选D。"},{"id":"sg-67","globalId":67,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":67,"question":"进入新民主主义社会后，我国在经济上处于领导地位的是（ ）。","options":["私人资本主义经济","国家资本主义经济","合作社经济","国营经济"],"answer":3,"answerLetter":"D","explain":"新民主主义社会存在五种经济成分，国营经济是通过没收官僚资本而形成的，它掌握了主要经济命 脉，在国民经济中居于领导地位。"},{"id":"sg-68","globalId":68,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":68,"question":"洋务派最早从事的洋务事业是（ ）。","options":["兴办军用工业","兴办民用工业","派遣留学生","创立新式学堂"],"answer":0,"answerLetter":"A","explain":"洋务派为了自强，最早从兴办军用工业开始，通过引进西方技术设备来制造枪炮等武器，以增强军 事力量。而兴办民用工业是为了解决军用工业的资金等问题；派遣留学生和创立新式学堂是为洋务事业培养 人才，这些举措都晚于兴办军用工业。答案：A。"},{"id":"sg-69","globalId":69,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":69,"question":"1931～1934年，中国共产党内出现的主要错误倾向是（ ）。","options":["“左”倾盲动主义","“左”倾教条主义","右倾保守主义","右倾机会主义"],"answer":1,"answerLetter":"B","explain":"1931 - 1934 年，王明“左”倾教条主义在党内占据统治地位，使中国革命遭受严重挫折。答案选B 。"},{"id":"sg-70","globalId":70,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":70,"question":"1962年1月，中共中央召开总结经验教训、明确工作方向的会议是（ ）。","options":["“七千人大会”","中共八届九中全会","第一次郑州会议","中共八届十中全会"],"answer":0,"answerLetter":"A","explain":"1962年1月召开的“七千人大会”，是中共中央召开的总结经验教训、明确工作方向的会议 。中共 八届九中全会1961年召开，正式批准对国民经济实行“调整、巩固、充实、提高”八字方针 ；第一次郑州会 议1958年召开，开始纠正“左”倾错误；中共八届十中全会1962年9月召开，使“左”倾错误进一步发展 。 答案选A 。"},{"id":"sg-71","globalId":71,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":71,"question":"近代中国睁眼看世界的第一人是（ ）。","options":["魏源","林则徐","龚自珍","洪仁玕"],"answer":1,"answerLetter":"B","explain":"林则徐组织翻译西方书刊，编译《四洲志》等，是近代中国睁眼看世界的第一人。"},{"id":"sg-72","globalId":72,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":72,"question":"以第一次国共合作为基础的国民革命统一战线正式形成的标志是（ ）。","options":["中共二大的召开","中共三大的召开","中国国民党一大的召开","中国国民党二大的召开"],"answer":2,"answerLetter":"C","explain":"1924 年中国国民党一大的召开，重新解释了三民主义，制定了联俄、联共、扶助农工的三大政策 ，标志着以第一次国共合作为基础的国民革命统一战线正式形成。中共二大主要是制定民主革命纲领；中共 三大是决定共产党员以个人身份加入国民党，但都不是统一战线正式形成标志；国民党二大时统一战线早已 形成。"},{"id":"sg-73","globalId":73,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":73,"question":"1931年1月至1935年1月，中国共产党内出现的主要错误倾向是（ ）。","options":["“左”倾盲动主义","“左”倾教条主义","右倾保守主义","右倾投降主义"],"answer":1,"answerLetter":"B","explain":"1931 年 1 月至 1935 年 1 月，以王明为代表的“左”倾教条主义在党中央占据统治地位，使中国 革命遭受严重挫折。“左”倾盲动主义主要在大革命失败后一段时间；右倾保守主义、右倾投降主义不符合 这一时期党内主要错误倾向特征。"},{"id":"sg-74","globalId":74,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":74,"question":"1967年，老一辈革命家与中央文革小组错误做法进行的抗争被诬称为","options":["“一月风暴”","“二月逆流”","“右倾翻案”","“反攻倒算”"],"answer":1,"answerLetter":"B","explain":"1967 年 2 月前后，谭震林、陈毅、叶剑英等老一辈革命家在不同会议上对“文化大革命”的错误 做法提出了强烈批评，但被江青等人诬称为“二月逆流” 。A 选项“一月风暴”是上海造反派掀起全面夺权 风暴；C 选项“右倾翻案”主要针对邓小平 1975 年整顿；D 选项“反攻倒算”不符合这一史实描述。答案 ：B"},{"id":"sg-75","globalId":75,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":75,"question":"1931年当选为中华苏维埃共和国临时中央政府主席的是（ ）。","options":["毛泽东","周恩来","项英","王稼祥"],"answer":0,"answerLetter":"A","explain":"1931年11月，中华苏维埃第一次全国代表大会在江西瑞金召开，大会选举产生了中华苏维埃共和国 临时中央政府，毛泽东当选为主席。所以答案是A。"},{"id":"sg-76","globalId":76,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":76,"question":"1967年，谭震林等老一辈无产阶级革命家与中央文革小组的错误做法进行的抗争被诬称为（ ）。","options":["“一月风暴”","“反攻倒算”","“右倾翻案”","“二月逆流”"],"answer":3,"answerLetter":"D","explain":"1967 年 2 月，谭震林、陈毅、叶剑英等老一辈革命家在不同会议上对“文化大革命”的错误做法 提出了强烈批评，但当时被林彪、江青反革命集团诬称为“二月逆流” 。"},{"id":"sg-77","globalId":77,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":77,"question":"袁世凯窃夺辛亥革命成果后，于1914年5月炮制了（ ）。","options":["《戒严法》","《中华民国约法》","《钦定宪法大纲》","《暂行新刑律》"],"answer":1,"answerLetter":"B","explain":"1914 年 5 月，袁世凯炮制《中华民国约法》，用总统制取代内阁制，为其复辟帝制做准备。答案 选B 。《戒严法》并非 1914 年 5 月炮制；《钦定宪法大纲》是清政府 1908 年颁布；《暂行新刑律》是袁 世凯在 1912 年在《大清新刑律》基础上修订。"},{"id":"sg-78","globalId":78,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":78,"question":"1933年，冯玉祥在张家口领导成立的抗日武装力量是（ ）。","options":["东北抗日义勇军","东北抗日联军","察哈尔抗日义勇军","察哈尔抗日同盟军"],"answer":3,"answerLetter":"D","explain":"1933 年冯玉祥在张家口成立的是察哈尔抗日同盟军。东北抗日义勇军是自发的民众抗日武装；东北 抗日联军是在东北抗日武装力量基础上发展而来，主要领导者有杨靖宇等；不存在察哈尔抗日义勇军这一确 切称谓。答案选D。"},{"id":"sg-79","globalId":79,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":79,"question":"1971年10月，新中国在外交上取得的重大成果是（ ）。","options":["恢复了在联合国的合法席位","恢复了在世界卫生组织的合法席位","实现了中日关系正常化","实现了中法关系正常化"],"answer":0,"answerLetter":"A","explain":"1971年10月，第26届联合国大会恢复中华人民共和国在联合国的一切合法权利。B选项恢复在世界卫 生组织合法席位时间不符；C选项中日关系正常化是1972年；D选项中法建交是1964年。答案选A。"},{"id":"sg-80","globalId":80,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":80,"question":"毛泽东为新华社写的1949年新年献词是（ ）。","options":["《对目前时局的宣言》","《目前形势和我们的任务》","《将革命进行到底》","《论人民民主专政》"],"answer":2,"answerLetter":"C","explain":"1949 年新年之际，毛泽东为新华社撰写《将革命进行到底》的新年献词，号召将革命进行到底 。A 选项《对目前时局的宣言》发表于抗战胜利后；B 选项《目前形势和我们的任务》是 1947 年毛泽东在陕北 米脂县杨家沟召集的会议上所作报告；D 选项《论人民民主专政》是 1949 年 6 月 30 日毛泽东为纪念中国 共产党成立 28 周年而写。答案：C 。"},{"id":"sg-81","globalId":81,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":81,"question":"在抗美援朝战争中担任中国人民志愿军司令员兼政治委员的是（ ）。","options":["朱德","彭德怀","陈毅","刘伯承"],"answer":1,"answerLetter":"B","explain":"抗美援朝战争中，彭德怀临危受命，出任中国人民志愿军司令员兼政治委员，指挥志愿军作战。而 朱德、陈毅、刘伯承并未担任此职。"},{"id":"sg-82","globalId":82,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":82,"question":"1935年，中共北平临时工作委员会领导发动的抗日救亡运动是（ ）。","options":["一二·九运动","一二·一运动","一二·三零运动","五·二零运动"],"answer":0,"answerLetter":"A","explain":"1935 年 12 月 9 日，中共北平临时工作委员会领导发动了一二·九运动，这是一场抗日救亡运动 。而 B 选项一二·一运动是 1945 年在昆明爆发的反对内战、争取民主的学生运动；C 选项一二·三零运动 表述错误；D 选项五·二零运动是 1947 年爆发的反饥饿、反内战、反迫害运动。所以答案是 A。"},{"id":"sg-83","globalId":83,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":83,"question":"1982年，中共十二大明确提出了（ ）。","options":["建设有中国特色的社会主义","党在社会主义初级阶段的基本路线","建设社会主义政治文明","党在社会主义初级阶段的基本纲领"],"answer":0,"answerLetter":"A","explain":"1982 年中共十二大首次明确提出“建设有中国特色的社会主义”这一崭新命题。B 选项党在社会主 义初级阶段基本路线是 1987 年十三大提出；C 选项建设社会主义政治文明是 2001 年提出；D 选项党在社 会主义初级阶段基本纲领是 1997 年十五大提出。"},{"id":"sg-84","globalId":84,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":84,"question":"毛泽东在《论持久战》中指出，中国抗日战争取得胜利最关键的阶段是（ ）。","options":["战略防御阶段","战略相持阶段","战略反攻阶段","战略决战阶段"],"answer":1,"answerLetter":"B","explain":"《论持久战》中明确提出，战略相持阶段是中国抗日战争取得胜利最关键的阶段。这个阶段，敌之 力量逐步削弱，我之力量逐步增强。相持阶段是持久战的过渡阶段，中国将在此阶段获得转弱为强的力量 ，为战略反攻准备条件。答案：B。"},{"id":"sg-85","globalId":85,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":85,"question":"在抗日战争中，国民党由比较积极地抗战转向消极抗战的标志是（ ）。","options":["国民党五届三中全会的召开","国民党五届四中全会的召开","国民党五届五中全会的召开","国民党五届六中全会的召开"],"answer":2,"answerLetter":"C","explain":"1939 年 1 月，国民党五届五中全会决定成立“防共委员会”，确定了“防共、限共、溶共、反共 ”的方针，这标志着国民党由比较积极地抗战转向消极抗战。答案选C 。"},{"id":"sg-86","globalId":86,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":86,"question":"1935年12月，中国共产党召开的确定抗日民族统一战线新政策的会议是（ ）。","options":["西湖会议","八七会议","瓦窑堡会议","洛川会议"],"answer":2,"answerLetter":"C","explain":"1935 年 12 月的瓦窑堡会议，提出了抗日民族统一战线的政策 ，既着重批判了“左”倾教条主义 在政治策略上的错误，也警戒全党汲取大革命中无产阶级放弃领导权而导致革命失败的教训。西湖会议主要 是讨论国共合作；八七会议是大革命失败后纠正右倾错误等；洛川会议是 1937 年制定全面抗战路线。答案 ：C。"},{"id":"sg-87","globalId":87,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":87,"question":"1990年，邓小平提出的关于中国农业改革与发展的思想是（ ）。","options":["“三个主体，三个补充”","“三步走”","“两个飞跃”","“两个大局”"],"answer":2,"answerLetter":"C","explain":"1990 年邓小平提出中国农业改革与发展的“两个飞跃”思想，一是废除人民公社，实行家庭联产承 包为主的责任制；二是发展适度规模经营，发展集体经济。所以答案选C 。A选项“三个主体，三个补充”是 陈云提出的；B选项“三步走”是中国现代化建设的战略部署；D选项“两个大局”是邓小平关于区域经济协 调发展的思想。"},{"id":"sg-88","globalId":88,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":88,"question":"毛泽东在1957年2月的讲话中指出，我国政治生活的主题是正确处理（ ）。","options":["敌我矛盾","人民内部矛盾","生产关系与生产力的矛盾","上层建筑与经济基础的矛盾"],"answer":1,"answerLetter":"B","explain":"1957 年 2 月，毛泽东在《关于正确处理人民内部矛盾的问题》的讲话中指出，我国政治生活的主 题是正确处理人民内部矛盾。敌我矛盾是对抗性矛盾，当时大规模的阶级斗争基本结束，重点是处理人民内 部这种非对抗性矛盾。C、D 选项属于社会基本矛盾，并非政治生活主题。"},{"id":"sg-89","globalId":89,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":89,"question":"在抗日战争中为国捐躯的八路军副参谋长是（ ）。","options":["彭雪枫","赵尚志","杨靖宇","左权"],"answer":3,"answerLetter":"D","explain":"左权是八路军副参谋长，在抗日战争中牺牲。彭雪枫是新四军将领；赵尚志、杨靖宇是东北抗日联 军的重要领导人。"},{"id":"sg-90","globalId":90,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":90,"question":"1935年1月，中国共产党在红军长征途中召开了具有历史转折意义的（ ）。","options":["古田会议","遵义会议","两河口会议","瓦窑堡会议"],"answer":1,"answerLetter":"B","explain":"1935年1月召开的遵义会议，结束了王明“左”倾冒险主义在中共中央的统治，确立了以毛泽东为代 表的新的中央的正确领导，在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党历史上一个 生死攸关的转折点 。A选项古田会议1929 年召开；C选项两河口会议1935年6月召开；D选项瓦窑堡会议1935 年12月召开。"},{"id":"sg-91","globalId":91,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":91,"question":"1990年，中共中央和国务院为进一步对外开放而作出的战略举措是（ ）。","options":["建立厦门经济特区","建立珠海经济特区","开发、开放海南经济特区","开发、开放上海浦东新区"],"answer":3,"answerLetter":"D","explain":"1990年，中共中央和国务院作出开发、开放上海浦东新区的战略举措。厦门、珠海经济特区在 1980年设立，海南经济特区在1988年设立。所以答案是D。"},{"id":"sg-92","globalId":92,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":92,"question":"毛泽东在1957年2月扩大的最高国务会议上指出，我国政治生活的主题是（ ）。","options":["正确处理敌我矛盾","正确处理人民内部矛盾","正确处理民主与专政的关系","正确处理共产党和民主党派的关系"],"answer":1,"answerLetter":"B","explain":"1957 年 2 月，毛泽东在扩大的最高国务会议上发表《关于正确处理人民内部矛盾的问题》讲话 ，指出我国政治生活的主题是正确处理人民内部矛盾。"},{"id":"sg-93","globalId":93,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":93,"question":"在武昌起义前夕的保路运动中，斗争最激烈的省份是（ ）。","options":["湖南","湖北","四川","广东"],"answer":2,"answerLetter":"C","explain":"保路运动中，四川人民发动了大规模武装起义，成立保路同志军，与清军展开激烈战斗，运动发展 成武装起义，斗争最为激烈。答案选C。"},{"id":"sg-94","globalId":94,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":94,"question":"1992年召开的中共十四大明确提出，我国经济体制改革的目标是建立（ ）。","options":["社会主义市场经济体制","社会主义有计划商品经济体制","计划为主、市场为辅的经济体制","市场为主、计划为辅的经济体制"],"answer":0,"answerLetter":"A","explain":"1992年中共十四大明确提出我国经济体制改革目标是建立社会主义市场经济体制 。"},{"id":"sg-95","globalId":95,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":95,"question":"毛泽东指出，社会主义国家政治生活的主题是（ ）。","options":["正确处理人民内部矛盾","正确处理敌我矛盾","正确处理共产党和民主党派的关系","正确处理民主和专政的关系"],"answer":0,"answerLetter":"A","explain":"1957 年 2 月，毛泽东发表《关于正确处理人民内部矛盾的问题》，提出社会主义国家政治生活的 主题是正确处理人民内部矛盾 。答案：A 。"},{"id":"sg-96","globalId":96,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":96,"question":"1998年，中共中央决定在县级以上党政领导班子和领导干部中深入开展（ ）。","options":["讲政治、讲经济、讲文化的教育","讲思想、讲作风、讲文明的教育","讲理想、讲觉悟、讲正气的教育","讲学习、讲政治、讲正气的教育"],"answer":3,"answerLetter":"D","explain":"1998 年底，中共中央决定在县级以上党政领导班子、领导干部中深入开展以讲学习、讲政治、讲正 气为主要内容的党性党风教育。所以答案是D。"},{"id":"sg-97","globalId":97,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":97,"question":"毛泽东指出，在社会主义改造完成后我国政治生活的主题是正确处理（ ）。","options":["生产关系与生产力之间的矛盾","上层建筑与经济基础之间的矛盾","敌我矛盾","人民内部矛盾"],"answer":3,"answerLetter":"D","explain":"社会主义改造完成后，国内的敌我矛盾已经基本解决，人民内部矛盾突出起来，成为政治生活的主 题。A、B选项是社会基本矛盾，不是政治生活主题。所以正确答案是关于人民内部矛盾。"},{"id":"sg-98","globalId":98,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":98,"question":"1936年10月，中国工农红军三大主力胜利会师地是（ ）。","options":["四川懋功地区","甘肃会宁、静宁将台堡","西康甘孜地区","陕北吴起镇"],"answer":1,"answerLetter":"B","explain":"1936年10月，红二、红四方面军先后同红一方面军在甘肃会宁、静宁将台堡会师，标志着中国工农 红军三大主力胜利会师。四川懋功地区是1935年6月红一、四方面军会师地；西康甘孜地区是1936年7月红二 、四方面军会师地；陕北吴起镇是1935年10月中央红军与陕北红军会师地。答案选B。"},{"id":"sg-99","globalId":99,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":99,"question":"19世纪60年代，清朝统治集团中倡导洋务的首领人物是（ ）。","options":["奕䜣","桂良","曾国藩","李鸿章"],"answer":0,"answerLetter":"A","explain":"19世纪60年代，清朝统治集团中倡导洋务的首领人物是奕䜣 ，他是中央洋务派的代表。曾国藩、李 鸿章是地方洋务派代表，桂良不是倡导洋务的首领人物。答案：A。"},{"id":"sg-100","globalId":100,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":100,"question":"1937年，出任新四军军长的是（ ）。","options":["朱德","刘伯承","叶挺","陈毅"],"answer":2,"answerLetter":"C","explain":"1937年，叶挺出任新四军军长 。朱德是八路军总指挥；刘伯承是八路军129师师长；陈毅在新四军 组建时是重要将领，但不是军长。"},{"id":"sg-101","globalId":101,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":101,"question":"全国性抗战开始后，中国军队取得第一次重大胜利的战役是（ ）。","options":["台儿庄战役","昆仑关战役","百团大战","平型关战役"],"answer":3,"answerLetter":"D","explain":"平型关战役是全国性抗战开始后中国军队取得的第一次重大胜利，有力地打击了日军的疯狂气焰 ，打破了“日军不可战胜”的神话。台儿庄战役是抗战以来中国正面战场取得的最大的一场胜仗；昆仑关战 役是桂南会战中取得的重大胜利；百团大战是八路军主动出击日军的一次大规模战役。答案：D。"},{"id":"sg-102","globalId":102,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":102,"question":"中共八大上，在经济建设方面提出“三个主体，三个补充”思想的领导人是（ ）。","options":["毛泽东","周恩来","陈云","邓小平"],"answer":2,"answerLetter":"C","explain":"在中共八大上，陈云提出了“三个主体，三个补充”的思想，即国家经营和集体经营是主体，一定 数量的个体经营为补充；计划生产是主体，一定范围的自由生产为补充；国家市场是主体，一定范围的自由 市场为补充。答案：C。"},{"id":"sg-103","globalId":103,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":103,"question":"1898年，为对抗维新变法而发表《劝学篇》的洋务派官僚是（ ）。","options":["李鸿章","左宗棠","张之洞","刘坤一"],"answer":2,"answerLetter":"C","explain":"1898 年，张之洞发表《劝学篇》，对洋务派的指导思想“中学为体，西学为用”作了全面阐述，试 图以此来对抗维新变法。答案选C。"},{"id":"sg-104","globalId":104,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":104,"question":"1940年8～12月，八路军发动的大规模进攻华北日军的战役是（ ）。","options":["平型关战役","忻口战役","黄桥战役","百团大战"],"answer":3,"answerLetter":"D","explain":"1940 年 8 月至 12 月八路军发动百团大战，向华北日军发起大规模进攻。平型关战役是 1937 年 ；忻口战役也是 1937 年；黄桥战役是 1940 年新四军在江苏黄桥对国民党顽固派军队进行的自卫反击战役 ，地点不在华北。"},{"id":"sg-105","globalId":105,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":105,"question":"2005年3月，第十届全国人民代表大会第三次会议通过的法律是（ ）。","options":["《香港特别行政区基本法》","《国家安全法》","《澳门特别行政区基本法》","《反分裂国家法》"],"answer":3,"answerLetter":"D","explain":"2005年3月，第十届全国人民代表大会第三次会议通过《反分裂国家法》 ，旨在反对和遏制“台独 ”分裂势力分裂国家，促进祖国和平统一。A选项《香港特别行政区基本法》于1990年通过；B选项《国家安 全法》2015年通过；C选项《澳门特别行政区基本法》1993 年通过。"},{"id":"sg-106","globalId":106,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":106,"question":"太平天国运动后期，提出《资政新篇》这一带有资本主义色彩改革方案的是（ ）。","options":["洪秀全","洪仁玕","石达开","李秀成"],"answer":1,"answerLetter":"B","explain":"《资政新篇》是洪仁玕向洪秀全提出的统筹全局的改革方案，具有鲜明的资本主义色彩。"},{"id":"sg-107","globalId":107,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":107,"question":"中共中央正式提出党在过渡时期总路线的时间是（ ）。","options":["1949年","1950年","1953年","1956年"],"answer":2,"answerLetter":"C","explain":"1953 年 6 月，中共中央政治局正式讨论和制定了中国共产党在过渡时期的总路线。答案选C。"},{"id":"sg-108","globalId":108,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":108,"question":"中国大陆基本解放和实现统一的标志是（ ）。","options":["1949年中华人民共和国的成立","1950年中共七届三中全会的召开","1951年西藏的和平解放","1952年土地改革的完成"],"answer":2,"answerLetter":"C","explain":"西藏和平解放，使中国大陆实现了基本解放和统一。中华人民共和国成立时，还有部分地区未解放 ；七届三中全会是为全面实施《共同纲领》规定了明确的战略策略方针；土地改革主要是关于农村生产关系 变革。答案选C。"},{"id":"sg-109","globalId":109,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":109,"question":"1898年，张之洞发表的对抗维新变法的著作是（ ）。","options":["《新学伪经考》","《孔子改制考》","《仁学》","《劝学篇》"],"answer":3,"answerLetter":"D","explain":"《劝学篇》为张之洞所著，其核心是“中体西用”，以此对抗维新变法。《新学伪经考》《孔子改 制考》是康有为的著作，《仁学》是谭嗣同的著作。"},{"id":"sg-110","globalId":110,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":110,"question":"20世纪70年代，毛泽东、周恩来抓住时机发起了改善中美关系的（ ）。","options":["“篮球外交”","“乒乓外交”","“网球外交”","“围棋外交”"],"answer":1,"answerLetter":"B","explain":"20世纪70年代，通过“乒乓外交”这一以小球推动大球的方式，打开了中美关系改善的大门 。答案 ：B"},{"id":"sg-111","globalId":111,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":111,"question":"外国列强对近代中国进行资本输出最早出现在（ ）。","options":["第一次鸦片战争后","第二次鸦片战争后","中日甲午战争","八国联军侵华战争后"],"answer":1,"answerLetter":"B","explain":"外国列强对中国进行资本输出，在第二次鸦片战争后就已开始，《天津条约》等不平等条约签订后 ，列强逐渐开始在中国设立工厂等进行资本输出活动。而甲午战争后资本输出大规模扩张。第一次鸦片战争 后主要还是商品输出为主。八国联军侵华后资本输出进一步加深。所以最早出现在第二次鸦片战争后。答案 ：B"},{"id":"sg-112","globalId":112,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":112,"question":"1904年至l905年，为争夺侵略权益公然在中国东北进行战争的是（ ）。","options":["美国与俄国","美国与英国","英国与日本","日本与俄国"],"answer":3,"answerLetter":"D","explain":"1904 - 1905年，日俄两国为争夺在华利益，在中国东北进行战争，清政府却宣布“局外中立”。答 案选D。"},{"id":"sg-113","globalId":113,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":113,"question":"1945年4月，包括解放军代表董必武在内的中国代表团出席了（ ）。","options":["开罗会议","德黑兰会议","雅尔塔会议","联合国制宪会议"],"answer":3,"answerLetter":"D","explain":"1945 年 4 月，董必武作为中国共产党代表随中国代表团出席联合国制宪会议。开罗会议、德黑兰 会议、雅尔塔会议召开时间与题干所给时间不对应，且参会人员中没有董必武。"},{"id":"sg-114","globalId":114,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":114,"question":"20世纪初，为传播民主革命思想而撰写《革命军》一书的人是（ ）。","options":["章炳麟","邹容","陈天华","孙中山"],"answer":1,"answerLetter":"B","explain":"邹容撰写了《革命军》，以通俗易懂的语言号召人民起来推翻清王朝统治，建立“中华共和国” 。 章炳麟的著作是《驳康有为论革命书》，陈天华的著作是《警世钟》《猛回头》，孙中山主要是领导革命实 践并提出革命理论。答案：B 。"},{"id":"sg-115","globalId":115,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":115,"question":"为反对袁世凯刺杀宋教仁和“善后大借款”，孙中山在1913年领导发动了（ ）。","options":["二次革命","护国战争","护法运动","北伐战争"],"answer":0,"answerLetter":"A","explain":"【标准答案：A】"},{"id":"sg-116","globalId":116,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":116,"question":"中国第一个资产阶级革命政党是（ ）。","options":["兴中会","中国同盟会","中华革命党","中国国民党"],"answer":1,"answerLetter":"B","explain":"兴中会是近代中国第一个资产阶级革命团体；中国同盟会是中国第一个全国性的统一的资产阶级革 命政党；中华革命党是孙中山于1914年在日本东京成立的组织；中国国民党由中华革命党改组而来。所以答 案是B。"},{"id":"sg-117","globalId":117,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":117,"question":"1905～1907年，资产阶级革命派与改良派论战的焦点是（ ）。","options":["要不要打倒列国","要不要实行共和","要不要以革命手段推翻清政府","要不要废科学，兴学堂"],"answer":2,"answerLetter":"C","explain":"1905 - 1907年资产阶级革命派与改良派论战主要围绕三个方面，其中焦点是要不要以革命手段推翻 清政府。革命派主张用革命手段推翻清王朝，改良派主张通过改良的方式实现君主立宪，反对革命。"},{"id":"sg-118","globalId":118,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":118,"question":"1945年4月，出席联合国制宪会议中国代表团中的解放区代表是（ ）。","options":["周恩来","刘少奇","董必武","王若飞"],"answer":2,"answerLetter":"C","explain":"1945 年 4 月，董必武作为解放区代表出席联合国制宪会议。"},{"id":"sg-119","globalId":119,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":119,"question":"为反对袁世凯的独裁和卖国行径，孙中山在1913年领导革命党人发动了（ ）。","options":["二次革命","护国战争","护法战争","北伐战争"],"answer":0,"answerLetter":"A","explain":"1913 年，袁世凯派人刺杀宋教仁，为反对袁世凯独裁和卖国，孙中山领导革命党人发动二次革命。 护国战争发生于 1915 年底，是反对袁世凯称帝；护法战争是 1917 - 1918 年，为维护《临时约法》；北伐 战争 1926 年开始，旨在推翻北洋军阀统治。答案：A 。"},{"id":"sg-120","globalId":120,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":120,"question":"中国对香港恢复行使主权的时间是（ ）。","options":["1997年7月1日","1997年l2月20日","1999年7月1日","1999年12月20日"],"answer":0,"answerLetter":"A","explain":"1997年7月1日，中国对香港恢复行使主权，香港回归祖国。1999年12月20日是澳门回归祖国的时间 ，1999年7月1日、1997年12月20日与港澳回归时间均不符。答案：A。"},{"id":"sg-121","globalId":121,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":121,"question":"1905年8月，中国同盟会成立时所确定的机关刊物是（ ）。","options":["《民报》","《新民丛报》","《时务报》","《万国公报》"],"answer":0,"answerLetter":"A","explain":"1905 年 8 月 20 日，孙中山、黄兴等人在东京成立中国同盟会，其机关报为《民报》 。《新民丛 报》是梁启超主持的，《时务报》是维新派创办，《万国公报》为广学会发行，均与同盟会机关刊物无关。"},{"id":"sg-122","globalId":122,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":122,"question":"1945年8月，毛泽东发表的号召对日本侵略者实行全国规模反攻的文章是（ ）。","options":["《为抗日救国告全国同胞书》","《关于目前形势与党的任务的决定》","《论持久战》","《对日寇的最后一战》"],"answer":3,"answerLetter":"D","explain":"1945年8月，毛泽东发表《对日寇的最后一战》，号召对日本侵略者实行全国规模反攻 。A选项《为 抗日救国告全国同胞书》是1935年中共驻共产国际代表团发表，推动了抗日救亡运动发展；B选项《关于目前 形势与党的任务的决定》是1937年洛川会议文件，主要是制定全面抗战路线；C选项《论持久战》是1938年毛 泽东阐述抗日战争方针的著作。"},{"id":"sg-123","globalId":123,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":123,"question":"20世纪初，在资产阶级民主革命思想传播中发表《驳康有为论革命书》的是（ ）。","options":["孙中山","邹容","章炳麟","陈天华"],"answer":2,"answerLetter":"C","explain":"章炳麟发表《驳康有为论革命书》，批驳康有为的保皇观点，强调中国人民完全有能力建立民主共 和制度。答案选C 。"},{"id":"sg-124","globalId":124,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":124,"question":"魏源在1843难编纂的《海国图志》中提出的重要思想是（ ）。","options":["中学为体、西学为用","物竞天择、适者生存","救亡图存","师夷长技以制夷"],"answer":3,"answerLetter":"D","explain":"《海国图志》中魏源明确提出了“师夷长技以制夷”的思想 ，主张学习西方先进技术来抵御西方侵 略。A选项“中学为体、西学为用”是洋务派主张；B选项“物竞天择、适者生存”是严复翻译《天演论》宣 传的思想；C选项“救亡图存”是甲午战后民族危机加深时兴起的思潮。"},{"id":"sg-125","globalId":125,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":125,"question":"中国封建社会产生过诸多“盛世”，出现在清代的是（ ）。","options":["文景之治","贞观之治","开元之治","康乾盛世"],"answer":3,"answerLetter":"D","explain":"文景之治是西汉汉文帝、汉景帝时期；贞观之治是唐朝唐太宗时期；开元之治是唐朝唐玄宗前期 ；康乾盛世是清朝康熙、雍正、乾隆时期的盛世局面。所以出现在清代的是康乾盛世。"},{"id":"sg-126","globalId":126,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":126,"question":"1911年，标志辛亥革命达到高潮的起义是（ ）。","options":["惠州起义","河口起义","广州起义","武昌起义"],"answer":3,"answerLetter":"D","explain":"武昌起义成功后，全国十几个省纷纷响应，清朝的统治摇摇欲坠，标志着辛亥革命达到高潮。而惠 州起义、河口起义、广州起义虽也是反清起义，但影响力和对辛亥革命进程推动程度不及武昌起义。"},{"id":"sg-127","globalId":127,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":127,"question":"20世纪初，邹容发表的号召人民推翻清朝统治、建立“中华共和国”的著作是（ ）。","options":["《驳康有为论革命书》","《革命军》","《警世钟》","《猛回头》"],"answer":1,"answerLetter":"B","explain":"邹容的《革命军》热情讴歌革命，号召推翻清朝统治，建立“中华共和国” 。A选项《驳康有为论 革命书》是章炳麟所著；C选项《警世钟》和D选项《猛回头》是陈天华所著。"},{"id":"sg-128","globalId":128,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":128,"question":"我国的科举制度正式废除于（ ）。","options":["1905年","1906年","1907年","1908年"],"answer":1,"answerLetter":"B","explain":"答案：B科举制度是中国古代选拔官员的一种制度，历经了1300多年。清朝末期，随着社会的变革和 新式教育的兴起，科举制度逐渐显得不适应时代的需求。1905年，清政府宣布废除科举制度的诏书，但实际 操作上，科举制度的废除是在1906年进行的。因此，我国的科举制度正式废除于1906年，选项B正确。"},{"id":"sg-129","globalId":129,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":129,"question":"中国共产党领导建立的第一个农民协会是在（ ）。","options":["浙江省萧山县","广东省海丰县","福建省上杭县","湖南省湘潭县"],"answer":0,"answerLetter":"A","explain":"1921 年 9 月，沈定一等在浙江省萧山县衙前村领导成立了第一个农民协会。答案：A 。"},{"id":"sg-130","globalId":130,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":130,"question":"从1937年卢沟桥事变到1938年10月广州、武汉失守，中国抗日战争处于（ ）。","options":["战略防御阶段","战略相持阶段","战略反攻阶段","战略决战阶段"],"answer":0,"answerLetter":"A","explain":"1937 年卢沟桥事变到 1938 年 10 月广州、武汉失守，日军处于战略进攻态势，中国军队处于战略 防御，进行了一系列抵抗作战。所以这一时期是战略防御阶段。"},{"id":"sg-131","globalId":131,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":131,"question":"我国对资本主义商业的社会主义改造所采取的基本政策是（ ）。","options":["加工订货","和平赎买","统购包销","公私合营"],"answer":1,"answerLetter":"B","explain":"我国对资本主义工商业社会主义改造采取的基本政策是和平赎买，通过国家资本主义形式，将其改 造成社会主义公有制企业。加工订货、统购包销是国家资本主义初级形式，公私合营是高级形式。答案选B。"},{"id":"sg-132","globalId":132,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":132,"question":"我国农业社会主义改造中，具有完全社会主义性质的经济组织形式是（ ）。","options":["变工队","互助组","初级农业生产合作社","高级农业生产合作社"],"answer":3,"answerLetter":"D","explain":"变工队是旧中国农村的一种劳动互助形式，不属于社会主义改造的经济组织形式；互助组是具有社 会主义萌芽性质；初级农业生产合作社具有半社会主义性质；高级农业生产合作社实现了土地等主要生产资 料的公有，具有完全社会主义性质。"},{"id":"sg-133","globalId":133,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":133,"question":"中国共产党为总结经验教训、明确工作方向召开的“七千人大会”是在（ ）。","options":["1958年","1959年","1962年","1963年"],"answer":2,"answerLetter":"C","explain":"“七千人大会”于1962年1月11日至2月7日召开 ，目的是总结经验教训、明确工作方向。"},{"id":"sg-134","globalId":134,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":134,"question":"1920年10月，李大钊发起成立的中国共产党早期组织是（ ）。","options":["上海共产主义小组","武汉共产主义小组","北京共产主义小组","广州共产主义小组"],"answer":2,"answerLetter":"C","explain":"1920年10月，李大钊发起成立北京共产主义小组 。上海共产主义小组是陈独秀发起成立的，武汉、 广州共产主义小组也都不是李大钊发起成立的。"},{"id":"sg-135","globalId":135,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":135,"question":"1946年6月全面内战爆发时，国民党军队首先进攻的地区是（ ）。","options":["中原解放区","东北解放区","山东解放区","陕甘宁解放区"],"answer":0,"answerLetter":"A","explain":"1946年6月，国民党军队以围攻中原解放区为起点，挑起了全国性的内战。所以国民党军队首先进攻 的地区是中原解放区。"},{"id":"sg-136","globalId":136,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":136,"question":"邓演达在1930年8月领导成立的中间党派是（ ）。","options":["中华职业教育社","中国国家社会党","中国青年党","中国国民党临时行动委员会"],"answer":3,"answerLetter":"D","explain":"1930 年 8 月，邓演达领导成立中国国民党临时行动委员会，它是中间党派中影响较大的一个。而 A 选项中华职业教育社由黄炎培等创立；B 选项中国国家社会党由张君劢等组建；C 选项中国青年党由曾琦 等建立，都与邓演达无关。"},{"id":"sg-137","globalId":137,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":137,"question":"我国西藏实现和平解放的时间是（ ）。","options":["1949年10月","1950年10月","1951年10月","1952年10月"],"answer":2,"answerLetter":"C","explain":"1951 年 5 月，中央人民政府同西藏地方政府达成关于和平解放西藏办法的协议，10 月，人民解放 军进驻拉萨，西藏和平解放。答案：C。"},{"id":"sg-138","globalId":138,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":138,"question":"1920年8月，陈独秀领导建立的中国共产党早期组织是（ ）。","options":["上海共产主义小组","北京共产主义小组","武汉共产主义小组","广州共产主义小组"],"answer":0,"answerLetter":"A","explain":"1920年8月，陈独秀在上海建立了中国第一个共产党早期组织——上海共产主义小组 。其他各地共 产主义小组在上海小组影响推动下建立。"},{"id":"sg-139","globalId":139,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":139,"question":"1947年，被国民党当局宣布为而“非法团体”而被迫解散的中国国民党派是（ ）。","options":["中国民主同盟","九三学社","中国农工民主党","台湾民主自治同盟"],"answer":0,"answerLetter":"A","explain":"1947 年 10 月，国民党当局宣布民盟为“非法团体”，明令对该组织及其成员的一切活动“严加取 缔”，民盟总部被迫发表公告，通告盟员自即日起一律停止政治活动，民盟总部即日解散。"},{"id":"sg-140","globalId":140,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":140,"question":"第五次反“围剿”斗争失败后，1934年10月开始战略转移的是（ ）。","options":["红十五军团","红一方面军","红二方面军","红四方面军"],"answer":1,"answerLetter":"B","explain":"第五次反“围剿”失败后，1934 年 10 月红一方面军率先开始战略转移，也就是长征。红二、红四 方面军随后开始长征，红十五军团成立于 1935 年，与此次战略转移起始时间不符。"},{"id":"sg-141","globalId":141,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":141,"question":"武昌起义前夕，在保路运动中规模最大、斗争最激烈的省份是（ ）。","options":["湖南","湖北","广东","四川"],"answer":3,"answerLetter":"D","explain":"保路运动中，四川成立保路同志会，发动民众开展反清武装起义，规模最大、斗争最激烈。答案 ：D。"},{"id":"sg-142","globalId":142,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":142,"question":"1921年9月，在浙江省萧山县衙前村组织成立第一个农民协会的是（ ）。","options":["沈定一","彭湃","阮啸仙","林伯渠"],"answer":0,"answerLetter":"A","explain":"1921 年 9 月，沈定一在浙江省萧山县衙前村组织成立了第一个农民协会。彭湃主要在广东海陆丰 开展农民运动；阮啸仙是广东农民运动的重要领导人之一；林伯渠主要活跃于民主革命等诸多重要政治活动 ，与题干农民协会创建不符。答案：A 。"},{"id":"sg-143","globalId":143,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":143,"question":"1947年，国民党宪警镇压爱国学生运动的事件是（ ）。","options":["五卅惨案","较场口惨案","下关惨案","五二零惨案"],"answer":3,"answerLetter":"D","explain":"1947 年 5 月 20 日，南京、上海、苏州、杭州地区 16 所专科以上院校学生 6000 余人汇集南京 ，举行反饥饿、反内战、挽救教育危机联合大游行，遭到国民党宪警的镇压，史称“五二零惨案” 。A 选项 五卅惨案发生于 1925 年；B 选项较场口惨案发生于 1946 年；C 选项下关惨案发生于 1946 年。"},{"id":"sg-144","globalId":144,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":144,"question":"第一次国共合作的政治基础是（ ）。","options":["三民主义","新三民主义","新民主主义","社会主义"],"answer":1,"answerLetter":"B","explain":"新三民主义与中国共产党在民主革命阶段的纲领基本一致，成为第一次国共合作的政治基础。三民 主义没有明确的反帝反封建内容；新民主主义是中国共产党的革命理论；社会主义与当时合作基础不符。答 案：B"},{"id":"sg-145","globalId":145,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":145,"question":"武昌起义胜利后被推举为湖北军政府都督的是（ ）。","options":["黄兴","黎元洪","孙中山","章太炎"],"answer":1,"answerLetter":"B","explain":"武昌起义后，革命党人认为需要有一个有地位的人来稳定局面，黎元洪当时是湖北新军协统，在旧 势力中有一定影响力，所以被推举为湖北军政府都督 。黄兴、孙中山当时不在武昌，章太炎在当时主要以思 想文化活动等闻名，并非被推举为湖北军政府都督之人。"},{"id":"sg-146","globalId":146,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":146,"question":"中国近代史上第一次彻底反帝反封建的革命运动是（ ）。","options":["辛亥革命","五四运动","五卅运动","国民革命"],"answer":1,"answerLetter":"B","explain":"辛亥革命没有彻底反帝反封建；五卅运动发生在五四运动之后；国民革命也是在五四运动之后。而 五四运动是中国近代史上第一次彻底反帝反封建的革命运动。"},{"id":"sg-147","globalId":147,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":147,"question":"1922年1月，中国共产党领导的第一次工人运动高潮的起点是（ ）。","options":["香港海员罢工","安源路矿工人罢工","京汉铁路工人罢工","省港工人罢工"],"answer":0,"answerLetter":"A","explain":"1922 年 1 月香港海员罢工，是中国工人阶级第一次直接同帝国主义势力进行的有组织较量 ，成为 第一次工人运动高潮的起点。"},{"id":"sg-148","globalId":148,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":148,"question":"中国近代史上人民群众第一次大规模的反侵略武装斗争是（ ）。","options":["三元里人民的抗英斗争","太平天国抗击洋枪队的斗争","台湾人民的抗日斗争","义和团抗击八国联军的斗争"],"answer":0,"answerLetter":"A","explain":"三元里人民抗英斗争发生于1841年，是中国近代史上人民群众第一次大规模的反侵略武装斗争。其 他选项时间均晚于它。"},{"id":"sg-149","globalId":149,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":149,"question":"1922年7月，中共二大第一次明确提出了（ ）。","options":["反帝反封建的民主革命纲领","实现共产主义的最高纲领","新民主主义革命总路线","土地革命总路线"],"answer":0,"answerLetter":"A","explain":"中共二大在分析国际国内形势和中国社会性质的基础上，第一次明确提出了反帝反封建的民主革命 纲领。B项实现共产主义最高纲领在一大就已提出；C项新民主主义革命总路线是1948年毛泽东完整表述的 ；D项土地革命总路线在20世纪30年代逐渐形成。"},{"id":"sg-150","globalId":150,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":150,"question":"1924年，国民革命统一战线正式形成的标志是（ ）。","options":["中国国民党一大的召开","中国国民党二大的召开","中国共产党三大的召开","中国共产党四大的召开"],"answer":0,"answerLetter":"A","explain":"1924 年，中国国民党一大在广州召开，重新解释了三民主义，制定了联俄、联共、扶助农工的三大 政策；承认共产党员和青年团员以个人身份加入国民党。标志着以第一次国共合作为基础的革命统一战线正 式建立。"},{"id":"sg-151","globalId":151,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":151,"question":"1947年，中国共产党在全国土地会议上制定的重要文件是（ ）。","options":["《井冈山土地法》","《兴国土地法》","《关于清算、减租及土地问题的请示》","《中国土地法大纲》"],"answer":3,"answerLetter":"D","explain":"1947 年全国土地会议制定的是《中国土地法大纲》。A 项《井冈山土地法》是 1928 年制定；B 项 《兴国土地法》是 1929 年制定；C 项《关于清算、减租及土地问题的请示》即《五四指示》，是 1946 年 发布。答案：D 。"},{"id":"sg-152","globalId":152,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":152,"question":"辛亥革命时期，资产阶级革命派的阶级基础是（ ）。","options":["买办资产阶级","官僚资产阶级","民族资产阶级","城市小资产阶级"],"answer":2,"answerLetter":"C","explain":"资产阶级革命派代表民族资产阶级的利益，民族资产阶级随着民族资本主义发展而壮大，为革命派 提供阶级基础。买办资产阶级和官僚资产阶级与帝国主义、封建势力联系紧密，不是革命派阶级基础。城市 小资产阶级不是资产阶级范畴。答案选C。"},{"id":"sg-153","globalId":153,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":153,"question":"中国历史上第一次比较完全意义上的资产阶级民主革命是（ ）。","options":["戊戌维新运动","辛亥革命","护国运动","国民革命"],"answer":1,"answerLetter":"B","explain":"辛亥革命推翻了清王朝统治，结束了统治中国两千多年的君主专制制度，建立了中国历史上第一个 资产阶级共和政府，是中国历史上第一次比较完全意义上的资产阶级民主革命。戊戌维新运动是一场资产阶 级性质的改良运动；护国运动是为反对袁世凯复辟帝制；国民革命是国共合作推翻北洋军阀统治的革命，时 间晚于辛亥革命 。答案选B。"},{"id":"sg-154","globalId":154,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":154,"question":"1925年，广州国民政府将所辖各部队统一改编为（ ）。","options":["国民军","国民革命军","东征军","北伐军"],"answer":1,"answerLetter":"B","explain":"1925 年，广州国民政府将所辖各部队统一改编为国民革命军，这是为适应革命形势发展，建立起的 新型军队。"},{"id":"sg-155","globalId":155,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":155,"question":"1947年10月，被国民党当局宣布为“非法团体”并勒令取缔的民主党派是（ ）。","options":["中国农工民主党","中国民主同盟","中国民主促进会","中国国民党革命委员会"],"answer":1,"answerLetter":"B","explain":"1947 年 10 月，国民党当局宣布中国民主同盟为“非法团体”，明令对该组织及其成员的一切活动 “严加取缔”。民盟被迫解散，这使中间路线的政治幻想破灭。"},{"id":"sg-156","globalId":156,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":156,"question":"对兴办洋务的指导思想最早作出完整表述的人是（ ）。","options":["冯桂芬","马建忠","王韬","郑观应"],"answer":0,"answerLetter":"A","explain":"冯桂芬在《校邠庐抗议》中提出“以中国之伦常名教为原本，辅以诸国富强之术”，第一次完整表 述了洋务运动“中体西用”的指导思想。"},{"id":"sg-157","globalId":157,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":157,"question":"新文化运动的主要内容是（ ）。","options":["提倡民主和科学","宣传俄国十月革命","主张社会革命","反对外来侵略"],"answer":0,"answerLetter":"A","explain":"新文化运动提倡民主、反对独裁专制，提倡科学、反对迷信盲从，这是其主要内容。B宣传俄国十月 革命是新文化运动后期内容，不是主要内容；C主张社会革命不是新文化运动核心内容；D反对外来侵略并非 新文化运动重点。"},{"id":"sg-158","globalId":158,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":158,"question":"中国人民解放军在1949年4月21日发起的重大战役是（ ）。","options":["辽沈战役","淮海战役","平津战役","渡江战役"],"answer":3,"answerLetter":"D","explain":"1949年4月21日，毛泽东、朱德发布《向全国进军的命令》，人民解放军发起渡江战役。而辽沈战役 1948年9 - 11月、淮海战役1948年11月 - 1949年1月、平津战役1948年11月 - 1949年1月。答案：D。"},{"id":"sg-159","globalId":159,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":159,"question":"1925年国民政府将所辖各部队统一改编为（ ）。","options":["国民军","东征军","国民革命军","北伐军"],"answer":2,"answerLetter":"C","explain":"1925年，国民政府将所辖各部队统一改编为国民革命军，这是为了适应当时革命形势发展，建立统 一军事力量的重要举措。"},{"id":"sg-160","globalId":160,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":160,"question":"1947年11月，在香港成立的中国民主党派是（ ）。","options":["中国民主同盟","中国国民党革命委员会","中国民主促进会","中国农工民主党"],"answer":1,"answerLetter":"B","explain":"1947 年 11 月，中国国民党民主派和其他爱国民主人士第一次联合会议在香港召开。1948 年 1 月 1 日，中国国民党革命委员会正式成立，其成立地点在香港 。"},{"id":"sg-161","globalId":161,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":161,"question":"国民党军队在1946年挑起全面内战的起点是大举围攻（ ）。","options":["东北解放区","中原解放区","陕北解放区","山东解放区"],"answer":1,"answerLetter":"B","explain":"1946 年 6 月，国民党军队以进攻中原解放区为起点，挑起了全国性的内战。"},{"id":"sg-162","globalId":162,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":162,"question":"新中国第一部婚姻法颁布的时间是（ ）。","options":["1950年5月","1950年6月","1951年7月","1951年8月"],"answer":0,"answerLetter":"A","explain":"新中国第一部婚姻法于1950年5月1日颁布施行，它对有关婚姻关系的建立、夫妻间的权利和义务、 父母子女间的关系，离婚、离婚后子女的抚养和教育等内容，作了具体规定。"},{"id":"sg-163","globalId":163,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":163,"question":"中国西藏和平解放的时间是（ ）。","options":["1948年10月","1949年10月","1950年10月","1951年10月"],"answer":3,"answerLetter":"D","explain":"1951 年 5 月 23 日，中央人民政府与西藏地方政府签订《关于和平解放西藏办法的协议》，1951 年 10 月，人民解放军进驻拉萨，西藏和平解放。答案选D。"},{"id":"sg-164","globalId":164,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":164,"question":"中国资产阶级领导的旧民主主义革命终结的标志是（ ）。","options":["二次革命的失败","护国运动的失败","第一次护法运动的失败","第二次护法运动的失败"],"answer":3,"answerLetter":"D","explain":"旧民主主义革命是由资产阶级领导的。第二次护法运动的失败，表明中国旧民主主义革命陷入绝境 ，标志着中国资产阶级领导的旧民主主义革命的终结。答案选D 。"},{"id":"sg-165","globalId":165,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":165,"question":"1927年，汪精卫在武汉制造的屠杀共产党人和革命群众的事变是（ ）。","options":["四一二事变","马日事变","七一五事变","皖南事变"],"answer":2,"answerLetter":"C","explain":"1927 年 7 月 15 日，汪精卫在武汉召开“分共”会议，公开叛变革命，对共产党员和革命群众进 行大屠杀，这就是七一五事变。四一二事变是蒋介石在上海发动的；马日事变是许克祥在长沙发动的；皖南 事变发生于 1941 年。"},{"id":"sg-166","globalId":166,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":166,"question":"1948年1月，在香港正式成立的民主党派是（ ）。","options":["中国民主同盟","中国国民党革命委员会","中国民主建国会","中国农工民主党"],"answer":1,"answerLetter":"B","explain":"1948年1月，中国国民党革命委员会在香港正式成立 。中国民主同盟1941年成立；中国民主建国会 1945年成立；中国农工民主党1930年成立。答案选B。"},{"id":"sg-167","globalId":167,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":167,"question":"国民党在全国统治建立后，官僚资本的垄断活动首先和主要是（ ）。","options":["从农业方面开始的","从重工业方面开始的","从商业方面开始的","从金融业方面开始的"],"answer":3,"answerLetter":"D","explain":"国民党统治时期，官僚资本的垄断活动，首先和主要的是在金融业方面开始的。官僚资本通过控制 金融机构，滥发纸币，造成通货膨胀等，掠夺财富。"},{"id":"sg-168","globalId":168,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":168,"question":"新中国发展国民经济第一个五年计划的中心环节是（ ）。","options":["优先发展轻工业","优先发展重工业","重点发展农村经济","重点发展城市经济"],"answer":1,"answerLetter":"B","explain":"新中国第一个五年计划以“一化三改”为核心，“一化”即社会主义工业化，而实现工业化的中心 环节是优先发展重工业，因为重工业是国家工业化和国防现代化的基础。"},{"id":"sg-169","globalId":169,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":169,"question":"中国资产阶级领导的民主革命进入到一个新阶段的标志是（ ）。","options":["兴中会的成立","华兴会的成立","光复会的成立","中国同盟会的成立"],"answer":3,"answerLetter":"D","explain":"中国同盟会是近代中国第一个全国性的资产阶级革命政党，它的成立使资产阶级民主革命有了统一 的领导和明确的奋斗目标，标志着中国资产阶级领导的民主革命进入新阶段。兴中会、华兴会、光复会都是 早期的资产阶级革命团体，不具备使革命进入新阶段这一意义。"},{"id":"sg-170","globalId":170,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":170,"question":"洪秀全在广西发动金田起义的时间是（ ）。","options":["1851年","1853年","1856年","1864年"],"answer":0,"answerLetter":"A","explain":"1851年1月，洪秀全在广西金田村发动起义，建号太平天国 。所以选A。"},{"id":"sg-171","globalId":171,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":171,"question":"新中国建立初期通过没收官僚资本建立了（ ）。","options":["合作社经济","国家资本主义经济","国营经济","民族资本主义经济"],"answer":2,"answerLetter":"C","explain":"新中国建立初期没收官僚资本，将其转化为社会主义性质的国营经济，使国家掌握了经济命脉。合 作社经济是通过对个体农业、手工业改造发展而来；国家资本主义经济是对资本主义工商业改造过程中的一 种经济形式；民族资本主义经济是中国旧有的经济成分，不是通过没收官僚资本建立。"},{"id":"sg-172","globalId":172,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":172,"question":"中华人民共和国的成立标志着中国进入（ ）。","options":["资本主义社会","社会主义初级阶段","新民主主义社会","社会主义中级阶段"],"answer":2,"answerLetter":"C","explain":"新中国成立初期，中国社会的性质是新民主主义社会 。直到1956年底社会主义改造基本完成，才进 入社会主义初级阶段。资本主义社会不符合中国发展轨迹，也不存在社会主义中级阶段这种表述。"},{"id":"sg-173","globalId":173,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":173,"question":"1950年6月，中国共产党为争取国家财政经济状况的基本好转而召开的重要会议是（ ）。","options":["中共七届二中全会","中共七届三中全会","中共七届四中全会","中共七届五中全会"],"answer":1,"answerLetter":"B","explain":"1950 年 6 月召开的中共七届三中全会，确定了当时全党和全国人民的中心任务是要在三年左右的 时间内，争取国家财政经济状况的基本好转。A 选项中共七届二中全会是 1949 年召开，主要是工作重心转 移等问题；C 选项中共七届四中全会 1954 年召开；D 选项中共七届五中全会 1955 年召开。答案：B。"},{"id":"sg-174","globalId":174,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":174,"question":"将社会主义初级阶段基本路线概括为“一个中心，两个基本点”的会议是（ ）。","options":["中共十二大","中共十三大","中共十五大","中共十六大"],"answer":1,"answerLetter":"B","explain":"中共十三大系统阐述了社会主义初级阶段理论，明确概括了党在社会主义初级阶段的基本路线，即 “一个中心，两个基本点”。“一个中心”是以经济建设为中心，“两个基本点”是坚持四项基本原则，坚 持改革开放。"},{"id":"sg-175","globalId":175,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":175,"question":"鸦片战争后，提出“师夷长技以制夷”思想的是（ ）。","options":["林则徐","王韬","龚自珍","魏源"],"answer":3,"answerLetter":"D","explain":"魏源在《海国图志》中明确提出“师夷长技以制夷”思想，主张学习西方先进技术来抵御西方侵略 。"},{"id":"sg-176","globalId":176,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":176,"question":"严复1898年翻译出版的《天演论》所宣传的思想是（ ）。","options":["师夷长技以制夷","中学为体、西学为用","振兴中华","物竞天择、适者生存"],"answer":3,"answerLetter":"D","explain":"《天演论》主要宣传了达尔文的进化论思想，核心观点是“物竞天择、适者生存”。A选项“师夷长 技以制夷”是魏源在《海国图志》中提出；B选项“中学为体、西学为用”是洋务派主张；C选项“振兴中华 ”是孙中山提出。"},{"id":"sg-177","globalId":177,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":177,"question":"资本—帝国主义列强对近代中国的侵略，首先和主要进行的是（ ）。","options":["军事侵略","政治控制","经济掠夺","文化渗透"],"answer":0,"answerLetter":"A","explain":"资本—帝国主义列强侵略中国，军事侵略是最首要的手段，通过军事侵略打开中国大门，进而实现 政治控制、经济掠夺和文化渗透等。答案：A。"},{"id":"sg-178","globalId":178,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":178,"question":"严复将英国人赫胥黎的《进化与伦理》的前两章翻译为（ ）。","options":["《天演论》","《穆勒名学》","《原富》","《法意》"],"answer":0,"answerLetter":"A","explain":"严复翻译的《天演论》是将赫胥黎《进化与伦理》前两章进行编译，宣传“物竞天择，适者生存 ”思想。"},{"id":"sg-179","globalId":179,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":179,"question":"遵义会议后，中共中央政治局成立了新的三人团负责红军的军事行动，其成员是（ ）。","options":["毛泽东、朱德、周恩来","毛泽东、朱德、王稼祥","毛泽东、周恩来、王稼祥","毛泽东、张闻天、周恩来"],"answer":2,"answerLetter":"C","explain":"遵义会议后成立的新三人团成员是毛泽东、周恩来、王稼祥 。这三人在当时红军军事指挥方面发挥 了关键作用。"},{"id":"sg-180","globalId":180,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":180,"question":"1928年底，在东北宣布“遵守三民主义，服从国民政府，改易旗帜”的是（ ）。","options":["张作霖","张学良","阎锡山","杨虎城"],"answer":1,"answerLetter":"B","explain":"1928年底张学良在东北宣布“遵守三民主义，服从国民政府，改易旗帜”，史称东北易帜，至此国 民政府在形式上基本统一全国 。答案选B。"},{"id":"sg-181","globalId":181,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":181,"question":"1956年召开的中共八大指出，党和全国人民当前的主要任务是（ ）。","options":["争取国家财政经济状况的根本好转","完成社会主义改造","正确处理人民内部矛盾","把我国从落后的农业国变为先进的工业国"],"answer":3,"answerLetter":"D","explain":"中共八大正确分析了社会主义改造完成后中国社会的主要矛盾和主要任务，指出国内的主要矛盾已 经是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，是人民对于经济文化迅速发展的 需要同当前经济文化不能满足人民需要的状况之间的矛盾。党和全国人民的主要任务是集中力量发展社会生 产力，把我国尽快地从落后的农业国变为先进的工业国。"},{"id":"sg-182","globalId":182,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":182,"question":"近代中国历史上第一个资产阶级革命组织是（ ）。","options":["兴中会","中国同盟会","华兴会","光复会"],"answer":0,"answerLetter":"A","explain":"兴中会是孙中山于1894 年在檀香山建立，是近代中国第一个资产阶级革命组织。中国同盟会是近代 中国第一个全国性的资产阶级革命政党；华兴会、光复会是资产阶级革命团体但成立时间晚于兴中会。答案 ：A"},{"id":"sg-183","globalId":183,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":183,"question":"洋务派在1862年创办的翻译学堂是（ ）。","options":["京师同文馆","广方言馆","译书局","译书馆"],"answer":0,"answerLetter":"A","explain":"1862年，洋务派创办京师同文馆，它是近代中国第一所新式学堂，是翻译学堂。广方言馆创办时间 晚于京师同文馆；译书局、译书馆不属于洋务派1862年创办的翻译学堂。"},{"id":"sg-184","globalId":184,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":184,"question":"1930年5月，毛泽东撰写的关于坚持辩证唯物主义思想路线的著作是（ ）。","options":["《中国的红色政权为什么能够存在》","《井冈山的斗争》","《星星之火，可以燎原》","《反对本本主义》"],"answer":3,"answerLetter":"D","explain":"1930年5月毛泽东写的《反对本本主义》，阐明了坚持辩证唯物主义的思想路线即坚持理论与实际相 结合的原则的极端重要性，表现了毛泽东开辟新道路、创造新理论的革命首创精神。答案：D 。"},{"id":"sg-185","globalId":185,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":185,"question":"1959年，在中共中央召开的庐山会议上受到错误批判的是（ ）。","options":["刘少奇","彭德怀","周恩来","邓小平"],"answer":1,"answerLetter":"B","explain":"1959 年庐山会议原本是为了总结经验教训、调整指标、继续纠正“左”倾错误而召开，彭德怀同志 写信给毛泽东主席，对“大跃进”和人民公社化运动中的错误提出批评，却遭到错误批判。答案选B。"},{"id":"sg-186","globalId":186,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":186,"question":"近代中国派遣第一批留学生是在（ ）。","options":["洋务运动时期质","戊戌维新时期","清末“新政”时期","辛亥革命时期"],"answer":0,"answerLetter":"A","explain":"洋务运动为了培养洋务人才，1872 年到 1875 年，清政府先后选派 120 名幼童赴美留学，这是近 代中国派遣的第一批留学生 。戊戌维新时期、清末“新政”时期、辛亥革命时期均晚于洋务运动派遣留学生 时间 。"},{"id":"sg-187","globalId":187,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":187,"question":"近代中国向西方派遣第一批留学生是在（ ）。","options":["洋务运动时期","戊戌维新时期","清末“新政”时期","辛亥革命时期"],"answer":0,"answerLetter":"A","explain":"洋务运动为培养洋务人才，在19世纪70 - 90年代，先后派遣4批幼童赴美留学 ，这是近代中国向西 方派遣的第一批留学生。答案：A。"},{"id":"sg-188","globalId":188,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":188,"question":"洋务运动时期，清政府建立的新式海军的主力是（ ）。","options":["福建水师","北洋水师","南洋水师","广东水师"],"answer":1,"answerLetter":"B","explain":"洋务运动创办新式海军，其中北洋水师是清政府海军的主力，规模最大、实力最强。"},{"id":"sg-189","globalId":189,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":189,"question":"1931年11月，中国共产党在江西瑞金召开的重要会议是（ ）。","options":["中共六届四中全会","红四军第九次党的代表大会","中华苏维埃第一次全国代表大会","赣南会议"],"answer":2,"answerLetter":"C","explain":"1931年11月在江西瑞金召开的是中华苏维埃第一次全国代表大会，这次会议宣告中华苏维埃共和国 临时中央政府成立 。A选项中共六届四中全会在上海召开；B选项红四军第九次党的代表大会即古田会议，在 福建上杭古田召开；D选项赣南会议在江西瑞金召开，但时间与题干不符。"},{"id":"sg-190","globalId":190,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":190,"question":"1966年至1976年间在我国发生的全局性、长时间的“左”倾严重错误是（ ）。","options":["“大跃进”","人民公社运动","反右派斗争扩大化","“文化大革命”"],"answer":3,"answerLetter":"D","explain":"“文化大革命 ”发生于1966 - 1976 年，是一场给党、国家和各族人民带来严重灾难的内乱，造成 了全局性、长时间的 “左” 倾严重错误。“大跃进”和人民公社运动主要发生在1958 - 1960 年；反右派 斗争扩大化发生在1957 年。"},{"id":"sg-191","globalId":191,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":191,"question":"抗日战争胜利后，国共双方通过重庆谈判签订《政府与中共代表会谈纪要》的时间是（ ）。","options":["1945年8月","1945年9月","1945年10月","1945年11月"],"answer":2,"answerLetter":"C","explain":"1945 年 10 月 10 日，国共双方签订《政府与中共代表会谈纪要》即双十协定 。所以答案是C。"},{"id":"sg-192","globalId":192,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":192,"question":"以蒋介石为首的国民党南京政权建立后，官僚资本的垄断活动首先和主要是（ ）。","options":["从重工业方面开始的","从金融业方面开始的","从商业方面开始的","从农业方面开始的"],"answer":1,"answerLetter":"B","explain":"官僚资本要实现对全国经济的控制，金融是关键领域。国民党统治集团通过建立“四行二局”等金 融机构，开始其垄断活动，以此为基础进而控制其他行业。答案：B 。"},{"id":"sg-193","globalId":193,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":193,"question":"抗日战争时期，中国共产党开展的延安整风运动最主要的任务是（ ）。","options":["反对主观主义以整顿学风","反对宗派主义以整顿党风","反对官僚主义以整顿作风","反对党八股以整顿文风"],"answer":0,"answerLetter":"A","explain":"延安整风运动的主要内容是反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整 顿文风，其中最主要任务是反对主观主义整顿学风，主观主义是中国共产党内反复出现“左”、右倾错误的 思想认识根源。"},{"id":"sg-194","globalId":194,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":194,"question":"鲁迅在《新青年》上发表的第一篇白话小说是（ ）。","options":["《孔乙己》","《药》","《狂人日记》","《阿Q正传》"],"answer":2,"answerLetter":"C","explain":"鲁迅于1918年5月在《新青年》发表《狂人日记》，这是中国第一部现代白话文小说。而《孔乙己》 《药》《阿Q正传》发表时间晚于《狂人日记》。"},{"id":"sg-195","globalId":195,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":195,"question":"在1860年洗劫和烧毁圆明园的外国侵略者是（ ）。","options":["日本侵略军","俄国侵略军","英法联军","八国联军"],"answer":2,"answerLetter":"C","explain":"1860 年第二次鸦片战争期间，英法联军攻占北京后洗劫并烧毁圆明园。日本侵略军主要罪行多在甲 午战争及抗日战争期间；俄国侵略军在近代主要是割占中国大片领土；八国联军侵华是 1900 年。答案：C。"},{"id":"sg-196","globalId":196,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":196,"question":"1933年11月，在福州发动抗日反蒋事变的国民党爱国将领是（ ）。","options":["马占山和李杜","冯玉祥和吉鸿昌","蔡廷锴和蒋光鼐","张学良和杨虎城"],"answer":2,"answerLetter":"C","explain":"1933 年 11 月发动福建事变（即抗日反蒋事变）的是蔡廷锴和蒋光鼐等率领的第十九路军 。A 选 项马占山、李杜主要是在东北抗日；B 选项冯玉祥、吉鸿昌组织察哈尔民众抗日同盟军；D 选项张学良、杨 虎城发动西安事变。所以答案是C。"},{"id":"sg-197","globalId":197,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":197,"question":"1978年，我国开展的一场马克思主义思想解放运动是（ ）。","options":["揭批“四人帮”","关于真理标准问题的大讨论","平反冤假错案","关于社会主义市场经济问题的大讨论"],"answer":1,"answerLetter":"B","explain":"1978 年开展的关于真理标准问题的大讨论，是一场马克思主义思想解放运动，它打破了长期以来个 人崇拜和教条主义的束缚，为拨乱反正、开启改革开放新时期作了重要的思想准备。A 选项揭批“四人帮 ”主要是政治上批判其罪行；C 选项平反冤假错案是落实政策工作；D 选项关于社会主义市场经济问题的大 讨论在 20 世纪 90 年代。"},{"id":"sg-198","globalId":198,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":198,"question":"毛泽东《论十大关系》报告围绕的基本方针是（ ）。","options":["独立自主","自力更生为主，争取外援为辅","调动一切积极因素，为社会主义事业服务","走中国特色社会主义道路"],"answer":2,"answerLetter":"C","explain":"《论十大关系》的报告确定了一个基本方针，就是“努力把党内党外、国内国外的一切积极的因素 ，直接的、间接的积极因素全部调动起来”，为社会主义建设服务 。"},{"id":"sg-199","globalId":199,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":199,"question":"在近代中国，洋务派开展洋务运动的指导思想是（ ）。","options":["“师夷长技以制夷”","“中学为体，西学为用”","“物竞天择，适者生存”","“启迪民智，除旧布新”"],"answer":1,"answerLetter":"B","explain":"洋务派的指导思想是“中学为体，西学为用”，意思是在维护清王朝封建统治的基础上，采用西方 先进技术。A选项“师夷长技以制夷”是魏源提出，是早期向西方学习思想的萌芽，但不是洋务派指导思想 ；C选项“物竞天择，适者生存”是严复翻译《天演论》传播的思想，为维新变法提供理论依据；D选项“启 迪民智，除旧布新”与维新派等相关，强调思想启蒙等。"},{"id":"sg-200","globalId":200,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":200,"question":"1934年中国工农红军第五次反“围剿”斗争失败后，率先开始战略转移的是（ ）。","options":["红十五军团","红一方面军","红二方面军","红四方面军"],"answer":1,"answerLetter":"B","explain":"1934 年第五次反“围剿”失败后率先开始战略转移的是红一方面军，也就是中央红军，答案选B 。"},{"id":"sg-201","globalId":201,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":201,"question":"1979年，邓小平在中央理论工作务虚会上首次明确提出，必须坚持（ ）。","options":["拨乱反正","解放思想","四项基本原则","以经济建设为中心"],"answer":2,"answerLetter":"C","explain":"1979年，邓小平在中央理论工作务虚会上首次明确提出必须坚持四项基本原则。四项基本原则是立 国之本，对稳定社会秩序、推动改革开放等具有重要意义。所以答案选C。"},{"id":"sg-202","globalId":202,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":202,"question":"1979年元旦，全国人大常委会发表的重要文献是（ ）。","options":["《一个国家，两种制度》","《告台湾同胞书》","《实现两岸和平统一的九项方针》","《反国家分裂法》"],"answer":1,"answerLetter":"B","explain":"1979年元旦，全国人大常委会发表《告台湾同胞书》，郑重宣示争取祖国和平统一的大政方针。A选 项《一个国家，两种制度》是1984 年邓小平提出；C选项《实现两岸和平统一的九项方针》是1995 年江泽民 提出；D选项《反国家分裂法》是2005 年通过。答案选B。"},{"id":"sg-203","globalId":203,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":203,"question":"毛泽东系统阐明农业合作化理论的重要文献是（ ）。","options":["《介绍一个合作社》","《关于农业合作化问题》","《组织起来》","《中国农村的社会主义高潮》"],"answer":1,"answerLetter":"B","explain":"1955 年 7 月 31 日，毛泽东在省、市、自治区党委书记会议上作《关于农业合作化问题》的报告 ，系统阐述了农业合作化理论 。答案：B 。"},{"id":"sg-204","globalId":204,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":204,"question":"在抗日战争的芦淞会站中，率领“八百壮士”孤军据守四行仓库的爱国将领是（ ）。","options":["佟麟阁","赵登禹","戴安澜","谢晋元"],"answer":3,"answerLetter":"D","explain":"在淞沪会战中，率领“八百壮士”坚守四行仓库的是谢晋元。佟麟阁、赵登禹是在北平保卫战中牺 牲；戴安澜是在入缅作战中殉国。"},{"id":"sg-205","globalId":205,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":205,"question":"1935年，中国共产党提出建立抗日民族统一战线的会议是（ ）。","options":["瓦窑堡会议","洛川会议","中共六届六中全会","中共六届七中全会"],"answer":0,"answerLetter":"A","explain":"1935 年 12 月，中共中央在瓦窑堡召开政治局会议，提出了在抗日的条件下与民族资产阶级重建统 一战线的新政策，即建立抗日民族统一战线。洛川会议主要是制定全面抗战路线等；中共六届六中全会提出 “马克思主义中国化”命题等；中共六届七中全会通过《关于若干历史问题的决议》等。答案：A。"},{"id":"sg-206","globalId":206,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":206,"question":"毛泽东于1928年12月主持制定的中国共产党历史上第一个土地法是（ ）。","options":["《井冈山土地法》","《兴国土地法》","《关于清算、减租及土地问题的指示》","《中国土地法大纲》"],"answer":0,"answerLetter":"A","explain":"1928 年 12 月毛泽东在井冈山主持制定了中国共产党历史上第一个土地法即《井冈山土地法》 。B 项《兴国土地法》是 1929 年制定；C 项《关于清算、减租及土地问题的指示》1946 年发布；D 项《中国土 地法大纲》1947 年颁布。"},{"id":"sg-207","globalId":207,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":207,"question":"在抗日战争的战略防御阶段，国民党军队在正面战场上取得胜利的战役是（ ）。","options":["台儿庄战役","桂南战役","枣宜战役","中条山战役"],"answer":0,"answerLetter":"A","explain":"在抗日战争战略防御阶段，台儿庄战役是国民党军队在正面战场取得的重大胜利。它打击了日军的 嚣张气焰，振奋了全国军民的抗战信心。桂南、枣宜、中条山战役都不是发生在战略防御阶段取得胜利的战 役。"},{"id":"sg-208","globalId":208,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":208,"question":"1935年10月，中央红军同红十五军团胜利会师于（ ）。","options":["四川懋功地区","西康甘孜地区","甘肃会宁、静宁地区","陕北吴起镇"],"answer":3,"answerLetter":"D","explain":"1935 年 10 月，中央红军到达陕北吴起镇，与红十五军团胜利会师。A 选项四川懋功地区是 1935 年 6 月中央红军与红四方面军会师地；B 选项西康甘孜地区是 1936 年 7 月红二、红四方面军会师地；C 选项甘肃会宁、静宁地区是 1936 年 10 月三大主力红军会师地。答案：D。"},{"id":"sg-209","globalId":209,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":209,"question":"1988年，中共中央和国务院决定建立的经济特区是（ ）。","options":["海南经济特区","珠海经济特区","厦门经济特区","深圳经济特区"],"answer":0,"answerLetter":"A","explain":"1988年，中共中央和国务院决定建立海南经济特区 。珠海、厦门、深圳经济特区设立时间早于 1988年。答案选A。"},{"id":"sg-210","globalId":210,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":210,"question":"1935年1月，中国共产党在遵义会议上解决的主要问题是（ ）。","options":["军事和组织问题","思想和作风问题","政治和军事问题","筹款和征兵问题"],"answer":0,"answerLetter":"A","explain":"遵义会议集中全力解决当时具有决定意义的军事问题和组织问题，结束王明“左”倾教条主义在中 央的统治，确立了以毛泽东为代表的马克思主义的正确路线在中共中央的领导地位。"},{"id":"sg-211","globalId":211,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":211,"question":"1990年3月，中共十三届六中全会通过了（ ）。","options":["《关于科学技术体制改革的决定》","《关于教育体制改革的决定》","《关于加强党同人民群众联系的决定》","《关于加强党的执政能力建设的决定》"],"answer":2,"answerLetter":"C","explain":"1990年3月，中共十三届六中全会通过《关于加强党同人民群众联系的决定》 。A选项《关于科学技 术体制改革的决定》是1985年3月作出；B选项《关于教育体制改革的决定》是1985年5月作出；D选项《关于 加强党的执政能力建设的决定》是2004年9月中共十六届四中全会通过。"},{"id":"sg-212","globalId":212,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":212,"question":"毛泽东在1957年指出，我国国家政治生活的主题是正确处理（ ）。","options":["敌我矛盾","人民内部矛盾","生产关系与生产力的矛盾","上层建筑与经济基础的矛盾"],"answer":1,"answerLetter":"B","explain":"1957 年毛泽东发表《关于正确处理人民内部矛盾的问题》，指出在社会主义制度下，人民的根本利 益是一致的，但还存在着敌我矛盾和人民内部矛盾，国家政治生活的主题是正确处理人民内部矛盾。答案选 B。"},{"id":"sg-213","globalId":213,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":213,"question":"在中共八大上，陈云提出的重要思想是（ ）。","options":["双重监督","“三个主体，三个补充”","健全法制","“两条腿”走路"],"answer":1,"answerLetter":"B","explain":"在中共八大上，陈云提出了“三个主体，三个补充”的思想，即国家经营和集体经营是主体，一定 数量的个体经营为补充；计划生产是主体，一定范围的自由生产为补充；国家市场是主体，一定范围的自由 市场为补充 。"},{"id":"sg-214","globalId":214,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":214,"question":"1935年中国共产党北平临时工作委员会领导发动的抗日救亡运动是是（ ）。","options":["五卅运动","一二·九运动","一二·一运动","一二·三零运动"],"answer":1,"answerLetter":"B","explain":"1935 年，在民族危机日益加深的形势下，中国共产党北平临时工作委员会领导发动了一二·九运动 ，这是一场大规模的抗日救亡运动。五卅运动发生于 1925 年；一二·一运动是 1945 年发生在昆明的反内 战、争民主运动；不存在一二·三零运动。答案：B。"},{"id":"sg-215","globalId":215,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":215,"question":"在中国近代史上，资产阶级思想和封建主义思想的第一次正面交锋是（ ）。","options":["洋务派与顽固派的论战","洋务派与维新派的论战","维新派与守旧派的论战","革命派与改良派的论战"],"answer":2,"answerLetter":"C","explain":"维新派与守旧派的论战，实质是资产阶级思想与封建主义思想在中国的第一次正面交锋 。论战涉及 要不要变法，要不要兴民权、设议院、实行君主立宪，要不要废八股、改科举和兴西学等问题，传播了新思 想。A选项洋务派与顽固派论战围绕是否学习西方科技等，本质都维护封建统治；B选项洋务派与维新派不是 思想正面交锋；D选项革命派与改良派论战在维新派与守旧派论战后，是资产阶级内部不同政治主张的较量。"},{"id":"sg-216","globalId":216,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":216,"question":"1936年10月，中国工农红军第一、二、四方面军胜利会师于（ ）。","options":["陕北保安地区","陕北洛川地区","陕北瓦窑堡地区","甘肃会宁、静宁地区"],"answer":3,"answerLetter":"D","explain":"1936年10月，红二、红四方面军先后同红一方面军在甘肃会宁、静宁及将台堡地区会师，标志着长 征胜利结束。所以答案是D。"},{"id":"sg-217","globalId":217,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":217,"question":"早在1836年就扬言要用武力打开中国门的是（ ）。","options":["国驻华商务监督义律","美国驻华公使田贝","德国传教士郭士立","法国传教士孟振生"],"answer":0,"answerLetter":"A","explain":"1836 年，英国驻华商务监督义律扬言要用武力打开中国国门，这与英国当时企图通过鸦片贸易扭转 贸易逆差，进而打开中国市场，进行殖民扩张的背景相关。答案：A 。"},{"id":"sg-218","globalId":218,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":218,"question":"清王朝由强盛转向衰落是在（ ）。","options":["乾隆朝后期","嘉庆朝中期","咸丰朝后期","同治朝中期"],"answer":0,"answerLetter":"A","explain":"乾隆朝后期，清朝统治由盛转衰，政治上吏治腐败，经济上土地兼并严重，军事上军备废弛等各种 社会矛盾加剧。答案选A。"},{"id":"sg-219","globalId":219,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":219,"question":"正式提出以人为本、全面协调可持续的科学发展观的会议是（ ）。","options":["中共十五届五中全会","中共十五届六中全会","中共十六届三中全会","中共十六届四中全会"],"answer":2,"answerLetter":"C","explain":"2003 年 10 月，中共十六届三中全会正式提出以人为本、全面协调可持续的科学发展观。答案选 C。"},{"id":"sg-220","globalId":220,"type":"shigang","category":"史纲专项 · 中国近现代史纲要","num":220,"question":"19世纪60年代，洋务派最早从事的洋务事业是（ ）。","options":["兴办民用工业","创立新式学堂","派遣留学生","兴办军用工业"],"answer":3,"answerLetter":"D","explain":"19世纪60年代，洋务派以“自强”为旗号，最早从事的洋务事业是兴办军用工业，目的是增强军事 力量，抵御外侮。所以答案是D。"}]);

if (typeof module !== 'undefined' && module.exports) {
  module.exports = SHIGANG_CHOICE_DATA;
}
